// The files are embedded below
const F={"package.json":"{\n  \"name\": \"lfc-bot\",\n  \"version\": \"1.0.0\",\n  \"description\": \"Legacy Football Championship - Discord Bot for Roblox Football League Management\",\n  \"main\": \"dist/index.js\",\n  \"type\": \"module\",\n  \"scripts\": {\n    \"build\": \"prisma generate && tsc\",\n    \"start\": \"prisma db push && tsx src/index.ts\",\n    \"dev\": \"tsx watch src/index.ts\",\n    \"postinstall\": \"prisma generate\",\n    \"prisma:generate\": \"prisma generate\",\n    \"prisma:push\": \"prisma db push\",\n    \"prisma:migrate\": \"prisma migrate dev\",\n    \"prisma:studio\": \"prisma studio\",\n    \"deploy:commands\": \"tsx src/deploy-commands.ts\"\n  },\n  \"dependencies\": {\n    \"@prisma/client\": \"^6.6.0\",\n    \"discord.js\": \"^14.18.0\",\n    \"dotenv\": \"^16.4.7\"\n  },\n  \"devDependencies\": {\n    \"@types/node\": \"^22.13.0\",\n    \"prisma\": \"^6.6.0\",\n    \"tsx\": \"^4.19.0\",\n    \"typescript\": \"^5.7.0\"\n  }\n}",".env":"# Discord Bot\nDISCORD_TOKEN=MTUzMTQ1OTMyNDc4NDgwMzk1MA.GFgg1s.YEX-vawQ6VU1jN6IXar91L6k-HGuU-rp4cCdv8\nCLIENT_ID=1531459324784803950\nGUILD_ID=1528366297161797672\n\n# Database\nDATABASE_URL=postgresql://neondb_owner:npg_c7kYfv1nldUp@ep-late-smoke-za1jl7uh.c-2.eu-west-2.aws.neon.tech/neondb?sslmode=require\n\n# Bot Configuration\nBOT_NAME=Legacy Football Championship\nBOT_PREFIX=/","prisma/schema.prisma":"generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ─── USER ────────────────────────────────────────────────────────────────────\n\nmodel DiscordUser {\n  id            String   @id @default(cuid())\n  discordId     String   @unique\n  username      String\n  globalName    String?\n  avatarUrl     String?\n  joinedAt      DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  player        Player?\n  teamsManaged  Team[]    @relation(\"TeamManager\")\n  refereedMatches Match[] @relation(\"MatchReferee\")\n  warnings      Warning[]\n  suspensions   Suspension[]\n\n  @@map(\"discord_users\")\n}\n\n// ─── PLAYER ──────────────────────────────────────────────────────────────────\n\nmodel Player {\n  id            String   @id @default(cuid())\n  lfcId         String   @unique\n  discordId     String   @unique\n  robloxUsername String?  // Roblox username for verification\n  robloxId      String?   // Roblox user ID\n  nickname      String?   // Auto-nickname assigned on contract\n  position      String   // Goalkeeper, Defender, Midfielder, Forward\n  region        String   // Europe, Asia, Africa, etc.\n  joinedAt      DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  user          DiscordUser @relation(fields: [discordId], references: [discordId])\n  teamId        String?\n  team          Team?       @relation(\"TeamPlayers\", fields: [teamId], references: [id])\n  roleInTeam    String?     // Captain, Vice Captain, Starter, Sub, Academy\n\n  // Career stats\n  goals         Int      @default(0)\n  assists       Int      @default(0)\n  saves         Int      @default(0)   // Goalkeeper specific\n  mvps          Int      @default(0)\n  appearances   Int      @default(0)\n  yellowCards   Int      @default(0)\n  redCards      Int      @default(0)\n  cleanSheets   Int      @default(0)   // Goalkeeper specific\n\n  trophies      Int      @default(0)\n  awards        Award[]\n\n  // Season-specific stats\n  seasonStats   PlayerSeasonStats[]\n\n  // Match participation\n  matchGoals    MatchGoal[]\n  matchAssists  MatchAssist[]\n  matchMvps     MatchMvp[]\n\n  // Contract & transfer history\n  contracts     Contract[]\n  transfersFrom Transfer[] @relation(\"FromPlayer\")\n  transfersTo   Transfer[] @relation(\"ToPlayer\")\n\n  // Lineup participation\n  lineups       LineupPlayer[]\n\n  @@map(\"players\")\n}\n\nmodel PlayerSeasonStats {\n  id          String @id @default(cuid())\n  playerId    String\n  seasonId    String\n  goals       Int    @default(0)\n  assists     Int    @default(0)\n  saves       Int    @default(0)\n  mvps        Int    @default(0)\n  appearances Int    @default(0)\n  yellowCards Int    @default(0)\n  redCards    Int    @default(0)\n  cleanSheets Int    @default(0)\n\n  player      Player @relation(fields: [playerId], references: [id])\n  season      Season @relation(fields: [seasonId], references: [id])\n\n  @@unique([playerId, seasonId])\n  @@map(\"player_season_stats\")\n}\n\n// ─── TEAM ────────────────────────────────────────────────────────────────────\n\nmodel Team {\n  id            String      @id @default(cuid())\n  name          String      @unique\n  shortName     String?     // e.g. \"LFC\"\n  logoUrl       String?\n  description   String?\n  managerId     String\n  manager       DiscordUser @relation(\"TeamManager\", fields: [managerId], references: [id])\n  createdAt     DateTime    @default(now())\n  updatedAt     DateTime    @updatedAt\n\n  players       Player[]    @relation(\"TeamPlayers\")\n\n  // Season records\n  seasonTeams   TeamSeasonStats[]\n\n  // Home and away matches\n  homeMatches   Match[]     @relation(\"HomeTeam\")\n  awayMatches   Match[]     @relation(\"AwayTeam\")\n\n  trophies      Int         @default(0)\n\n  @@map(\"teams\")\n}\n\nmodel TeamSeasonStats {\n  id          String  @id @default(cuid())\n  teamId      String\n  seasonId    String\n  played      Int     @default(0)\n  wins        Int     @default(0)\n  draws       Int     @default(0)\n  losses      Int     @default(0)\n  goalsFor    Int     @default(0)\n  goalsAgainst Int    @default(0)\n  points      Int     @default(0)\n\n  team        Team    @relation(fields: [teamId], references: [id])\n  season      Season  @relation(fields: [seasonId], references: [id])\n\n  @@unique([teamId, seasonId])\n  @@map(\"team_season_stats\")\n}\n\n// ─── SEASON ──────────────────────────────────────────────────────────────────\n\nmodel Season {\n  id          String   @id @default(cuid())\n  name        String   @unique // e.g. \"Season 1\", \"Season 2\"\n  isActive    Boolean  @default(false)\n  startedAt   DateTime?\n  endedAt     DateTime?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  matches     Match[]\n  playerStats PlayerSeasonStats[]\n  teamStats   TeamSeasonStats[]\n  awards      Award[]\n\n  @@map(\"seasons\")\n}\n\n// ─── MATCH ───────────────────────────────────────────────────────────────────\n\nmodel Match {\n  id          String   @id @default(cuid())\n  matchNumber Int?\n  matchweek   Int?      // Week/fixture number\n  homeTeamId  String\n  awayTeamId  String\n  homeScore   Int      @default(0)\n  awayScore   Int      @default(0)\n  status      String   @default(\"Scheduled\") // Scheduled, Live, Finished, Postponed, Forfeit\n  matchDate   DateTime?\n  refereeId   String?\n  referee     DiscordUser? @relation(\"MatchReferee\", fields: [refereeId], references: [id])\n  seasonId    String\n  season      Season   @relation(fields: [seasonId], references: [id])\n  threadId    String?   // Discord thread ID for live match\n  forfeit     Boolean  @default(false)\n  forfeitingTeam String? // \"home\" or \"away\" — who forfeited\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  homeTeam    Team     @relation(\"HomeTeam\", fields: [homeTeamId], references: [id])\n  awayTeam    Team     @relation(\"AwayTeam\", fields: [awayTeamId], references: [id])\n\n  goals       MatchGoal[]\n  assists     MatchAssist[]\n  mvps        MatchMvp[]\n  cards       MatchCard[]\n  lineups     Lineup[]\n  lineupsP    LineupPlayer[]\n  disputes    Dispute[]\n  predictions Prediction[]\n  motmPoll    MotmPoll[]\n  motmVotes   MotmVote[]\n\n  @@map(\"matches\")\n}\n\nmodel MatchGoal {\n  id       String @id @default(cuid())\n  matchId  String\n  playerId String\n  minute   Int?\n  isOwnGoal Boolean @default(false)\n\n  match    Match  @relation(fields: [matchId], references: [id])\n  player   Player @relation(fields: [playerId], references: [id])\n\n  @@map(\"match_goals\")\n}\n\nmodel MatchAssist {\n  id       String @id @default(cuid())\n  matchId  String\n  playerId String\n  minute   Int?\n\n  match    Match  @relation(fields: [matchId], references: [id])\n  player   Player @relation(fields: [playerId], references: [id])\n\n  @@map(\"match_assists\")\n}\n\nmodel MatchMvp {\n  id       String @id @default(cuid())\n  matchId  String @unique\n  playerId String\n  reason   String?\n\n  match    Match  @relation(fields: [matchId], references: [id])\n  player   Player @relation(fields: [playerId], references: [id])\n\n  @@map(\"match_mvps\")\n}\n\nmodel MatchCard {\n  id       String @id @default(cuid())\n  matchId  String\n  playerId String\n  type     String // Yellow, Red\n  minute   Int?\n  reason   String?\n\n  match    Match  @relation(fields: [matchId], references: [id])\n  player   Player @relation(fields: [playerId], references: [id])\n\n  @@map(\"match_cards\")\n}\n\n// ─── AWARD ───────────────────────────────────────────────────────────────────\n\nmodel Award {\n  id        String   @id @default(cuid())\n  type      String   // Golden Boot, Golden Boy, Best Playmaker, etc.\n  playerId  String\n  seasonId  String\n  reason    String?\n  awardedAt DateTime @default(now())\n\n  player    Player   @relation(fields: [playerId], references: [id])\n  season    Season   @relation(fields: [seasonId], references: [id])\n\n  @@unique([playerId, seasonId, type])\n  @@map(\"awards\")\n}\n\n// ─── TRANSFER ────────────────────────────────────────────────────────────────\n\nmodel Transfer {\n  id            String   @id @default(cuid())\n  playerId      String\n  fromTeamId    String?\n  toTeamId      String?\n  fromTeamName  String?\n  toTeamName    String?\n  fee           Int?     // Transfer fee (in millions or currency unit)\n  status        String   @default(\"Pending\") // Pending, Completed, Cancelled\n  completedAt   DateTime?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  player        Player   @relation(\"FromPlayer\", fields: [playerId], references: [id])\n\n  @@map(\"transfers\")\n}\n\n// ─── WARNINGS & SUSPENSIONS ──────────────────────────────────────────────────\n\nmodel Warning {\n  id        String   @id @default(cuid())\n  userId    String\n  reason    String\n  issuedBy  String   // Discord ID of who issued\n  createdAt DateTime @default(now())\n\n  user      DiscordUser @relation(fields: [userId], references: [id])\n\n  @@map(\"warnings\")\n}\n\nmodel Suspension {\n  id        String   @id @default(cuid())\n  userId    String\n  reason    String\n  issuedBy  String\n  expiresAt DateTime?\n  active    Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user      DiscordUser @relation(fields: [userId], references: [id])\n\n  @@map(\"suspensions\")\n}\n\nmodel Blacklist {\n  id        String   @id @default(cuid())\n  discordId String   @unique\n  reason    String\n  issuedBy  String\n  createdAt DateTime @default(now())\n\n  @@map(\"blacklist\")\n}\n\n// ─── GUILD CONFIG ────────────────────────────────────────────────────────────\n\nmodel GuildConfig {\n  id          String   @id @default(cuid())\n  guildId     String   @unique\n  newsChannelId String?\n  staffRoleId   String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@map(\"guild_config\")\n}\n\n// ─── NEWS / ANNOUNCEMENTS ────────────────────────────────────────────────────\n\nmodel NewsArticle {\n  id        String   @id @default(cuid())\n  guildId   String\n  type      String   // match_result, transfer, award, season, milestone, broadcast\n  title     String\n  content   String   @db.Text\n  imageUrl  String?\n  messageId String?\n  channelId String?\n  createdAt DateTime @default(now())\n\n  @@map(\"news_articles\")\n}\n\n// ─── CONTRACT ────────────────────────────────────────────────────────────────\n\nmodel Contract {\n  id            String   @id @default(cuid())\n  playerId      String\n  teamId        String\n  teamName      String   @default(\"\")\n  roleInTeam    String?  // Captain, Vice Captain, Starter, Sub, Academy\n  signedAt      DateTime @default(now())\n  expiresAt     DateTime?\n  isActive      Boolean  @default(true)\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  player        Player   @relation(fields: [playerId], references: [id])\n  team          Team     @relation(fields: [teamId], references: [id])\n\n  @@map(\"contracts\")\n}\n\n// ─── LINEUP ──────────────────────────────────────────────────────────────────\n\nmodel Lineup {\n  id            String   @id @default(cuid())\n  matchId       String\n  teamId        String\n  captainId     String?\n  formation     String?  // e.g. \"4-4-2\", \"4-3-3\"\n  submittedAt   DateTime @default(now())\n  isConfirmed   Boolean  @default(false)\n\n  match         Match    @relation(fields: [matchId], references: [id])\n  team          Team     @relation(fields: [teamId], references: [id])\n  players       LineupPlayer[]\n\n  @@map(\"lineups\")\n}\n\nmodel LineupPlayer {\n  id       String  @id @default(cuid())\n  lineupId String\n  playerId String\n  position String? // The position in the lineup (GK, LB, CB, CM, ST, etc.)\n  isBench  Boolean @default(false)\n  order    Int     @default(0) // Display order\n\n  lineup   Lineup  @relation(fields: [lineupId], references: [id])\n  player   Player  @relation(fields: [playerId], references: [id])\n  match    Match   @relation(fields: [matchId], references: [id])\n\n  @@map(\"lineup_players\")\n}\n\n// ─── DISPUTE ─────────────────────────────────────────────────────────────────\n\nmodel Dispute {\n  id            String   @id @default(cuid())\n  matchId       String\n  reporterId    String   // Discord ID\n  reason        String   @db.Text\n  evidenceUrl   String?  // Link to clip/screenshot evidence\n  status        String   @default(\"Open\") // Open, Under Review, Resolved, Dismissed\n  resolvedBy    String?  // Discord ID of who resolved\n  resolution    String?  // Resolution notes\n  ticketChannelId String? // Discord channel ID for the ticket\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  match         Match    @relation(fields: [matchId], references: [id])\n\n  @@map(\"disputes\")\n}\n\n// ─── PREDICTION ──────────────────────────────────────────────────────────────\n\nmodel Prediction {\n  id              String   @id @default(cuid())\n  matchId         String\n  userId          String   // Discord ID of predictor\n  predictedTeamId String   // Which team they predict will win (or null for draw)\n  predictedDraw   Boolean  @default(false)\n  points          Int      @default(0)\n  resolved        Boolean  @default(false)\n  createdAt       DateTime @default(now())\n\n  match           Match    @relation(fields: [matchId], references: [id])\n\n  @@unique([matchId, userId])\n  @@map(\"predictions\")\n}\n\n// ─── WEEKLY AWARDS ──────────────────────────────────────────────────────────\n\nmodel WeeklyAward {\n  id          String   @id @default(cuid())\n  type        String   // potw (Player of Week), totw (Team of Week)\n  playerId    String?\n  teamId      String?\n  seasonId    String\n  weekNumber  Int\n  reason      String?\n  awardedAt   DateTime @default(now())\n\n  season      Season   @relation(fields: [seasonId], references: [id])\n  player      Player?  @relation(fields: [playerId], references: [id])\n\n  @@map(\"weekly_awards\")\n}\n\n// ─── MOTM (Man of the Match) Poll ───────────────────────────────────────────\n\nmodel MotmPoll {\n  id        String   @id @default(cuid())\n  matchId   String   @unique\n  messageId String?  // Discord message ID of the poll\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n\n  match     Match    @relation(fields: [matchId], references: [id])\n  votes     MotmVote[]\n\n  @@map(\"motm_polls\")\n}\n\nmodel MotmVote {\n  id        String   @id @default(cuid())\n  pollId    String\n  voterId   String   // Discord ID of voter\n  playerId  String   // Player they voted for\n  createdAt DateTime @default(now())\n\n  poll      MotmPoll @relation(fields: [pollId], references: [id])\n  player    Player   @relation(fields: [playerId], references: [id])\n\n  @@unique([pollId, voterId])\n  @@map(\"motm_votes\")\n}","src/index.ts":"import { Client, GatewayIntentBits, Collection, Events } from \"discord.js\";\nimport \"dotenv/config\";\nimport { prisma } from \"./database/prisma.js\";\nimport { loadCommands } from \"./utils/commandLoader.js\";\nimport { loadEvents } from \"./utils/eventLoader.js\";\nimport type { ExtendedClient } from \"./types/index.js\";\n\nconst client = new Client({\n  intents: [\n    GatewayIntentBits.Guilds,\n    GatewayIntentBits.GuildMembers,\n    GatewayIntentBits.GuildMessages,\n    GatewayIntentBits.MessageContent,\n  ],\n}) as ExtendedClient;\n\nclient.commands = new Collection();\n\nasync function bootstrap() {\n  try {\n    // Connect to database\n    await prisma.$connect();\n    console.log(\"[Database] Connected to PostgreSQL successfully.\");\n\n    // Load commands\n    await loadCommands(client);\n    console.log(\"[Commands] All commands loaded.\");\n\n    // Load events\n    await loadEvents(client);\n    console.log(\"[Events] All events loaded.\");\n\n    // Login to Discord\n    await client.login(process.env.DISCORD_TOKEN);\n    console.log(`[Bot] Logged in as ${client.user?.tag}`);\n  } catch (error) {\n    console.error(\"[Fatal] Failed to start bot:\", error);\n    process.exit(1);\n  }\n}\n\n// Graceful shutdown\nprocess.on(\"SIGINT\", async () => {\n  console.log(\"\\n[Shutdown] Shutting down gracefully...\");\n  await prisma.$disconnect();\n  client.destroy();\n  process.exit(0);\n});\n\nprocess.on(\"SIGTERM\", async () => {\n  console.log(\"\\n[Shutdown] Shutting down gracefully...\");\n  await prisma.$disconnect();\n  client.destroy();\n  process.exit(0);\n});\n\nbootstrap();","src/deploy-commands.ts":"import { REST, Routes } from \"discord.js\";\nimport \"dotenv/config\";\nimport { readdirSync } from \"fs\";\nimport { join, dirname } from \"path\";\nimport { fileURLToPath } from \"url\";\n\nconst __filename = fileURLToPath(import.meta.url);\nconst __dirname = dirname(__filename);\n\nconst commands: unknown[] = [];\n\nasync function loadCommandsForDeploy() {\n  const commandsPath = join(__dirname, \"commands\");\n  const categories = readdirSync(commandsPath);\n\n  for (const category of categories) {\n    const categoryPath = join(commandsPath, category);\n    const stat = await import(\"fs\").then((fs) => fs.promises.stat(categoryPath));\n\n    if (!stat.isDirectory()) continue;\n\n    const commandFiles = readdirSync(categoryPath).filter(\n      (file) => file.endsWith(\".ts\") || file.endsWith(\".js\")\n    );\n\n    for (const file of commandFiles) {\n      const filePath = join(categoryPath, file);\n      try {\n        const commandModule = await import(filePath);\n        const command = commandModule.default;\n        if (command?.data) {\n          commands.push(command.data.toJSON());\n          console.log(`[Deploy] Loaded /${command.data.name}`);\n        }\n      } catch (error) {\n        console.error(`[Deploy] Failed to load ${file}:`, error);\n      }\n    }\n  }\n}\n\nasync function deploy() {\n  const token = process.env.DISCORD_TOKEN;\n  const clientId = process.env.CLIENT_ID;\n  const guildId = process.env.GUILD_ID;\n\n  if (!token || !clientId) {\n    console.error(\"Missing DISCORD_TOKEN or CLIENT_ID in environment.\");\n    process.exit(1);\n  }\n\n  await loadCommandsForDeploy();\n\n  const rest = new REST({ version: \"10\" }).setToken(token);\n\n  try {\n    console.log(`[Deploy] Registering ${commands.length} commands...`);\n\n    let data: unknown;\n\n    if (guildId) {\n      // Guild-specific (faster for development)\n      data = await rest.put(\n        Routes.applicationGuildCommands(clientId, guildId),\n        { body: commands }\n      );\n      console.log(`[Deploy] Registered ${(data as unknown[]).length} guild commands.`);\n    } else {\n      // Global commands (up to 1 hour propagation)\n      data = await rest.put(\n        Routes.applicationCommands(clientId),\n        { body: commands }\n      );\n      console.log(`[Deploy] Registered ${(data as unknown[]).length} global commands.`);\n    }\n  } catch (error) {\n    console.error(\"[Deploy] Failed:\", error);\n    process.exit(1);\n  }\n}\n\ndeploy();","src/types/index.ts":"import type {\n  Client,\n  Collection,\n  CommandInteraction,\n  SlashCommandBuilder,\n  SlashCommandSubcommandsOnlyBuilder,\n  SlashCommandOptionsOnlyBuilder,\n  PermissionResolvable,\n} from \"discord.js\";\n\nexport interface Command {\n  data:\n    | SlashCommandBuilder\n    | SlashCommandSubcommandsOnlyBuilder\n    | SlashCommandOptionsOnlyBuilder;\n  execute: (interaction: CommandInteraction) => Promise<void>;\n  cooldown?: number;\n  permissions?: PermissionResolvable[];\n  category?: string;\n}\n\nexport interface ExtendedClient extends Client {\n  commands: Collection<string, Command>;\n}\n\nexport interface PlayerStats {\n  goals: number;\n  assists: number;\n  saves: number;\n  mvps: number;\n  appearances: number;\n  yellowCards: number;\n  redCards: number;\n  cleanSheets: number;\n}\n\nexport interface SeasonStats extends PlayerStats {\n  seasonId: string;\n  seasonName: string;\n}\n\nexport interface LeagueStanding {\n  teamId: string;\n  teamName: string;\n  played: number;\n  wins: number;\n  draws: number;\n  losses: number;\n  goalsFor: number;\n  goalsAgainst: number;\n  goalDifference: number;\n  points: number;\n}\n\nexport type Position =\n  | \"Goalkeeper\"\n  | \"Defender\"\n  | \"Midfielder\"\n  | \"Forward\";\n\nexport type Region =\n  | \"Europe\"\n  | \"Asia\"\n  | \"Africa\"\n  | \"North America\"\n  | \"South America\"\n  | \"Oceania\";\n\nexport type AwardType =\n  | \"Golden Boot\"\n  | \"Golden Boy\"\n  | \"Best Playmaker\"\n  | \"Player of the Season\"\n  | \"Team of the Season\"\n  | \"Manager of the Season\"\n  | \"Golden Glove\";\n\nexport type TransferStatus = \"Pending\" | \"Completed\" | \"Cancelled\";\n\nexport type MatchStatus = \"Scheduled\" | \"Live\" | \"Finished\" | \"Postponed\" | \"Forfeit\";\n\nexport type TeamRole = \"Captain\" | \"Vice Captain\" | \"Starter\" | \"Sub\" | \"Academy\";\n\nexport type Formation = \"4-4-2\" | \"4-3-3\" | \"3-5-2\" | \"4-2-3-1\" | \"5-3-2\" | \"4-1-4-1\" | \"3-4-3\";","src/database/prisma.ts":"import { PrismaClient } from \"@prisma/client\";\n\nconst globalForPrisma = globalThis as unknown as {\n  prisma: PrismaClient | undefined;\n};\n\nexport const prisma =\n  globalForPrisma.prisma ??\n  new PrismaClient({\n    log:\n      process.env.NODE_ENV === \"development\"\n        ? [\"query\", \"warn\", \"error\"]\n        : [\"warn\", \"error\"],\n  });\n\nif (process.env.NODE_ENV !== \"production\") {\n  globalForPrisma.prisma = prisma;\n}","src/utils/commandLoader.ts":"import { readdirSync } from \"fs\";\nimport { join, dirname } from \"path\";\nimport { fileURLToPath } from \"url\";\nimport type { ExtendedClient, Command } from \"../types/index.js\";\n\nconst __filename = fileURLToPath(import.meta.url);\nconst __dirname = dirname(__filename);\n\nexport async function loadCommands(client: ExtendedClient): Promise<void> {\n  const commandsPath = join(__dirname, \"..\", \"commands\");\n  const categories = readdirSync(commandsPath);\n\n  for (const category of categories) {\n    const categoryPath = join(commandsPath, category);\n    const stat = await import(\"fs\").then((fs) => fs.promises.stat(categoryPath));\n\n    if (!stat.isDirectory()) continue;\n\n    const commandFiles = readdirSync(categoryPath).filter(\n      (file) => file.endsWith(\".ts\") || file.endsWith(\".js\")\n    );\n\n    for (const file of commandFiles) {\n      const filePath = join(categoryPath, file);\n      try {\n        const commandModule = await import(filePath);\n        const command = commandModule.default as Command;\n\n        if (!command?.data?.name || !command?.execute) {\n          console.warn(`[Warning] Command at ${filePath} missing \"data\" or \"execute\".`);\n          continue;\n        }\n\n        client.commands.set(command.data.name, command);\n        console.log(`[Commands] Loaded /${command.data.name} (${category})`);\n      } catch (error) {\n        console.error(`[Error] Failed to load command at ${filePath}:`, error);\n      }\n    }\n  }\n}","src/utils/eventLoader.ts":"import { readdirSync } from \"fs\";\nimport { join, dirname } from \"path\";\nimport { fileURLToPath } from \"url\";\nimport type { ExtendedClient } from \"../types/index.js\";\n\nconst __filename = fileURLToPath(import.meta.url);\nconst __dirname = dirname(__filename);\n\nexport async function loadEvents(client: ExtendedClient): Promise<void> {\n  const eventsPath = join(__dirname, \"..\", \"events\");\n  const eventFiles = readdirSync(eventsPath).filter(\n    (file) => file.endsWith(\".ts\") || file.endsWith(\".js\")\n  );\n\n  for (const file of eventFiles) {\n    const filePath = join(eventsPath, file);\n    try {\n      const eventModule = await import(filePath);\n      const event = eventModule.default;\n\n      if (!event?.name || !event?.execute) {\n        console.warn(`[Warning] Event at ${filePath} missing \"name\" or \"execute\".`);\n        continue;\n      }\n\n      if (event.once) {\n        client.once(event.name, (...args: unknown[]) => event.execute(...args));\n      } else {\n        client.on(event.name, (...args: unknown[]) => event.execute(...args));\n      }\n\n      console.log(`[Events] Loaded ${event.name}`);\n    } catch (error) {\n      console.error(`[Error] Failed to load event at ${filePath}:`, error);\n    }\n  }\n}","src/utils/helpers.ts":"import {\n  EmbedBuilder,\n  ColorResolvable,\n  CommandInteraction,\n  GuildMember,\n} from \"discord.js\";\n\nconst PRIMARY_COLOR: ColorResolvable = \"#00AA00\";\nconst ERROR_COLOR: ColorResolvable = \"#FF0000\";\nconst WARNING_COLOR: ColorResolvable = \"#FFAA00\";\n\nexport function createEmbed(\n  title: string,\n  description?: string,\n  color: ColorResolvable = PRIMARY_COLOR\n): EmbedBuilder {\n  return new EmbedBuilder()\n    .setTitle(title)\n    .setDescription(description ?? null)\n    .setColor(color)\n    .setTimestamp();\n}\n\nexport function createSuccessEmbed(title: string, description?: string): EmbedBuilder {\n  return createEmbed(title, description, \"#00AA00\");\n}\n\nexport function createErrorEmbed(title: string, description?: string): EmbedBuilder {\n  return createEmbed(title, description, ERROR_COLOR);\n}\n\nexport function createWarningEmbed(title: string, description?: string): EmbedBuilder {\n  return createEmbed(title, description, WARNING_COLOR);\n}\n\nexport function getMember(interaction: CommandInteraction): GuildMember | null {\n  return interaction.member as GuildMember | null;\n}\n\nexport function formatDate(date: Date | null | undefined): string {\n  if (!date) return \"N/A\";\n  return date.toLocaleDateString(\"en-US\", {\n    year: \"numeric\",\n    month: \"short\",\n    day: \"numeric\",\n  });\n}\n\nexport function formatSeasonStats(stats: {\n  goals: number;\n  assists: number;\n  saves?: number;\n  mvps: number;\n  appearances: number;\n  yellowCards?: number;\n  redCards?: number;\n  cleanSheets?: number;\n}): string {\n  const parts = [\n    `⚽ Goals: ${stats.goals}`,\n    `🎯 Assists: ${stats.assists}`,\n    `🏆 MVPs: ${stats.mvps}`,\n    `📋 Appearances: ${stats.appearances}`,\n  ];\n  if (stats.saves !== undefined && stats.saves > 0) {\n    parts.push(`🧤 Saves: ${stats.saves}`);\n  }\n  if (stats.cleanSheets !== undefined && stats.cleanSheets > 0) {\n    parts.push(`🧹 Clean Sheets: ${stats.cleanSheets}`);\n  }\n  if (stats.yellowCards !== undefined) {\n    parts.push(`🟨 Yellow Cards: ${stats.yellowCards}`);\n  }\n  if (stats.redCards !== undefined) {\n    parts.push(`🟥 Red Cards: ${stats.redCards}`);\n  }\n  return parts.join(\"\\n\");\n}\n\nexport function generateLfcId(discordId: string): string {\n  // Generate a unique LFC ID\n  const hash = Array.from(discordId)\n    .reduce((acc, char) => acc + char.charCodeAt(0), 0)\n    .toString(16)\n    .toUpperCase()\n    .slice(0, 6);\n  return `LFC-${hash}`;\n}","src/utils/permissions.ts":"import type { CommandInteraction, GuildMember } from \"discord.js\";\n\nexport enum RoleType {\n  Founder = \"founder\",\n  LeagueManagement = \"league-management\",\n  Moderator = \"moderator\",\n  Referee = \"referee\",\n}\n\nconst ROLE_NAMES: Record<RoleType, string[]> = {\n  [RoleType.Founder]: [\"Founder\", \"Owner\", \"LFC Founder\"],\n  [RoleType.LeagueManagement]: [\"League Management\", \"League Admin\", \"Commissioner\"],\n  [RoleType.Moderator]: [\"Moderator\", \"Mod\", \"Staff\"],\n  [RoleType.Referee]: [\"Referee\", \"Match Official\", \"Ref\"],\n};\n\nexport function hasRole(\n  member: GuildMember | null,\n  roleType: RoleType\n): boolean {\n  if (!member) return false;\n  const allowedNames = ROLE_NAMES[roleType];\n  return member.roles.cache.some((role) =>\n    allowedNames.some(\n      (name) => role.name.toLowerCase() === name.toLowerCase()\n    )\n  );\n}\n\nexport function hasAnyStaffRole(member: GuildMember | null): boolean {\n  if (!member) return false;\n  return Object.values(RoleType).some((roleType) => hasRole(member, roleType));\n}\n\nexport function requireRole(roleType: RoleType) {\n  return function (interaction: CommandInteraction): boolean {\n    const member = interaction.member as GuildMember | null;\n    if (!member) return false;\n    return hasRole(member, roleType);\n  };\n}\n\nexport function getRoleHierarchy(): RoleType[] {\n  return [RoleType.Founder, RoleType.LeagueManagement, RoleType.Moderator, RoleType.Referee];\n}","src/events/ready.ts":"import { Events, ActivityType } from \"discord.js\";\nimport type { ExtendedClient } from \"../types/index.js\";\n\nconst event = {\n  name: Events.ClientReady,\n  once: true,\n  execute(client: ExtendedClient) {\n    if (!client.user) return;\n\n    console.log(`[Bot] ${client.user.tag} is online!`);\n    console.log(`[Bot] Serving ${client.guilds.cache.size} guilds`);\n\n    // Set bot activity\n    client.user.setActivity(\"Legacy Football Championship\", {\n      type: ActivityType.Watching,\n    });\n\n    // Set bot status\n    client.user.setStatus(\"online\");\n  },\n};\n\nexport default event;","src/events/interactionCreate.ts":"import { Events, CommandInteraction, GuildMember } from \"discord.js\";\nimport type { ExtendedClient } from \"../types/index.js\";\n\nconst event = {\n  name: Events.InteractionCreate,\n  async execute(interaction: CommandInteraction) {\n    // Handle slash commands only\n    if (!interaction.isChatInputCommand()) return;\n\n    const client = interaction.client as ExtendedClient;\n    const command = client.commands.get(interaction.commandName);\n\n    if (!command) {\n      await interaction.reply({\n        content: \"❌ Command not found.\",\n        ephemeral: true,\n      });\n      return;\n    }\n\n    // Cooldown check\n    const cooldownKey = `${interaction.user.id}-${command.data.name}`;\n    const cooldownAmount = (command.cooldown ?? 3) * 1000;\n    const now = Date.now();\n\n    // Simple in-memory cooldown\n    if (!(\"cooldowns\" in client)) {\n      (client as Record<string, unknown>).cooldowns = new Map();\n    }\n    const cooldowns = (client as Record<string, unknown>).cooldowns as Map<string, number>;\n\n    if (cooldowns.has(cooldownKey)) {\n      const expiration = cooldowns.get(cooldownKey)!;\n      if (now < expiration) {\n        const timeLeft = ((expiration - now) / 1000).toFixed(1);\n        await interaction.reply({\n          content: `⏳ Please wait ${timeLeft}s before using \\`/${command.data.name}\\` again.`,\n          ephemeral: true,\n        });\n        return;\n      }\n    }\n\n    // Permission check if specified\n    if (command.permissions && command.permissions.length > 0) {\n      const member = interaction.member as GuildMember | null;\n      if (member) {\n        const hasPerms = command.permissions.every((perm) =>\n          member.permissions.has(perm)\n        );\n        if (!hasPerms) {\n          await interaction.reply({\n            content: \"❌ You don't have permission to use this command.\",\n            ephemeral: true,\n          });\n          return;\n        }\n      }\n    }\n\n    // Execute the command\n    try {\n      await command.execute(interaction);\n    } catch (error) {\n      console.error(`[Error] Command /${command.data.name}:`, error);\n\n      const reply = {\n        content: \"❌ An error occurred while executing this command.\",\n        ephemeral: true,\n      };\n\n      if (interaction.replied || interaction.deferred) {\n        await interaction.followUp(reply);\n      } else {\n        await interaction.reply(reply);\n      }\n    }\n\n    // Set cooldown\n    cooldowns.set(cooldownKey, now + cooldownAmount);\n  },\n};\n\nexport default event;","src/services/playerService.ts":"import { prisma } from \"../database/prisma.js\";\nimport { generateLfcId } from \"../utils/helpers.js\";\nimport type { Position, Region } from \"../types/index.js\";\n\nexport class PlayerService {\n  /**\n   * Get or create a player profile linked to a Discord user.\n   */\n  async getOrCreatePlayer(discordId: string, username: string) {\n    // First ensure the DiscordUser exists\n    let discordUser = await prisma.discordUser.findUnique({\n      where: { discordId },\n    });\n\n    if (!discordUser) {\n      discordUser = await prisma.discordUser.create({\n        data: { discordId, username },\n      });\n    } else if (discordUser.username !== username) {\n      // Update username if changed\n      discordUser = await prisma.discordUser.update({\n        where: { discordId },\n        data: { username },\n      });\n    }\n\n    // Check if player exists\n    let player = await prisma.player.findUnique({\n      where: { discordId },\n      include: {\n        user: true,\n        team: true,\n        seasonStats: { include: { season: true } },\n        awards: { include: { season: true } },\n      },\n    });\n\n    if (!player) {\n      player = await prisma.player.create({\n        data: {\n          lfcId: generateLfcId(discordId),\n          discordId,\n          position: \"Midfielder\",\n          region: \"Europe\",\n        },\n        include: {\n          user: true,\n          team: true,\n          seasonStats: { include: { season: true } },\n          awards: { include: { season: true } },\n        },\n      });\n    }\n\n    return player;\n  }\n\n  /**\n   * Get a player by Discord ID.\n   */\n  async getPlayer(discordId: string) {\n    return prisma.player.findUnique({\n      where: { discordId },\n      include: {\n        user: true,\n        team: true,\n        seasonStats: {\n          include: { season: true },\n          orderBy: { season: { name: \"desc\" } },\n        },\n        awards: { include: { season: true } },\n      },\n    });\n  }\n\n  /**\n   * Get a player by LFC ID.\n   */\n  async getPlayerByLfcId(lfcId: string) {\n    return prisma.player.findUnique({\n      where: { lfcId },\n      include: {\n        user: true,\n        team: true,\n        seasonStats: {\n          include: { season: true },\n          orderBy: { season: { name: \"desc\" } },\n        },\n        awards: { include: { season: true } },\n      },\n    });\n  }\n\n  /**\n   * Update player position and region.\n   */\n  async updatePlayerProfile(\n    discordId: string,\n    data: { position?: Position; region?: Region }\n  ) {\n    return prisma.player.update({\n      where: { discordId },\n      data,\n      include: { user: true, team: true },\n    });\n  }\n\n  /**\n   * Get top goalscorers.\n   */\n  async getTopGoalscorers(limit = 10) {\n    return prisma.player.findMany({\n      orderBy: { goals: \"desc\" },\n      take: limit,\n      include: { user: true, team: true },\n    });\n  }\n\n  /**\n   * Get top assist providers.\n   */\n  async getTopAssists(limit = 10) {\n    return prisma.player.findMany({\n      orderBy: { assists: \"desc\" },\n      take: limit,\n      include: { user: true, team: true },\n    });\n  }\n\n  /**\n   * Get most MVPs.\n   */\n  async getTopMvps(limit = 10) {\n    return prisma.player.findMany({\n      orderBy: { mvps: \"desc\" },\n      take: limit,\n      include: { user: true, team: true },\n    });\n  }\n\n  /**\n   * Get most appearances.\n   */\n  async getTopAppearances(limit = 10) {\n    return prisma.player.findMany({\n      orderBy: { appearances: \"desc\" },\n      take: limit,\n      include: { user: true, team: true },\n    });\n  }\n\n  /**\n   * Get transfer history for a player.\n   */\n  async getTransferHistory(playerId: string) {\n    return prisma.transfer.findMany({\n      where: { playerId, status: \"Completed\" },\n      orderBy: { completedAt: \"desc\" },\n    });\n  }\n}\n\nexport const playerService = new PlayerService();","src/services/teamService.ts":"import { prisma } from \"../database/prisma.js\";\n\nexport class TeamService {\n  /**\n   * Create a new team.\n   */\n  async createTeam(data: {\n    name: string;\n    shortName?: string;\n    description?: string;\n    managerId: string;\n  }) {\n    return prisma.team.create({\n      data: {\n        name: data.name,\n        shortName: data.shortName,\n        description: data.description,\n        managerId: data.managerId,\n      },\n      include: { manager: true },\n    });\n  }\n\n  /**\n   * Get a team by ID.\n   */\n  async getTeamById(teamId: string) {\n    return prisma.team.findUnique({\n      where: { id: teamId },\n      include: {\n        manager: true,\n        players: { include: { user: true } },\n        seasonTeams: { include: { season: true } },\n      },\n    });\n  }\n\n  /**\n   * Get a team by name.\n   */\n  async getTeamByName(name: string) {\n    return prisma.team.findUnique({\n      where: { name },\n      include: {\n        manager: true,\n        players: { include: { user: true } },\n        seasonTeams: { include: { season: true } },\n      },\n    });\n  }\n\n  /**\n   * List all teams.\n   */\n  async listTeams() {\n    return prisma.team.findMany({\n      include: {\n        manager: true,\n        _count: { select: { players: true } },\n      },\n      orderBy: { name: \"asc\" },\n    });\n  }\n\n  /**\n   * Get team stats for a specific season.\n   */\n  async getTeamSeasonStats(teamId: string, seasonId: string) {\n    return prisma.teamSeasonStats.findUnique({\n      where: { teamId_seasonId: { teamId, seasonId } },\n    });\n  }\n\n  /**\n   * Add a player to a team.\n   */\n  async addPlayerToTeam(playerId: string, teamId: string) {\n    return prisma.player.update({\n      where: { id: playerId },\n      data: { teamId },\n    });\n  }\n\n  /**\n   * Remove a player from their team.\n   */\n  async removePlayerFromTeam(playerId: string) {\n    return prisma.player.update({\n      where: { id: playerId },\n      data: { teamId: null },\n    });\n  }\n}\n\nexport const teamService = new TeamService();","src/services/matchService.ts":"import { prisma } from \"../database/prisma.js\";\n\nexport class MatchService {\n  /**\n   * Create a new match.\n   */\n  async createMatch(data: {\n    homeTeamId: string;\n    awayTeamId: string;\n    seasonId: string;\n    matchDate?: Date;\n    refereeId?: string;\n  }) {\n    return prisma.match.create({\n      data: {\n        homeTeamId: data.homeTeamId,\n        awayTeamId: data.awayTeamId,\n        seasonId: data.seasonId,\n        matchDate: data.matchDate,\n        refereeId: data.refereeId,\n        status: \"Scheduled\",\n      },\n      include: {\n        homeTeam: true,\n        awayTeam: true,\n        season: true,\n      },\n    });\n  }\n\n  /**\n   * Start a match (set status to Live).\n   */\n  async startMatch(matchId: string) {\n    return prisma.match.update({\n      where: { id: matchId },\n      data: { status: \"Live\" },\n    });\n  }\n\n  /**\n   * Finish a match with a score.\n   */\n  async finishMatch(\n    matchId: string,\n    data: {\n      homeScore: number;\n      awayScore: number;\n    }\n  ) {\n    const match = await prisma.match.update({\n      where: { id: matchId },\n      data: {\n        homeScore: data.homeScore,\n        awayScore: data.awayScore,\n        status: \"Finished\",\n      },\n    });\n\n    // Update team season stats\n    await this.updateTeamStatsAfterMatch(match);\n\n    return match;\n  }\n\n  /**\n   * Update team standings after a match finishes.\n   */\n  private async updateTeamStatsAfterMatch(match: {\n    id: string;\n    homeTeamId: string;\n    awayTeamId: string;\n    homeScore: number;\n    awayScore: number;\n    seasonId: string;\n  }) {\n    const homeStats = await prisma.teamSeasonStats.findUnique({\n      where: {\n        teamId_seasonId: {\n          teamId: match.homeTeamId,\n          seasonId: match.seasonId,\n        },\n      },\n    });\n\n    const awayStats = await prisma.teamSeasonStats.findUnique({\n      where: {\n        teamId_seasonId: {\n          teamId: match.awayTeamId,\n          seasonId: match.seasonId,\n        },\n      },\n    });\n\n    // Determine result\n    let homeResult: \"win\" | \"draw\" | \"loss\";\n    let awayResult: \"win\" | \"draw\" | \"loss\";\n\n    if (match.homeScore > match.awayScore) {\n      homeResult = \"win\";\n      awayResult = \"loss\";\n    } else if (match.homeScore < match.awayScore) {\n      homeResult = \"loss\";\n      awayResult = \"win\";\n    } else {\n      homeResult = \"draw\";\n      awayResult = \"draw\";\n    }\n\n    // Update home team stats\n    if (homeStats) {\n      await prisma.teamSeasonStats.update({\n        where: { id: homeStats.id },\n        data: {\n          played: homeStats.played + 1,\n          wins: homeStats.wins + (homeResult === \"win\" ? 1 : 0),\n          draws: homeStats.draws + (homeResult === \"draw\" ? 1 : 0),\n          losses: homeStats.losses + (homeResult === \"loss\" ? 1 : 0),\n          goalsFor: homeStats.goalsFor + match.homeScore,\n          goalsAgainst: homeStats.goalsAgainst + match.awayScore,\n          points:\n            homeStats.points +\n            (homeResult === \"win\" ? 3 : homeResult === \"draw\" ? 1 : 0),\n        },\n      });\n    }\n\n    // Update away team stats\n    if (awayStats) {\n      await prisma.teamSeasonStats.update({\n        where: { id: awayStats.id },\n        data: {\n          played: awayStats.played + 1,\n          wins: awayStats.wins + (awayResult === \"win\" ? 1 : 0),\n          draws: awayStats.draws + (awayResult === \"draw\" ? 1 : 0),\n          losses: awayStats.losses + (awayResult === \"loss\" ? 1 : 0),\n          goalsFor: awayStats.goalsFor + match.awayScore,\n          goalsAgainst: awayStats.goalsAgainst + match.homeScore,\n          points:\n            awayStats.points +\n            (awayResult === \"win\" ? 3 : awayResult === \"draw\" ? 1 : 0),\n        },\n      });\n    }\n  }\n\n  /**\n   * Record a goal in a match.\n   */\n  async recordGoal(matchId: string, playerId: string, minute?: number) {\n    const goal = await prisma.matchGoal.create({\n      data: { matchId, playerId, minute },\n    });\n\n    // Increment player goals\n    await prisma.player.update({\n      where: { id: playerId },\n      data: { goals: { increment: 1 } },\n    });\n\n    return goal;\n  }\n\n  /**\n   * Record an assist in a match.\n   */\n  async recordAssist(matchId: string, playerId: string, minute?: number) {\n    const assist = await prisma.matchAssist.create({\n      data: { matchId, playerId, minute },\n    });\n\n    // Increment player assists\n    await prisma.player.update({\n      where: { id: playerId },\n      data: { assists: { increment: 1 } },\n    });\n\n    return assist;\n  }\n\n  /**\n   * Record a card in a match.\n   */\n  async recordCard(\n    matchId: string,\n    playerId: string,\n    type: \"Yellow\" | \"Red\",\n    minute?: number,\n    reason?: string\n  ) {\n    const card = await prisma.matchCard.create({\n      data: { matchId, playerId, type, minute, reason },\n    });\n\n    // Increment player cards\n    const field = type === \"Yellow\" ? \"yellowCards\" : \"redCards\";\n    await prisma.player.update({\n      where: { id: playerId },\n      data: { [field]: { increment: 1 } },\n    });\n\n    return card;\n  }\n\n  /**\n   * Record MVP for a match.\n   */\n  async recordMvp(matchId: string, playerId: string, reason?: string) {\n    const mvp = await prisma.matchMvp.upsert({\n      where: { matchId },\n      update: { playerId, reason },\n      create: { matchId, playerId, reason },\n    });\n\n    // Increment player MVPs\n    await prisma.player.update({\n      where: { id: playerId },\n      data: { mvps: { increment: 1 } },\n    });\n\n    return mvp;\n  }\n\n  /**\n   * Get matches for a team.\n   */\n  async getTeamMatches(teamId: string) {\n    return prisma.match.findMany({\n      where: {\n        OR: [{ homeTeamId: teamId }, { awayTeamId: teamId }],\n      },\n      include: {\n        homeTeam: true,\n        awayTeam: true,\n        season: true,\n      },\n      orderBy: { matchDate: \"desc\" },\n    });\n  }\n\n  /**\n   * Get upcoming fixtures.\n   */\n  async getUpcomingFixtures(limit = 10) {\n    return prisma.match.findMany({\n      where: { status: \"Scheduled\" },\n      include: {\n        homeTeam: true,\n        awayTeam: true,\n        season: true,\n      },\n      orderBy: { matchDate: \"asc\" },\n      take: limit,\n    });\n  }\n\n  /**\n   * Get recent results.\n   */\n  async getRecentResults(limit = 10) {\n    return prisma.match.findMany({\n      where: { status: \"Finished\" },\n      include: {\n        homeTeam: true,\n        awayTeam: true,\n        season: true,\n        goals: { include: { player: { include: { user: true } } } },\n        mvps: { include: { player: { include: { user: true } } } },\n      },\n      orderBy: { updatedAt: \"desc\" },\n      take: limit,\n    });\n  }\n}\n\nexport const matchService = new MatchService();","src/services/leagueService.ts":"import { prisma } from \"../database/prisma.js\";\n\nexport class LeagueService {\n  /**\n   * Get the current active season.\n   */\n  async getActiveSeason() {\n    return prisma.season.findFirst({\n      where: { isActive: true },\n      include: {\n        _count: { select: { matches: true } },\n      },\n    });\n  }\n\n  /**\n   * Get a season by ID.\n   */\n  async getSeasonById(seasonId: string) {\n    return prisma.season.findUnique({\n      where: { id: seasonId },\n      include: {\n        _count: { select: { matches: true } },\n      },\n    });\n  }\n\n  /**\n   * Get standings for a season, sorted by points descending.\n   */\n  async getStandings(seasonId: string) {\n    const teamStats = await prisma.teamSeasonStats.findMany({\n      where: { seasonId },\n      include: { team: true },\n      orderBy: [{ points: \"desc\" }, { goalsFor: \"desc\" }],\n    });\n\n    return teamStats.map((stat, index) => ({\n      position: index + 1,\n      teamId: stat.teamId,\n      teamName: stat.team.name,\n      played: stat.played,\n      wins: stat.wins,\n      draws: stat.draws,\n      losses: stat.losses,\n      goalsFor: stat.goalsFor,\n      goalsAgainst: stat.goalsAgainst,\n      goalDifference: stat.goalsFor - stat.goalsAgainst,\n      points: stat.points,\n    }));\n  }\n\n  /**\n   * Create a new season.\n   */\n  async createSeason(name: string) {\n    return prisma.season.create({\n      data: { name, isActive: true },\n    });\n  }\n\n  /**\n   * End the current active season.\n   */\n  async endActiveSeason() {\n    const activeSeason = await this.getActiveSeason();\n    if (!activeSeason) return null;\n\n    return prisma.season.update({\n      where: { id: activeSeason.id },\n      data: {\n        isActive: false,\n        endedAt: new Date(),\n      },\n    });\n  }\n\n  /**\n   * Initialize season stats for all teams.\n   */\n  async initializeSeasonStats(seasonId: string) {\n    const teams = await prisma.team.findMany();\n    const stats = [];\n\n    for (const team of teams) {\n      const existing = await prisma.teamSeasonStats.findUnique({\n        where: {\n          teamId_seasonId: { teamId: team.id, seasonId },\n        },\n      });\n\n      if (!existing) {\n        const stat = await prisma.teamSeasonStats.create({\n          data: { teamId: team.id, seasonId },\n        });\n        stats.push(stat);\n      }\n    }\n\n    return stats;\n  }\n\n  /**\n   * Initialize season stats for all players in a team.\n   */\n  async initializePlayerSeasonStats(seasonId: string, teamId?: string) {\n    const whereClause = teamId ? { teamId } : {};\n    const players = await prisma.player.findMany({ where: whereClause });\n    const stats = [];\n\n    for (const player of players) {\n      const existing = await prisma.playerSeasonStats.findUnique({\n        where: {\n          playerId_seasonId: { playerId: player.id, seasonId },\n        },\n      });\n\n      if (!existing) {\n        const stat = await prisma.playerSeasonStats.create({\n          data: { playerId: player.id, seasonId },\n        });\n        stats.push(stat);\n      }\n    }\n\n    return stats;\n  }\n}\n\nexport const leagueService = new LeagueService();","src/services/adminService.ts":"import { prisma } from \"../database/prisma.js\";\n\nexport class AdminService {\n  /**\n   * Issue a warning to a user.\n   */\n  async warnUser(discordId: string, reason: string, issuedBy: string) {\n    return prisma.warning.create({\n      data: { userId: discordId, reason, issuedBy },\n    });\n  }\n\n  /**\n   * Get warnings for a user.\n   */\n  async getUserWarnings(discordId: string) {\n    return prisma.warning.findMany({\n      where: { userId: discordId },\n      orderBy: { createdAt: \"desc\" },\n    });\n  }\n\n  /**\n   * Suspend a user.\n   */\n  async suspendUser(\n    discordId: string,\n    reason: string,\n    issuedBy: string,\n    expiresAt?: Date\n  ) {\n    return prisma.suspension.create({\n      data: {\n        userId: discordId,\n        reason,\n        issuedBy,\n        expiresAt,\n        active: true,\n      },\n    });\n  }\n\n  /**\n   * Check if a user is currently suspended.\n   */\n  async isUserSuspended(discordId: string): Promise<boolean> {\n    const suspension = await prisma.suspension.findFirst({\n      where: {\n        userId: discordId,\n        active: true,\n        OR: [\n          { expiresAt: null },\n          { expiresAt: { gte: new Date() } },\n        ],\n      },\n    });\n\n    if (!suspension) return false;\n\n    // Auto-expire if past expiry date\n    if (suspension.expiresAt && suspension.expiresAt < new Date()) {\n      await prisma.suspension.update({\n        where: { id: suspension.id },\n        data: { active: false },\n      });\n      return false;\n    }\n\n    return true;\n  }\n\n  /**\n   * Lift a suspension.\n   */\n  async liftSuspension(discordId: string) {\n    return prisma.suspension.updateMany({\n      where: { userId: discordId, active: true },\n      data: { active: false },\n    });\n  }\n\n  /**\n   * Blacklist a user.\n   */\n  async blacklistUser(discordId: string, reason: string, issuedBy: string) {\n    return prisma.blacklist.create({\n      data: { discordId, reason, issuedBy },\n    });\n  }\n\n  /**\n   * Check if a user is blacklisted.\n   */\n  async isBlacklisted(discordId: string): Promise<boolean> {\n    const entry = await prisma.blacklist.findUnique({\n      where: { discordId },\n    });\n    return !!entry;\n  }\n\n  /**\n   * Get active suspensions.\n   */\n  async getActiveSuspensions() {\n    return prisma.suspension.findMany({\n      where: { active: true },\n      include: { user: true },\n      orderBy: { createdAt: \"desc\" },\n    });\n  }\n}\n\nexport const adminService = new AdminService();","src/services/newsService.ts":"import {\n  EmbedBuilder,\n  TextChannel,\n  Guild,\n  Message,\n  hyperlink,\n} from \"discord.js\";\nimport { prisma } from \"../database/prisma.js\";\nimport type { ExtendedClient } from \"../types/index.js\";\n\ntype NewsType =\n  | \"match_result\"\n  | \"transfer\"\n  | \"award\"\n  | \"season_start\"\n  | \"season_end\"\n  | \"milestone\"\n  | \"broadcast\"\n  | \"weekly_roundup\";\n\ninterface NewsPayload {\n  type: NewsType;\n  guildId: string;\n  title: string;\n  content: string;\n  embeds?: EmbedBuilder[];\n  imageUrl?: string;\n}\n\nexport class NewsService {\n  /**\n   * Get the configured news channel for a guild.\n   */\n  async getNewsChannel(guild: Guild): Promise<TextChannel | null> {\n    const config = await prisma.guildConfig.findUnique({\n      where: { guildId: guild.id },\n    });\n\n    if (!config?.newsChannelId) return null;\n\n    const channel = guild.channels.cache.get(config.newsChannelId);\n    if (channel instanceof TextChannel) return channel;\n\n    // Try fetching if not cached\n    try {\n      const fetched = await guild.channels.fetch(config.newsChannelId);\n      if (fetched instanceof TextChannel) return fetched;\n    } catch {\n      return null;\n    }\n\n    return null;\n  }\n\n  /**\n   * Set the news channel for a guild.\n   */\n  async setNewsChannel(guildId: string, channelId: string) {\n    return prisma.guildConfig.upsert({\n      where: { guildId },\n      update: { newsChannelId: channelId },\n      create: { guildId, newsChannelId: channelId },\n    });\n  }\n\n  /**\n   * Publish a news article to the configured channel and database.\n   */\n  async publish(client: ExtendedClient, payload: NewsPayload): Promise<Message | null> {\n    const guild = client.guilds.cache.get(payload.guildId);\n    if (!guild) return null;\n\n    const channel = await this.getNewsChannel(guild);\n    if (!channel) return null;\n\n    const embed = new EmbedBuilder()\n      .setTitle(payload.title)\n      .setDescription(payload.content)\n      .setColor(this.getColorForType(payload.type))\n      .setFooter({\n        text: `Legacy Football Championship • ${new Date().toLocaleDateString(\"en-US\", { weekday: \"long\", year: \"numeric\", month: \"long\", day: \"numeric\" })}`,\n      })\n      .setTimestamp();\n\n    // If additional embeds were provided, use the first one instead\n    const finalEmbeds = payload.embeds ?? [embed];\n\n    if (payload.imageUrl) {\n      finalEmbeds[0]?.setImage(payload.imageUrl);\n    }\n\n    // Send to channel\n    const message = await channel.send({ embeds: finalEmbeds });\n\n    // Store in database\n    await prisma.newsArticle.create({\n      data: {\n        guildId: payload.guildId,\n        type: payload.type,\n        title: payload.title,\n        content: payload.content,\n        messageId: message.id,\n        channelId: channel.id,\n      },\n    });\n\n    return message;\n  }\n\n  /**\n   * Auto-post a match result.\n   */\n  async announceMatchResult(\n    client: ExtendedClient,\n    data: {\n      guildId: string;\n      homeTeam: string;\n      awayTeam: string;\n      homeScore: number;\n      awayScore: number;\n      scorers?: string[];\n      mvp?: string;\n      matchId: string;\n    }\n  ) {\n    const isDraw = data.homeScore === data.awayScore;\n    const homeWin = data.homeScore > data.awayScore;\n\n    const emoji = isDraw ? \"🤝\" : homeWin ? \"🏠\" : \"🚗\";\n    const resultText = isDraw\n      ? \"Draw!\"\n      : homeWin\n        ? `${data.homeTeam} wins!`\n        : `${data.awayTeam} wins!`;\n\n    const embed = new EmbedBuilder()\n      .setTitle(`⚽ Full-Time: ${data.homeTeam} vs ${data.awayTeam}`)\n      .setColor(isDraw ? \"#FFAA00\" : homeWin ? \"#00AA00\" : \"#0066CC\")\n      .setDescription(\n        `**${data.homeTeam}** ${data.homeScore} - ${data.awayScore} **${data.awayTeam}**\\n\\n${emoji} **${resultText}**`\n      )\n      .addFields(\n        {\n          name: \"⚽ Scorers\",\n          value: data.scorers?.length\n            ? data.scorers.join(\"\\n\")\n            : \"No goals recorded\",\n          inline: true,\n        },\n        {\n          name: \"🏆 MVP\",\n          value: data.mvp ?? \"Not selected\",\n          inline: true,\n        }\n      )\n      .setFooter({\n        text: `Match ID: ${data.matchId.slice(0, 8)} • Legacy Football Championship`,\n      })\n      .setTimestamp();\n\n    return this.publish(client, {\n      type: \"match_result\",\n      guildId: data.guildId,\n      title: `⚽ Match Result: ${data.homeTeam} ${data.homeScore} - ${data.awayScore} ${data.awayTeam}`,\n      content: `${emoji} **${resultText}**\\n\\n**${data.homeTeam}** ${data.homeScore} - ${data.awayScore} **${data.awayTeam}**`,\n      embeds: [embed],\n    });\n  }\n\n  /**\n   * Auto-post a transfer announcement.\n   */\n  async announceTransfer(\n    client: ExtendedClient,\n    data: {\n      guildId: string;\n      playerName: string;\n      fromTeam: string;\n      toTeam: string;\n      fee?: string;\n    }\n  ) {\n    const embed = new EmbedBuilder()\n      .setTitle(\"🔄 Transfer Complete!\")\n      .setColor(\"#00AA00\")\n      .setDescription(\n        `**${data.playerName}** has completed a move!`\n      )\n      .addFields(\n        { name: \"➡️ From\", value: data.fromTeam, inline: true },\n        { name: \"🏠 To\", value: data.toTeam, inline: true },\n        {\n          name: \"💰 Fee\",\n          value: data.fee ?? \"Free Transfer\",\n          inline: true,\n        }\n      )\n      .setFooter({ text: \"Legacy Football Championship • Transfer Window\" })\n      .setTimestamp();\n\n    return this.publish(client, {\n      type: \"transfer\",\n      guildId: data.guildId,\n      title: `🔄 ${data.playerName} joins ${data.toTeam}`,\n      content: `${data.playerName} has moved from ${data.fromTeam} to ${data.toTeam}${data.fee ? ` for ${data.fee}` : \" on a free transfer\"}.`,\n      embeds: [embed],\n    });\n  }\n\n  /**\n   * Auto-post an award announcement.\n   */\n  async announceAward(\n    client: ExtendedClient,\n    data: {\n      guildId: string;\n      playerName: string;\n      awardType: string;\n      season: string;\n      reason?: string;\n    }\n  ) {\n    const awardEmojis: Record<string, string> = {\n      \"Golden Boot\": \"🥾\",\n      \"Golden Boy\": \"🌟\",\n      \"Best Playmaker\": \"🎯\",\n      \"Player of the Season\": \"👑\",\n      \"Team of the Season\": \"🏅\",\n      \"Manager of the Season\": \"📋\",\n    };\n\n    const emoji = awardEmojis[data.awardType] ?? \"🏅\";\n\n    const embed = new EmbedBuilder()\n      .setTitle(`${emoji} ${data.awardType} Awarded!`)\n      .setColor(\"#FFD700\")\n      .setDescription(\n        `**${data.playerName}** has been awarded **${data.awardType}**!`\n      )\n      .addFields(\n        { name: \"🏅 Award\", value: data.awardType, inline: true },\n        { name: \"📅 Season\", value: data.season, inline: true },\n        { name: \"📝 Reason\", value: data.reason ?? \"Outstanding performance\", inline: false }\n      )\n      .setFooter({ text: \"Legacy Football Championship • Awards\" })\n      .setTimestamp();\n\n    return this.publish(client, {\n      type: \"award\",\n      guildId: data.guildId,\n      title: `${emoji} ${data.awardType}: ${data.playerName}`,\n      content: `**${data.playerName}** has won the **${data.awardType}** award for ${data.season}!`,\n      embeds: [embed],\n    });\n  }\n\n  /**\n   * Announce season start.\n   */\n  async announceSeasonStart(\n    client: ExtendedClient,\n    data: {\n      guildId: string;\n      seasonName: string;\n      teamCount: number;\n    }\n  ) {\n    const embed = new EmbedBuilder()\n      .setTitle(\"📅 New Season Begins!\")\n      .setColor(\"#00AA00\")\n      .setDescription(\n        `**${data.seasonName}** is officially underway!`\n      )\n      .addFields(\n        { name: \"📋 Season\", value: data.seasonName, inline: true },\n        { name: \"🏟️ Teams\", value: `${data.teamCount} teams competing`, inline: true },\n        {\n          name: \"🎯 What to Expect\",\n          value: [\n            \"• Exciting matches every week\",\n            \"• Intense title race\",\n            \"• Individual awards up for grabs\",\n            \"• Transfer window action\",\n          ].join(\"\\n\"),\n          inline: false,\n        }\n      )\n      .setFooter({ text: \"Legacy Football Championship\" })\n      .setTimestamp();\n\n    return this.publish(client, {\n      type: \"season_start\",\n      guildId: data.guildId,\n      title: `📅 ${data.seasonName} has begun!`,\n      content: `The **${data.seasonName}** of Legacy Football Championship is now LIVE with **${data.teamCount} teams** competing for glory!`,\n      embeds: [embed],\n    });\n  }\n\n  /**\n   * Announce season end with champion.\n   */\n  async announceSeasonEnd(\n    client: ExtendedClient,\n    data: {\n      guildId: string;\n      seasonName: string;\n      championName?: string;\n      championPoints?: number;\n    }\n  ) {\n    const embed = new EmbedBuilder()\n      .setTitle(\"🏆 Season Over!\")\n      .setColor(\"#FFD700\")\n      .setDescription(`**${data.seasonName}** has concluded!`);\n\n    if (data.championName) {\n      embed.addFields(\n        {\n          name: \"👑 Champions\",\n          value: `**${data.championName}**${data.championPoints ? ` — ${data.championPoints} points` : \"\"}`,\n          inline: false,\n        },\n        {\n          name: \"🎊 Congratulations!\",\n          value: `A huge congratulations to **${data.championName}** for winning ${data.seasonName}!`,\n          inline: false,\n        }\n      );\n    }\n\n    embed\n      .addFields({\n        name: \"🏅 Awards Ceremony\",\n        value: \"Use `/award give` to distribute season awards before the next season begins.\",\n        inline: false,\n      })\n      .setFooter({ text: \"Legacy Football Championship\" })\n      .setTimestamp();\n\n    return this.publish(client, {\n      type: \"season_end\",\n      guildId: data.guildId,\n      title: `🏆 ${data.seasonName} has ended!`,\n      content: data.championName\n        ? `**${data.championName}** are the champions of ${data.seasonName}!`\n        : `${data.seasonName} has come to a close.`,\n      embeds: [embed],\n    });\n  }\n\n  /**\n   * Announce a player milestone.\n   */\n  async announceMilestone(\n    client: ExtendedClient,\n    data: {\n      guildId: string;\n      playerName: string;\n      teamName?: string;\n      milestone: string; // e.g. \"10 Goals\", \"50 Appearances\", \"5 MVPs\"\n      stat: string;\n    }\n  ) {\n    const embed = new EmbedBuilder()\n      .setTitle(\"🌟 Milestone Achieved!\")\n      .setColor(\"#00AA00\")\n      .setDescription(\n        `**${data.playerName}** has reached a career milestone!`\n      )\n      .addFields(\n        { name: \"👤 Player\", value: data.playerName, inline: true },\n        { name: \"🎯 Milestone\", value: data.milestone, inline: true },\n        {\n          name: \"🏠 Team\",\n          value: data.teamName ?? \"Free Agent\",\n          inline: true,\n        },\n        {\n          name: \"📈 Career Stats\",\n          value: data.stat,\n          inline: false,\n        }\n      )\n      .setFooter({ text: \"Legacy Football Championship • Milestones\" })\n      .setTimestamp();\n\n    return this.publish(client, {\n      type: \"milestone\",\n      guildId: data.guildId,\n      title: `🌟 ${data.playerName} — ${data.milestone}!`,\n      content: `**${data.playerName}** has achieved **${data.milestone}** in their LFC career!`,\n      embeds: [embed],\n    });\n  }\n\n  /**\n   * Announce a breaking news broadcast from management.\n   */\n  async announceBroadcast(\n    client: ExtendedClient,\n    data: {\n      guildId: string;\n      title: string;\n      message: string;\n      authorName: string;\n      color?: string;\n    }\n  ) {\n    const embed = new EmbedBuilder()\n      .setTitle(`📢 ${data.title}`)\n      .setColor((data.color as never) ?? \"#FF0000\")\n      .setDescription(data.message)\n      .setFooter({\n        text: `Posted by ${data.authorName} • Legacy Football Championship`,\n      })\n      .setTimestamp();\n\n    return this.publish(client, {\n      type: \"broadcast\",\n      guildId: data.guildId,\n      title: `📢 ${data.title}`,\n      content: data.message,\n      embeds: [embed],\n    });\n  }\n\n  /**\n   * Generate a weekly roundup embed.\n   */\n  async generateWeeklyRoundup(\n    client: ExtendedClient,\n    guildId: string,\n    seasonName: string,\n    standings: Array<{\n      position: number;\n      teamName: string;\n      played: number;\n      wins: number;\n      draws: number;\n      losses: number;\n      points: number;\n    }>,\n    topScorers: Array<{\n      name: string;\n      goals: number;\n      team?: string;\n    }>,\n    recentMatches: Array<{\n      homeTeam: string;\n      awayTeam: string;\n      homeScore: number;\n      awayScore: number;\n    }>\n  ) {\n    // Build standings snippet\n    const top3 = standings.slice(0, 3);\n    const standingsText = top3.length\n      ? top3\n          .map(\n            (s) =>\n              `${getMedalEmoji(s.position)} **${s.teamName}** — ${s.points}pts (${s.wins}W / ${s.draws}D / ${s.losses}L)`\n          )\n          .join(\"\\n\")\n      : \"No standings data yet.\";\n\n    // Build scorers snippet\n    const scorersText = topScorers.length\n      ? topScorers\n          .slice(0, 5)\n          .map((s, i) => `${i + 1}. **${s.name}**${s.team ? ` (${s.team})` : \"\"} — ${s.goals}G`)\n          .join(\"\\n\")\n      : \"No scorers data yet.\";\n\n    // Build results snippet\n    const resultsText = recentMatches.length\n      ? recentMatches\n          .slice(0, 5)\n          .map((m) => `**${m.homeTeam}** ${m.homeScore} - ${m.awayScore} **${m.awayTeam}**`)\n          .join(\"\\n\")\n      : \"No recent matches.\";\n\n    const embed = new EmbedBuilder()\n      .setTitle(\"📊 Weekly Roundup\")\n      .setColor(\"#00AA00\")\n      .setDescription(`**${seasonName}** — Weekly summary of league action.`)\n      .addFields(\n        {\n          name: \"🏆 Top 3 Standings\",\n          value: standingsText,\n          inline: false,\n        },\n        {\n          name: \"⚽ Top Goalscorers\",\n          value: scorersText,\n          inline: true,\n        },\n        {\n          name: \"📋 Recent Results\",\n          value: resultsText,\n          inline: true,\n        }\n      )\n      .setFooter({ text: \"Legacy Football Championship • Weekly Roundup\" })\n      .setTimestamp();\n\n    return this.publish(client, {\n      type: \"weekly_roundup\",\n      guildId,\n      title: \"📊 Weekly Roundup\",\n      content: `Here's your weekly roundup of **${seasonName}** action!`,\n      embeds: [embed],\n    });\n  }\n\n  /**\n   * Get news history for a guild.\n   */\n  async getRecentNews(guildId: string, limit = 10) {\n    return prisma.newsArticle.findMany({\n      where: { guildId },\n      orderBy: { createdAt: \"desc\" },\n      take: limit,\n    });\n  }\n\n  /**\n   * Check and announce player milestones.\n   * Called after a match updates player stats.\n   */\n  async checkMilestones(\n    client: ExtendedClient,\n    guildId: string,\n    playerId: string\n  ) {\n    const player = await prisma.player.findUnique({\n      where: { id: playerId },\n      include: { user: true, team: true },\n    });\n\n    if (!player) return;\n\n    const milestones: Array<{ name: string; threshold: number; format: string }> = [\n      { name: \"Goals\", threshold: 10, format: `${player.goals} Goals` },\n      { name: \"Goals\", threshold: 25, format: `${player.goals} Goals` },\n      { name: \"Goals\", threshold: 50, format: `${player.goals} Goals` },\n      { name: \"Assists\", threshold: 10, format: `${player.assists} Assists` },\n      { name: \"Assists\", threshold: 25, format: `${player.assists} Assists` },\n      { name: \"MVPs\", threshold: 5, format: `${player.mvps} MVPs` },\n      { name: \"MVPs\", threshold: 10, format: `${player.mvps} MVPs` },\n      { name: \"Appearances\", threshold: 10, format: `${player.appearances} Appearances` },\n      { name: \"Appearances\", threshold: 25, format: `${player.appearances} Appearances` },\n      { name: \"Appearances\", threshold: 50, format: `${player.appearances} Appearances` },\n      { name: \"Appearances\", threshold: 100, format: `${player.appearances} Appearances` },\n    ];\n\n    for (const milestone of milestones) {\n      const current =\n        milestone.name === \"Goals\"\n          ? player.goals\n          : milestone.name === \"Assists\"\n            ? player.assists\n            : milestone.name === \"MVPs\"\n              ? player.mvps\n              : player.appearances;\n\n      if (current === milestone.threshold) {\n        // Check if we already announced this milestone\n        const alreadyAnnounced = await prisma.newsArticle.findFirst({\n          where: {\n            guildId,\n            type: \"milestone\",\n            content: { contains: `${milestone.format}` },\n            title: { contains: player.user.username },\n          },\n        });\n\n        if (!alreadyAnnounced) {\n          const statLine = `⚽ ${player.goals}G | 🎯 ${player.assists}A | 🏆 ${player.mvps} MVP | 📋 ${player.appearances} Apps`;\n          await this.announceMilestone(client, {\n            guildId,\n            playerName: player.user.username,\n            teamName: player.team?.name,\n            milestone: milestone.format,\n            stat: statLine,\n          });\n        }\n      }\n    }\n  }\n\n  private getColorForType(type: NewsType): number {\n    const colors: Record<NewsType, number> = {\n      match_result: 0x00aa00,\n      transfer: 0x0099ff,\n      award: 0xffd700,\n      season_start: 0x00aa00,\n      season_end: 0xffd700,\n      milestone: 0x00aaff,\n      broadcast: 0xff0000,\n      weekly_roundup: 0x00aa00,\n    };\n    return colors[type] ?? 0x00aa00;\n  }\n}\n\nfunction getMedalEmoji(position: number): string {\n  switch (position) {\n    case 1:\n      return \"🥇\";\n    case 2:\n      return \"🥈\";\n    case 3:\n      return \"🥉\";\n    default:\n      return \"#\";\n  }\n}\n\nexport const newsService = new NewsService();","src/services/contractService.ts":"import { prisma } from \"../database/prisma.js\";\nimport { generateLfcId } from \"../utils/helpers.js\";\nimport type { TeamRole } from \"../types/index.js\";\n\nexport class ContractService {\n  /**\n   * Offer a contract to a player — creates player if new, signs contract, assigns nickname.\n   */\n  async offerContract(data: {\n    discordId: string;\n    username: string;\n    teamName: string;\n    position: string;\n    region: string;\n    robloxUsername?: string;\n    roleInTeam?: TeamRole;\n    nickname?: string;\n  }) {\n    // 1. Ensure DiscordUser exists\n    let discordUser = await prisma.discordUser.findUnique({\n      where: { discordId: data.discordId },\n    });\n    if (!discordUser) {\n      discordUser = await prisma.discordUser.create({\n        data: { discordId: data.discordId, username: data.username },\n      });\n    }\n\n    // 2. Find team\n    const team = await prisma.team.findUnique({ where: { name: data.teamName } });\n    if (!team) throw new Error(`Team \"${data.teamName}\" not found.`);\n\n    // 3. Upsert player\n    let player = await prisma.player.findUnique({\n      where: { discordId: data.discordId },\n    });\n    if (!player) {\n      player = await prisma.player.create({\n        data: {\n          lfcId: generateLfcId(data.discordId),\n          discordId: data.discordId,\n          position: data.position,\n          region: data.region,\n          robloxUsername: data.robloxUsername,\n          nickname: data.nickname,\n          roleInTeam: data.roleInTeam,\n          teamId: team.id,\n        },\n      });\n    } else {\n      player = await prisma.player.update({\n        where: { discordId: data.discordId },\n        data: {\n          position: data.position,\n          region: data.region,\n          robloxUsername: data.robloxUsername,\n          nickname: data.nickname,\n          roleInTeam: data.roleInTeam,\n          teamId: team.id,\n        },\n      });\n    }\n\n    // 4. Deactivate any existing active contracts\n    await prisma.contract.updateMany({\n      where: { playerId: player.id, isActive: true },\n      data: { isActive: false },\n    });\n\n    // 5. Create new contract\n    const contract = await prisma.contract.create({\n      data: {\n        playerId: player.id,\n        teamId: team.id,\n        teamName: team.name,\n        roleInTeam: data.roleInTeam,\n        isActive: true,\n      },\n    });\n\n    const updatedPlayer = await prisma.player.findUnique({\n      where: { id: player.id },\n      include: { user: true, team: true },\n    });\n\n    return { player: updatedPlayer!, contract, team };\n  }\n\n  /**\n   * Release a player from their team (back to free agency).\n   */\n  async releasePlayer(discordId: string) {\n    const player = await prisma.player.findUnique({\n      where: { discordId },\n      include: { team: true, contracts: { where: { isActive: true } } },\n    });\n    if (!player) throw new Error(\"Player not found.\");\n    if (!player.teamId) throw new Error(\"Player is already a free agent.\");\n\n    // Deactivate active contracts\n    await prisma.contract.updateMany({\n      where: { playerId: player.id, isActive: true },\n      data: { isActive: false },\n    });\n\n    // Remove from team\n    await prisma.player.update({\n      where: { id: player.id },\n      data: { teamId: null, roleInTeam: null },\n    });\n\n    return player;\n  }\n\n  /**\n   * Get all free agents (verified players without a team).\n   */\n  async getFreeAgents() {\n    return prisma.player.findMany({\n      where: { teamId: null },\n      include: { user: true },\n      orderBy: { goals: \"desc\" },\n    });\n  }\n\n  /**\n   * Get a player's current contract.\n   */\n  async getActiveContract(playerId: string) {\n    return prisma.contract.findFirst({\n      where: { playerId, isActive: true },\n      include: { team: true },\n    });\n  }\n\n  /**\n   * Get all players for a team with their roles.\n   */\n  async getTeamRoster(teamId: string) {\n    return prisma.player.findMany({\n      where: { teamId },\n      include: { user: true },\n      orderBy: [{ roleInTeam: \"asc\" }, { goals: \"desc\" }],\n    });\n  }\n}\n\nexport const contractService = new ContractService();","src/services/predictionService.ts":"import { prisma } from \"../database/prisma.js\";\n\nexport class PredictionService {\n  /**\n   * Place a prediction on a match.\n   */\n  async predict(data: {\n    matchId: string;\n    userId: string;\n    teamId?: string;\n    draw?: boolean;\n  }) {\n    return prisma.prediction.upsert({\n      where: {\n        matchId_userId: { matchId: data.matchId, userId: data.userId },\n      },\n      update: {\n        predictedTeamId: data.teamId ?? null,\n        predictedDraw: data.draw ?? false,\n      },\n      create: {\n        matchId: data.matchId,\n        userId: data.userId,\n        predictedTeamId: data.teamId ?? null,\n        predictedDraw: data.draw ?? false,\n      },\n    });\n  }\n\n  /**\n   * Resolve predictions after a match ends.\n   * Points: 3 for correct winner, 1 for correct draw.\n   */\n  async resolvePredictions(matchId: string) {\n    const match = await prisma.match.findUnique({\n      where: { id: matchId },\n    });\n    if (!match || match.status !== \"Finished\") return;\n    if (match.homeScore === null || match.awayScore === null) return;\n\n    const predictions = await prisma.prediction.findMany({\n      where: { matchId, resolved: false },\n    });\n\n    let winnerId: string | null = null;\n    let isDraw = false;\n\n    if (match.homeScore > match.awayScore) {\n      winnerId = match.homeTeamId;\n    } else if (match.awayScore > match.homeScore) {\n      winnerId = match.awayTeamId;\n    } else {\n      isDraw = true;\n    }\n\n    for (const pred of predictions) {\n      let points = 0;\n      if (isDraw && pred.predictedDraw) points = 3;\n      else if (winnerId && pred.predictedTeamId === winnerId) points = 3;\n\n      await prisma.prediction.update({\n        where: { id: pred.id },\n        data: { points, resolved: true },\n      });\n    }\n  }\n\n  /**\n   * Get prediction leaderboard for a season.\n   */\n  async getLeaderboard(seasonId: string) {\n    const matches = await prisma.match.findMany({\n      where: { seasonId, status: \"Finished\" },\n      select: { id: true },\n    });\n    const matchIds = matches.map((m) => m.id);\n\n    const predictions = await prisma.prediction.findMany({\n      where: { matchId: { in: matchIds }, resolved: true },\n    });\n\n    // Aggregate by user\n    const userPoints = new Map<string, number>();\n    for (const p of predictions) {\n      userPoints.set(p.userId, (userPoints.get(p.userId) ?? 0) + p.points);\n    }\n\n    return Array.from(userPoints.entries())\n      .map(([userId, points]) => ({ userId, points }))\n      .sort((a, b) => b.points - a.points);\n  }\n\n  /**\n   * Get total predictions for a user.\n   */\n  async getUserStats(userId: string) {\n    const predictions = await prisma.prediction.findMany({\n      where: { userId },\n      include: { match: { include: { homeTeam: true, awayTeam: true } } },\n      orderBy: { createdAt: \"desc\" },\n    });\n\n    const correct = predictions.filter((p) => p.resolved && p.points > 0).length;\n    const total = predictions.filter((p) => p.resolved).length;\n\n    return { predictions, correct, total, accuracy: total > 0 ? ((correct / total) * 100).toFixed(1) : \"0\" };\n  }\n}\n\nexport const predictionService = new PredictionService();","src/commands/offer/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { contractService } from \"../../services/contractService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command, TeamRole } from \"../../types/index.js\";\n\nconst POSITIONS = [\n  { name: \"🧤 Goalkeeper\", value: \"Goalkeeper\" },\n  { name: \"🛡️ Defender\", value: \"Defender\" },\n  { name: \"🎯 Midfielder\", value: \"Midfielder\" },\n  { name: \"⚽ Forward\", value: \"Forward\" },\n];\n\nconst ROLES = [\n  { name: \"👑 Captain\", value: \"Captain\" },\n  { name: \"⭐ Vice Captain\", value: \"Vice Captain\" },\n  { name: \"🏃 Starter\", value: \"Starter\" },\n  { name: \"🔄 Sub\", value: \"Sub\" },\n  { name: \"📚 Academy\", value: \"Academy\" },\n];\n\nconst REGIONS = [\n  { name: \"🌍 Europe\", value: \"Europe\" },\n  { name: \"🌏 Asia\", value: \"Asia\" },\n  { name: \"🌍 Africa\", value: \"Africa\" },\n  { name: \"🌎 North America\", value: \"North America\" },\n  { name: \"🌎 South America\", value: \"South America\" },\n  { name: \"🌏 Oceania\", value: \"Oceania\" },\n];\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"offer\")\n    .setDescription(\"Offer a contract to a player and auto-nickname them (Management only)\")\n    .addUserOption((opt) =>\n      opt.setName(\"player\").setDescription(\"Player to offer contract\").setRequired(true)\n    )\n    .addStringOption((opt) =>\n      opt.setName(\"team\").setDescription(\"Team name\").setRequired(true)\n    )\n    .addStringOption((opt) =>\n      opt.setName(\"position\").setDescription(\"Position\").setRequired(true)\n        .addChoices(...POSITIONS)\n    )\n    .addStringOption((opt) =>\n      opt.setName(\"region\").setDescription(\"Region\").setRequired(true)\n        .addChoices(...REGIONS)\n    )\n    .addStringOption((opt) =>\n      opt.setName(\"role\").setDescription(\"Team role\").setRequired(false)\n        .addChoices(...ROLES)\n    )\n    .addStringOption((opt) =>\n      opt.setName(\"roblox\").setDescription(\"Roblox username\").setRequired(false)\n    )\n    .addStringOption((opt) =>\n      opt.setName(\"nickname\").setDescription(\"Server nickname to assign\").setRequired(false)\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    if (!hasRole(interaction.member as never, RoleType.Founder) &&\n        !hasRole(interaction.member as never, RoleType.LeagueManagement)) {\n      await interaction.editReply({\n        embeds: [createErrorEmbed(\"❌ Insufficient Permissions\",\"You need **Founder** or **League Management** role.\")],\n      });\n      return;\n    }\n\n    const target = interaction.options.getUser(\"player\", true);\n    const teamName = interaction.options.getString(\"team\", true);\n    const position = interaction.options.getString(\"position\", true);\n    const region = interaction.options.getString(\"region\", true);\n    const role = interaction.options.getString(\"role\") as TeamRole | null;\n    const roblox = interaction.options.getString(\"roblox\");\n    const nickname = interaction.options.getString(\"nickname\");\n\n    try {\n      const { player, contract, team } = await contractService.offerContract({\n        discordId: target.id,\n        username: target.username,\n        teamName,\n        position,\n        region,\n        robloxUsername: roblox ?? undefined,\n        roleInTeam: role ?? undefined,\n        nickname: nickname ?? undefined,\n      });\n\n      // Auto-nickname if provided\n      let nicknameResult = \"None\";\n      if (nickname && interaction.guild) {\n        try {\n          const member = await interaction.guild.members.fetch(target.id);\n          await member.setNickname(nickname);\n          nicknameResult = `✅ Set to **${nickname}**`;\n        } catch {\n          nicknameResult = \"⚠️ Could not set nickname (check bot permissions)\";\n        }\n      }\n\n      const embed = new EmbedBuilder()\n        .setTitle(\"📝 Contract Offered!\")\n        .setColor(\"#00AA00\")\n        .setDescription(`**${target.username}** has joined **${team.name}**!`)\n        .addFields(\n          { name: \"👤 Player\", value: `<@${target.id}>`, inline: true },\n          { name: \"🏟️ Team\", value: team.name, inline: true },\n          { name: \"⚽ Position\", value: position, inline: true },\n          { name: \"🌍 Region\", value: region, inline: true },\n          { name: \"🎭 Role\", value: role ?? \"Starter\", inline: true },\n          { name: \"🆔 LFC ID\", value: player.lfcId, inline: true },\n          { name: \"🎮 Roblox\", value: roblox ?? \"Not set\", inline: true },\n          { name: \"📛 Nickname\", value: nicknameResult, inline: false },\n        )\n        .setFooter({ text: `Contract ID: ${contract.id.slice(0, 8)} • Legacy Football Championship` })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error: unknown) {\n      const msg = error instanceof Error ? error.message : \"Unknown error\";\n      await interaction.editReply({ content: `❌ ${msg}` });\n    }\n  },\n};\n\nexport default command;","src/commands/release/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { contractService } from \"../../services/contractService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"release\")\n    .setDescription(\"Release a player from their team back to free agency (Management only)\")\n    .addUserOption((opt) =>\n      opt.setName(\"player\").setDescription(\"Player to release\").setRequired(true)\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    if (!hasRole(interaction.member as never, RoleType.Founder) &&\n        !hasRole(interaction.member as never, RoleType.LeagueManagement)) {\n      await interaction.editReply({\n        embeds: [createErrorEmbed(\"❌ Insufficient Permissions\",\"You need **Founder** or **League Management** role.\")],\n      });\n      return;\n    }\n\n    const target = interaction.options.getUser(\"player\", true);\n\n    try {\n      const player = await contractService.releasePlayer(target.id);\n      const embed = new EmbedBuilder()\n        .setTitle(\"🆓 Player Released\")\n        .setColor(\"#FFAA00\")\n        .setDescription(`**${target.username}** has been released from **${player.team?.name ?? \"their club\"}** and is now a free agent.`)\n        .addFields(\n          { name: \"👤 Player\", value: `<@${target.id}>`, inline: true },\n          { name: \"📊 Status\", value: \"🆓 Free Agent\", inline: true },\n          { name: \"⚽ Career Stats\", value: `${player.goals}G / ${player.assists}A / ${player.appearances} Apps`, inline: false },\n        )\n        .setFooter({ text: \"Legacy Football Championship • Transfers\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error: unknown) {\n      const msg = error instanceof Error ? error.message : \"Unknown error\";\n      await interaction.editReply({ content: `❌ ${msg}` });\n    }\n  },\n};\n\nexport default command;","src/commands/freeagents/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { contractService } from \"../../services/contractService.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"freeagents\")\n    .setDescription(\"List all available free agents (unassigned players)\"),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const freeAgents = await contractService.getFreeAgents();\n\n    const embed = new EmbedBuilder()\n      .setTitle(\"🆓 Free Agents\")\n      .setColor(\"#00AA00\");\n\n    if (freeAgents.length === 0) {\n      embed.setDescription(\"No free agents available. All players are under contract.\");\n    } else {\n      // Group by position\n      const grouped: Record<string, typeof freeAgents> = {};\n      for (const p of freeAgents) {\n        if (!grouped[p.position]) grouped[p.position] = [];\n        grouped[p.position].push(p);\n      }\n\n      for (const [pos, players] of Object.entries(grouped)) {\n        const emojis: Record<string, string> = {\n          Goalkeeper: \"🧤\", Defender: \"🛡️\", Midfielder: \"🎯\", Forward: \"⚽\",\n        };\n        embed.addFields({\n          name: `${emojis[pos] ?? \"👤\"} ${pos}s (${players.length})`,\n          value: players\n            .slice(0, 8)\n            .map((p) =>\n              `**${p.user.username}** — ⚽${p.goals}G / 🎯${p.assists}A / 📋${p.appearances}Apps`\n            )\n            .join(\"\\n\") + (players.length > 8 ? `\\n*+${players.length - 8} more...*` : \"\"),\n          inline: false,\n        });\n      }\n    }\n\n    embed\n      .setFooter({ text: `Total: ${freeAgents.length} free agents • Use /offer to sign` })\n      .setTimestamp();\n\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\n\nexport default command;","src/commands/profile/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { playerService } from \"../../services/playerService.js\";\nimport { contractService } from \"../../services/contractService.js\";\nimport { formatDate, formatSeasonStats } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"profile\")\n    .setDescription(\"View a unified player profile with Roblox info and season stats\")\n    .addUserOption((opt) =>\n      opt.setName(\"player\").setDescription(\"Player to view\").setRequired(true)\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const target = interaction.options.getUser(\"player\", true);\n\n    try {\n      const player = await playerService.getPlayer(target.id);\n      if (!player) {\n        await interaction.editReply({\n          content: `❌ ${target.username} is not registered as an LFC player.`,\n        });\n        return;\n      }\n\n      const contract = await contractService.getActiveContract(player.id);\n\n      // Build season stats string\n      const activeStat = player.seasonStats.find((s) => s.season.isActive);\n      const seasonLine = activeStat\n        ? formatSeasonStats({\n            goals: activeStat.goals,\n            assists: activeStat.assists,\n            saves: activeStat.saves,\n            mvps: activeStat.mvps,\n            appearances: activeStat.appearances,\n            yellowCards: activeStat.yellowCards,\n            redCards: activeStat.redCards,\n            cleanSheets: activeStat.cleanSheets,\n          })\n        : \"No active season data.\";\n\n      const embed = new EmbedBuilder()\n        .setTitle(`👤 ${target.username} — Player Profile`)\n        .setThumbnail(target.displayAvatarURL())\n        .setColor(\"#00AA00\")\n        .addFields(\n          {\n            name: \"🆔 Identity\",\n            value: [\n              `**LFC ID:** ${player.lfcId}`,\n              `**Discord:** ${target.username}`,\n              player.robloxUsername ? `**Roblox:** ${player.robloxUsername}` : null,\n              `**Joined:** ${formatDate(player.joinedAt)}`,\n            ].filter(Boolean).join(\"\\n\"),\n            inline: true,\n          },\n          {\n            name: \"⚽ Football\",\n            value: [\n              `**Club:** ${player.team?.name ?? \"🆓 Free Agent\"}`,\n              `**Position:** ${player.position}`,\n              `**Region:** ${player.region}`,\n              player.nickname ? `**Nickname:** ${player.nickname}` : null,\n            ].filter(Boolean).join(\"\\n\"),\n            inline: true,\n          },\n          {\n            name: \"🎭 Team Role\",\n            value: player.roleInTeam ?? \"Unassigned\",\n            inline: true,\n          },\n          {\n            name: \"📈 Active Season Stats\",\n            value: seasonLine,\n            inline: false,\n          },\n          {\n            name: \"🏆 Career Totals\",\n            value: formatSeasonStats({\n              goals: player.goals,\n              assists: player.assists,\n              saves: player.saves,\n              mvps: player.mvps,\n              appearances: player.appearances,\n              yellowCards: player.yellowCards,\n              redCards: player.redCards,\n              cleanSheets: player.cleanSheets,\n            }),\n            inline: false,\n          },\n          {\n            name: \"📋 Contract\",\n            value: contract\n              ? `**${contract.team.name}** — ${contract.roleInTeam ?? \"Starter\"}\\nSigned: ${formatDate(contract.signedAt)}`\n              : \"No active contract\",\n            inline: false,\n          },\n        )\n        .setFooter({ text: `Trophies: ${player.trophies} 🏆 | Legacy Football Championship` })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Profile Error]\", error);\n      await interaction.editReply({ content: \"❌ An error occurred.\" });\n    }\n  },\n};\n\nexport default command;","src/commands/topscorers/index.ts":"import { SlashCommandBuilder, CommandInteraction, EmbedBuilder } from \"discord.js\";\nimport { playerService } from \"../../services/playerService.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"topscorers\")\n    .setDescription(\"View the top goalscorers leaderboard\"),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n    const players = await playerService.getTopGoalscorers(15);\n    const embed = new EmbedBuilder()\n      .setTitle(\"⚽ Top Goalscorers\")\n      .setColor(\"#FFD700\")\n      .setDescription(players.length\n        ? players.map((p, i) =>\n            `${i + 1}. **${p.user.globalName ?? p.user.username}**${p.team ? ` (${p.team.name})` : \"\"} — **${p.goals}G**`)\n          .join(\"\\n\")\n        : \"No data yet.\"\n      )\n      .setFooter({ text: \"Legacy Football Championship\" }).setTimestamp();\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\nexport default command;","src/commands/topassists/index.ts":"import { SlashCommandBuilder, CommandInteraction, EmbedBuilder } from \"discord.js\";\nimport { playerService } from \"../../services/playerService.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"topassists\")\n    .setDescription(\"View the top assists leaderboard\"),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n    const players = await playerService.getTopAssists(15);\n    const embed = new EmbedBuilder()\n      .setTitle(\"🎯 Top Assists\")\n      .setColor(\"#00AAFF\")\n      .setDescription(players.length\n        ? players.map((p, i) =>\n            `${i + 1}. **${p.user.globalName ?? p.user.username}**${p.team ? ` (${p.team.name})` : \"\"} — **${p.assists}A**`)\n          .join(\"\\n\")\n        : \"No data yet.\"\n      )\n      .setFooter({ text: \"Legacy Football Championship\" }).setTimestamp();\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\nexport default command;","src/commands/topsaves/index.ts":"import { SlashCommandBuilder, CommandInteraction, EmbedBuilder } from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"topsaves\")\n    .setDescription(\"View the top saves leaderboard (Goalkeepers)\"),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n    const players = await prisma.player.findMany({\n      where: { position: \"Goalkeeper\" },\n      orderBy: { saves: \"desc\" },\n      take: 15,\n      include: { user: true, team: true },\n    });\n    const embed = new EmbedBuilder()\n      .setTitle(\"🧤 Top Saves\")\n      .setColor(\"#00AA00\")\n      .setDescription(players.length\n        ? players.map((p, i) =>\n            `${i + 1}. **${p.user.globalName ?? p.user.username}**${p.team ? ` (${p.team.name})` : \"\"} — **${p.saves} saves** | 🧹 ${p.cleanSheets} CS`)\n          .join(\"\\n\")\n        : \"No goalkeeper data yet.\"\n      )\n      .setFooter({ text: \"Legacy Football Championship\" }).setTimestamp();\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\nexport default command;","src/commands/leaderboards/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n  ActionRowBuilder,\n  StringSelectMenuBuilder,\n  ComponentType,\n} from \"discord.js\";\nimport { playerService } from \"../../services/playerService.js\";\nimport { predictionService } from \"../../services/predictionService.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { leagueService } from \"../../services/leagueService.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst BOARDS = [\n  { label: \"⚽ Golden Boot (Goals)\", value: \"goals\", emoji: \"⚽\" },\n  { label: \"🎯 Playmaker (Assists)\", value: \"assists\", emoji: \"🎯\" },\n  { label: \"🧤 Golden Glove (Saves)\", value: \"saves\", emoji: \"🧤\" },\n  { label: \"🏆 Most MVPs\", value: \"mvps\", emoji: \"🏆\" },\n  { label: \"📋 Most Appearances\", value: \"apps\", emoji: \"📋\" },\n  { label: \"🔮 Prediction King\", value: \"predictions\", emoji: \"🔮\" },\n];\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"leaderboards\")\n    .setDescription(\"View all award rankings in one place with a dropdown\"),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n    await showBoard(interaction, \"goals\");\n  },\n};\n\nasync function showBoard(interaction: CommandInteraction, type: string) {\n  let embed: EmbedBuilder;\n\n  switch (type) {\n    case \"assists\": {\n      const players = await playerService.getTopAssists(10);\n      embed = makeBoardEmbed(\"🎯 Playmaker Rankings — Top Assists\", \"#00AAFF\", players, \"assists\", \"A\");\n      break;\n    }\n    case \"saves\": {\n      const players = await prisma.player.findMany({ where: { position: \"Goalkeeper\" }, orderBy: { saves: \"desc\" }, take: 10, include: { user: true, team: true } });\n      embed = new EmbedBuilder().setTitle(\"🧤 Golden Glove — Top Saves\").setColor(\"#00AA00\")\n        .setDescription(players.length ? players.map((p, i) => `${i + 1}. **${p.user.globalName ?? p.user.username}**${p.team ? ` (${p.team.name})` : \"\"} — **${p.saves} saves** | 🧹 ${p.cleanSheets} CS`).join(\"\\n\") : \"No data.\")\n        .setFooter({ text: \"Legacy Football Championship\" }).setTimestamp();\n      break;\n    }\n    case \"mvps\": {\n      const players = await playerService.getTopMvps(10);\n      embed = makeBoardEmbed(\"🏆 Most Valuable Players — Top MVPs\", \"#FFD700\", players, \"mvps\", \"MVP\");\n      break;\n    }\n    case \"apps\": {\n      const players = await playerService.getTopAppearances(10);\n      embed = makeBoardEmbed(\"📋 Iron Men — Most Appearances\", \"#00AA00\", players, \"appearances\", \"Apps\");\n      break;\n    }\n    case \"predictions\": {\n      const season = await leagueService.getActiveSeason();\n      const list = season ? await predictionService.getLeaderboard(season.id) : [];\n      embed = new EmbedBuilder().setTitle(\"🔮 Prediction King\").setColor(\"#FF6600\")\n        .setDescription(list.length\n          ? list.slice(0, 10).map((u, i) => `${i + 1}. <@${u.userId}> — **${u.points} pts**`).join(\"\\n\")\n          : \"No predictions yet. Use `/predict` on matches!\")\n        .setFooter({ text: \"Legacy Football Championship\" }).setTimestamp();\n      break;\n    }\n    default: {\n      const players = await playerService.getTopGoalscorers(10);\n      embed = makeBoardEmbed(\"⚽ Golden Boot — Top Goalscorers\", \"#FFD700\", players, \"goals\", \"G\");\n    }\n  }\n\n  const select = new StringSelectMenuBuilder()\n    .setCustomId(\"lb_select\").setPlaceholder(\"Switch leaderboard...\")\n    .addOptions(BOARDS.map((b) => ({ label: b.label, value: b.value })));\n\n  const row = new ActionRowBuilder<StringSelectMenuBuilder>().addComponents(select);\n  const reply = await interaction.editReply({ embeds: [embed], components: [row] });\n\n  const collector = reply.createMessageComponentCollector({ componentType: ComponentType.StringSelect, time: 120_000 });\n  collector.on(\"collect\", async (si) => {\n    if (si.user.id !== interaction.user.id) { await si.reply({ content: \"❌ Not your menu.\", ephemeral: true }); return; }\n    await si.deferUpdate();\n    await showBoard(si as unknown as CommandInteraction, si.values[0]);\n  });\n  collector.on(\"end\", async () => {\n    const dr = ActionRowBuilder.from<StringSelectMenuBuilder>(row);\n    dr.components.forEach((c) => c.setDisabled(true));\n    await interaction.editReply({ components: [dr] });\n  });\n}\n\nfunction makeBoardEmbed(title: string, color: string, players: Array<{ user: { username: string; globalName: string | null }; team: { name: string } | null; goals: number; assists: number; mvps: number; appearances: number }>, key: string, suffix: string) {\n  return new EmbedBuilder().setTitle(title).setColor(color as never)\n    .setDescription(players.length\n      ? players.map((p, i) => `${i + 1}. **${p.user.globalName ?? p.user.username}**${p.team ? ` (${p.team.name})` : \"\"} — **${(p as Record<string, number>)[key] ?? 0}${suffix}**`).join(\"\\n\")\n      : \"No data.\")\n    .setFooter({ text: \"Legacy Football Championship\" }).setTimestamp();\n}\n\nexport default command;","src/commands/squad/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { teamService } from \"../../services/teamService.js\";\nimport type { Command, Position } from \"../../types/index.js\";\n\nconst POSITION_ORDER: Position[] = [\"Goalkeeper\", \"Defender\", \"Midfielder\", \"Forward\"];\nconst POS_EMOJIS: Record<string, string> = { Goalkeeper: \"🧤\", Defender: \"🛡️\", Midfielder: \"🎯\", Forward: \"⚽\" };\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"squad\")\n    .setDescription(\"Display a club's full roster\")\n    .addStringOption((opt) =>\n      opt.setName(\"team\").setDescription(\"Team name\").setRequired(true)\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const teamName = interaction.options.getString(\"team\", true);\n    const team = await teamService.getTeamByName(teamName);\n    if (!team) {\n      await interaction.editReply({ content: `❌ Team **${teamName}** not found.` });\n      return;\n    }\n\n    const embed = new EmbedBuilder()\n      .setTitle(`👥 ${team.name} — Full Squad`)\n      .setColor(\"#00AA00\")\n      .setDescription(\n        team.players.length\n          ? `**Manager:** <@${team.manager.discordId}> | **Total:** ${team.players.length} players`\n          : \"No players registered.\"\n      );\n\n    // Group by role then position\n    const captains = team.players.filter((p) => p.roleInTeam === \"Captain\" || p.roleInTeam === \"Vice Captain\");\n    const starters = team.players.filter((p) => p.roleInTeam === \"Starter\" || !p.roleInTeam);\n    const subs = team.players.filter((p) => p.roleInTeam === \"Sub\" || p.roleInTeam === \"Academy\");\n\n    if (captains.length) {\n      embed.addFields({\n        name: \"👑 Leadership\",\n        value: captains.map((p) => `**${p.roleInTeam}:** ${p.user.username} (${p.position})`).join(\"\\n\"),\n        inline: false,\n      });\n    }\n\n    for (const pos of POSITION_ORDER) {\n      const posPlayers = starters.filter((p) => p.position === pos);\n      if (posPlayers.length) {\n        embed.addFields({\n          name: `${POS_EMOJIS[pos] ?? \"👤\"} ${pos}s (${posPlayers.length})`,\n          value: posPlayers\n            .map((p) => `**${p.user.username}** — ⚽${p.goals}G / 🎯${p.assists}A / 📋${p.appearances}Apps`)\n            .join(\"\\n\"),\n          inline: false,\n        });\n      }\n    }\n\n    if (subs.length) {\n      embed.addFields({\n        name: \"🔄 Substitutes & Academy\",\n        value: subs.map((p) => `**${p.user.username}** (${p.position}${p.roleInTeam ? ` — ${p.roleInTeam}` : \"\"})`).join(\"\\n\"),\n        inline: false,\n      });\n    }\n\n    embed.setFooter({ text: \"Legacy Football Championship\" }).setTimestamp();\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\n\nexport default command;","src/commands/club/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n  ActionRowBuilder,\n  StringSelectMenuBuilder,\n  ComponentType,\n} from \"discord.js\";\nimport { teamService } from \"../../services/teamService.js\";\nimport { matchService } from \"../../services/matchService.js\";\nimport { playerService } from \"../../services/playerService.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"club\")\n    .setDescription(\"View a complete team hub with stats, history, and roster\")\n    .addStringOption((opt) =>\n      opt.setName(\"team\").setDescription(\"Team name\").setRequired(true)\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n    const teamName = interaction.options.getString(\"team\", true);\n    const team = await teamService.getTeamByName(teamName);\n    if (!team) {\n      await interaction.editReply({ content: `❌ Team **${teamName}** not found.` });\n      return;\n    }\n    await showClubPage(interaction, team, \"stats\");\n  },\n};\n\nasync function showClubPage(interaction: CommandInteraction, team: Awaited<ReturnType<typeof teamService.getTeamByName>>, tab: string) {\n  if (!team) return;\n  let embed: EmbedBuilder;\n\n  switch (tab) {\n    case \"roster\": {\n      const posOrder = [\"Goalkeeper\", \"Defender\", \"Midfielder\", \"Forward\"];\n      embed = new EmbedBuilder().setTitle(`👥 ${team.name} — Roster`).setColor(\"#00AA00\");\n      for (const pos of posOrder) {\n        const filtered = team.players.filter((p) => p.position === pos);\n        if (filtered.length) embed.addFields({ name: `${pos}s (${filtered.length})`, value: filtered.map((p) => `**${p.user.username}**${p.roleInTeam ? ` — ${p.roleInTeam}` : \"\"} — ⚽${p.goals}G 🎯${p.assists}A`).join(\"\\n\"), inline: false });\n      }\n      break;\n    }\n    case \"history\": {\n      const matches = await matchService.getTeamMatches(team.id);\n      embed = new EmbedBuilder().setTitle(`📊 ${team.name} — Match History`).setColor(\"#00AA00\");\n      if (matches.length) {\n        const finished = matches.filter((m) => m.status === \"Finished\").slice(0, 10);\n        embed.setDescription(finished.length\n          ? finished.map((m) => {\n              const isHome = m.homeTeamId === team.id;\n              const score = isHome ? `${m.homeScore}-${m.awayScore}` : `${m.awayScore}-${m.homeScore}`;\n              const opponent = isHome ? m.awayTeam.name : m.homeTeam.name;\n              const result = isHome ? (m.homeScore > m.awayScore ? \"✅ W\" : m.homeScore < m.awayScore ? \"❌ L\" : \"🤝 D\") : (m.awayScore > m.homeScore ? \"✅ W\" : m.awayScore < m.homeScore ? \"❌ L\" : \"🤝 D\");\n              return `${result} | ${team.name} ${score} vs ${opponent}`;\n            }).join(\"\\n\")\n          : \"No finished matches.\"\n        );\n      } else {\n        embed.setDescription(\"No matches played yet.\");\n      }\n      break;\n    }\n    default: {\n      const ss = team.seasonTeams[team.seasonTeams.length - 1];\n      embed = new EmbedBuilder()\n        .setTitle(`🏟️ ${team.name} ${team.shortName ? `(${team.shortName})` : \"\"}`)\n        .setColor(\"#00AA00\")\n        .setDescription(team.description ?? \"No description.\")\n        .addFields(\n          { name: \"👤 Manager\", value: `<@${team.manager.discordId}>`, inline: true },\n          { name: \"👥 Squad\", value: `${team.players.length} players`, inline: true },\n          { name: \"🏆 Trophies\", value: `${team.trophies}`, inline: true }\n        );\n      if (ss) {\n        const gd = ss.goalsFor - ss.goalsAgainst;\n        embed.addFields({ name: \"📊 Season Record\", value: `**${ss.played}**PL | **${ss.wins}**W | **${ss.draws}**D | **${ss.losses}**L | GF:${ss.goalsFor} GA:${ss.goalsAgainst} GD:${gd >= 0 ? \"+\" : \"\"}${gd} | **${ss.points}pts**`, inline: false });\n      }\n      const top = [...team.players].sort((a, b) => b.goals - a.goals).slice(0, 3);\n      if (top.length) embed.addFields({ name: \"⚽ Top Scorers\", value: top.map((p, i) => `${i + 1}. **${p.user.username}** — ${p.goals}G`).join(\"\\n\"), inline: false });\n    }\n  }\n\n  const select = new StringSelectMenuBuilder().setCustomId(\"club_tabs\").setPlaceholder(\"Switch tab...\")\n    .addOptions(\n      { label: \"📊 Stats & Info\", value: \"stats\", emoji: \"📊\", default: tab === \"stats\" },\n      { label: \"👥 Roster\", value: \"roster\", emoji: \"👥\", default: tab === \"roster\" },\n      { label: \"📋 Match History\", value: \"history\", emoji: \"📋\", default: tab === \"history\" },\n    );\n\n  const row = new ActionRowBuilder<StringSelectMenuBuilder>().addComponents(select);\n  const reply = await interaction.editReply({ embeds: [embed], components: [row] });\n\n  const collector = reply.createMessageComponentCollector({ componentType: ComponentType.StringSelect, time: 120_000 });\n  collector.on(\"collect\", async (si) => {\n    if (si.user.id !== interaction.user.id) { await si.reply({ content: \"❌ Not your menu.\", ephemeral: true }); return; }\n    await si.deferUpdate();\n    const refreshed = await teamService.getTeamByName(team.name);\n    if (refreshed) await showClubPage(si as unknown as CommandInteraction, refreshed, si.values[0]);\n  });\n  collector.on(\"end\", async () => {\n    const dr = ActionRowBuilder.from<StringSelectMenuBuilder>(row);\n    dr.components.forEach((c) => c.setDisabled(true));\n    await interaction.editReply({ components: [dr] }).catch(() => {});\n  });\n}\n\nexport default command;","src/commands/creatematch/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n  ChannelType,\n} from \"discord.js\";\nimport { matchService } from \"../../services/matchService.js\";\nimport { leagueService } from \"../../services/leagueService.js\";\nimport { teamService } from \"../../services/teamService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command, ExtendedClient } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"creatematch\")\n    .setDescription(\"Create a match with thread for live updates (Management/Referee)\")\n    .addStringOption((o) => o.setName(\"home\").setDescription(\"Home team\").setRequired(true))\n    .addStringOption((o) => o.setName(\"away\").setDescription(\"Away team\").setRequired(true))\n    .addIntegerOption((o) => o.setName(\"week\").setDescription(\"Matchweek number\").setRequired(false))\n    .addUserOption((o) => o.setName(\"referee\").setDescription(\"Referee\").setRequired(false))\n    .addBooleanOption((o) => o.setName(\"createthread\").setDescription(\"Create a match thread?\").setRequired(false)),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    if (!hasRole(interaction.member as never, RoleType.Founder) &&\n        !hasRole(interaction.member as never, RoleType.LeagueManagement) &&\n        !hasRole(interaction.member as never, RoleType.Referee)) {\n      await interaction.editReply({ embeds: [createErrorEmbed(\"❌ Insufficient Permissions\", \"Need Staff role.\")] });\n      return;\n    }\n\n    const homeName = interaction.options.getString(\"home\", true);\n    const awayName = interaction.options.getString(\"away\", true);\n    const week = interaction.options.getInteger(\"week\");\n    const refUser = interaction.options.getUser(\"referee\");\n    const createThread = interaction.options.getBoolean(\"createthread\") ?? true;\n\n    const homeTeam = await teamService.getTeamByName(homeName);\n    const awayTeam = await teamService.getTeamByName(awayName);\n    if (!homeTeam || !awayTeam) {\n      await interaction.editReply({ content: \"❌ One or both teams not found.\" });\n      return;\n    }\n    if (homeTeam.id === awayTeam.id) {\n      await interaction.editReply({ embeds: [createErrorEmbed(\"❌ Invalid\", \"Cannot play itself.\")] });\n      return;\n    }\n\n    const activeSeason = await leagueService.getActiveSeason();\n    if (!activeSeason) {\n      await interaction.editReply({ embeds: [createErrorEmbed(\"❌ No Active Season\", \"Start a season first.\")] });\n      return;\n    }\n\n    const match = await matchService.createMatch({\n      homeTeamId: homeTeam.id,\n      awayTeamId: awayTeam.id,\n      seasonId: activeSeason.id,\n      refereeId: refUser?.id,\n    });\n\n    // Update matchweek\n    if (week) {\n      await (await import(\"../../database/prisma.js\")).prisma.match.update({\n        where: { id: match.id },\n        data: { matchweek: week },\n      });\n    }\n\n    // Create thread\n    let threadInfo = \"No thread created.\";\n    if (createThread && interaction.channel && interaction.channel.type === ChannelType.GuildText) {\n      try {\n        const thread = await interaction.channel.threads.create({\n          name: `⚽ ${homeTeam.name} vs ${awayTeam.name}${week ? ` (GW${week})` : \"\"}`,\n          reason: \"Match thread for live updates\",\n        });\n        await thread.send(`⚽ **${homeTeam.name}** vs **${awayTeam.name}**\\n📅 ${activeSeason.name}${refUser ? `\\n👨‍⚖️ Referee: <@${refUser.id}>` : \"\"}\\n\\nUse **/goal**, **/assist**, **/yellow**, **/red** in this thread to log events!`);\n        await (await import(\"../../database/prisma.js\")).prisma.match.update({\n          where: { id: match.id },\n          data: { threadId: thread.id },\n        });\n        threadInfo = `📝 Thread created: ${thread}`;\n      } catch { threadInfo = \"⚠️ Could not create thread.\"; }\n    }\n\n    const embed = new EmbedBuilder()\n      .setTitle(\"⚽ Match Created!\")\n      .setColor(\"#00AA00\")\n      .addFields(\n        { name: \"🏠 Home\", value: homeTeam.name, inline: true },\n        { name: \"🆚 vs\", value: awayTeam.name, inline: true },\n        { name: \"📅 Week\", value: week ? `GW${week}` : \"TBD\", inline: true },\n        { name: \"👨‍⚖️ Referee\", value: refUser ? `<@${refUser.id}>` : \"TBD\", inline: true },\n        { name: \"🆔 Match ID\", value: match.id.slice(0, 8), inline: true },\n        { name: \"📋 Status\", value: \"🟢 Scheduled\", inline: true },\n        { name: \"📎 Thread\", value: threadInfo, inline: false },\n      )\n      .setFooter({ text: \"Use /match start or /fulltime when ready\" })\n      .setTimestamp();\n\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\nexport default command;","src/commands/goal/index.ts":"import { SlashCommandBuilder, CommandInteraction, EmbedBuilder } from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command, ExtendedClient } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"goal\")\n    .setDescription(\"Quick log a goal during a live match\")\n    .addStringOption((o) => o.setName(\"match_id\").setDescription(\"Match ID\").setRequired(true))\n    .addUserOption((o) => o.setName(\"scorer\").setDescription(\"Player who scored\").setRequired(true))\n    .addUserOption((o) => o.setName(\"assist\").setDescription(\"Player who assisted\").setRequired(false))\n    .addIntegerOption((o) => o.setName(\"minute\").setDescription(\"Minute scored\").setRequired(false)),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n    if (!hasRole(interaction.member as never, RoleType.Founder) && !hasRole(interaction.member as never, RoleType.LeagueManagement) && !hasRole(interaction.member as never, RoleType.Referee)) {\n      await interaction.editReply({ embeds: [createErrorEmbed(\"❌ Permissions\", \"Staff only.\")] }); return;\n    }\n\n    const matchId = interaction.options.getString(\"match_id\", true);\n    const scorer = interaction.options.getUser(\"scorer\", true);\n    const assist = interaction.options.getUser(\"assist\");\n    const minute = interaction.options.getInteger(\"minute\");\n\n    const player = await prisma.player.findUnique({ where: { discordId: scorer.id } });\n    if (!player) { await interaction.editReply({ content: \"❌ Scorer not registered.\" }); return; }\n\n    await prisma.matchGoal.create({ data: { matchId, playerId: player.id, minute } });\n    await prisma.player.update({ where: { id: player.id }, data: { goals: { increment: 1 }, appearances: { increment: 1 } } });\n    await updatePlayerSeasonStat(player.id, matchId, \"goals\");\n\n    let assistText = \"\";\n    if (assist) {\n      const aPlayer = await prisma.player.findUnique({ where: { discordId: assist.id } });\n      if (aPlayer) {\n        await prisma.matchAssist.create({ data: { matchId, playerId: aPlayer.id, minute } });\n        await prisma.player.update({ where: { id: aPlayer.id }, data: { assists: { increment: 1 } } });\n        assistText = `\\n🎯 **Assist:** <@${assist.id}>`;\n      }\n    }\n\n    const embed = new EmbedBuilder()\n      .setTitle(\"⚽ GOAL!\")\n      .setColor(\"#00AA00\")\n      .setDescription(`**<@${scorer.id}>** scores!${assistText}`)\n      .addFields(\n        { name: \"🔢 Match\", value: matchId.slice(0, 8), inline: true },\n        { name: \"⏱ Minute\", value: minute ? `${minute}'` : \"N/A\", inline: true },\n      )\n      .setFooter({ text: \"Legacy Football Championship • Live\" }).setTimestamp();\n\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\n\nasync function updatePlayerSeasonStat(playerId: string, matchId: string, field: string) {\n  const match = await prisma.match.findUnique({ where: { id: matchId }, select: { seasonId: true } });\n  if (!match) return;\n  const stat = await prisma.playerSeasonStats.findUnique({\n    where: { playerId_seasonId: { playerId, seasonId: match.seasonId } },\n  });\n  if (stat) {\n    await prisma.playerSeasonStats.update({ where: { id: stat.id }, data: { [field]: { increment: 1 } } });\n  }\n}\n\nexport default command;","src/commands/assist/index.ts":"import { SlashCommandBuilder, CommandInteraction, EmbedBuilder } from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"assist\")\n    .setDescription(\"Quick log an assist during a live match\")\n    .addStringOption((o) => o.setName(\"match_id\").setDescription(\"Match ID\").setRequired(true))\n    .addUserOption((o) => o.setName(\"player\").setDescription(\"Player who assisted\").setRequired(true))\n    .addIntegerOption((o) => o.setName(\"minute\").setDescription(\"Minute\").setRequired(false)),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n    if (!hasRole(interaction.member as never, RoleType.Founder) && !hasRole(interaction.member as never, RoleType.LeagueManagement) && !hasRole(interaction.member as never, RoleType.Referee)) {\n      await interaction.editReply({ embeds: [createErrorEmbed(\"❌ Permissions\", \"Staff only.\")] }); return;\n    }\n    const matchId = interaction.options.getString(\"match_id\", true);\n    const target = interaction.options.getUser(\"player\", true);\n    const minute = interaction.options.getInteger(\"minute\");\n    const player = await prisma.player.findUnique({ where: { discordId: target.id } });\n    if (!player) { await interaction.editReply({ content: \"❌ Player not registered.\" }); return; }\n    await prisma.matchAssist.create({ data: { matchId, playerId: player.id, minute } });\n    await prisma.player.update({ where: { id: player.id }, data: { assists: { increment: 1 } } });\n    const embed = new EmbedBuilder().setTitle(\"🎯 Assist Logged\").setColor(\"#00AAFF\")\n      .setDescription(`**<@${target.id}>** provided the assist!`)\n      .addFields({ name: \"🔢 Match\", value: matchId.slice(0, 8), inline: true }, { name: \"⏱ Minute\", value: minute ? `${minute}'` : \"N/A\", inline: true })\n      .setFooter({ text: \"Legacy Football Championship • Live\" }).setTimestamp();\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\nexport default command;","src/commands/yellow/index.ts":"import { SlashCommandBuilder, CommandInteraction, EmbedBuilder } from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"yellow\")\n    .setDescription(\"Log a yellow card during a match\")\n    .addStringOption((o) => o.setName(\"match_id\").setDescription(\"Match ID\").setRequired(true))\n    .addUserOption((o) => o.setName(\"player\").setDescription(\"Player booked\").setRequired(true))\n    .addIntegerOption((o) => o.setName(\"minute\").setDescription(\"Minute\").setRequired(false))\n    .addStringOption((o) => o.setName(\"reason\").setDescription(\"Reason\").setRequired(false)),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n    if (!hasRole(interaction.member as never, RoleType.Founder) && !hasRole(interaction.member as never, RoleType.LeagueManagement) && !hasRole(interaction.member as never, RoleType.Referee)) {\n      await interaction.editReply({ embeds: [createErrorEmbed(\"❌ Permissions\", \"Staff only.\")] }); return;\n    }\n    const matchId = interaction.options.getString(\"match_id\", true);\n    const target = interaction.options.getUser(\"player\", true);\n    const minute = interaction.options.getInteger(\"minute\");\n    const reason = interaction.options.getString(\"reason\");\n    const player = await prisma.player.findUnique({ where: { discordId: target.id } });\n    if (!player) { await interaction.editReply({ content: \"❌ Player not registered.\" }); return; }\n    await prisma.matchCard.create({ data: { matchId, playerId: player.id, type: \"Yellow\", minute, reason } });\n    await prisma.player.update({ where: { id: player.id }, data: { yellowCards: { increment: 1 } } });\n    const embed = new EmbedBuilder().setTitle(\"🟨 Yellow Card\").setColor(\"#FFAA00\")\n      .setDescription(`**<@${target.id}>** has been booked!`)\n      .addFields({ name: \"🔢 Match\", value: matchId.slice(0, 8), inline: true }, { name: \"⏱ Minute\", value: minute ? `${minute}'` : \"N/A\", inline: true }, { name: \"📝 Reason\", value: reason ?? \"Foul\", inline: false })\n      .setFooter({ text: \"Legacy Football Championship • Live\" }).setTimestamp();\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\nexport default command;","src/commands/red/index.ts":"import { SlashCommandBuilder, CommandInteraction, EmbedBuilder } from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"red\")\n    .setDescription(\"Log a red card during a match\")\n    .addStringOption((o) => o.setName(\"match_id\").setDescription(\"Match ID\").setRequired(true))\n    .addUserOption((o) => o.setName(\"player\").setDescription(\"Player sent off\").setRequired(true))\n    .addIntegerOption((o) => o.setName(\"minute\").setDescription(\"Minute\").setRequired(false))\n    .addStringOption((o) => o.setName(\"reason\").setDescription(\"Reason\").setRequired(false)),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n    if (!hasRole(interaction.member as never, RoleType.Founder) && !hasRole(interaction.member as never, RoleType.LeagueManagement) && !hasRole(interaction.member as never, RoleType.Referee)) {\n      await interaction.editReply({ embeds: [createErrorEmbed(\"❌ Permissions\", \"Staff only.\")] }); return;\n    }\n    const matchId = interaction.options.getString(\"match_id\", true);\n    const target = interaction.options.getUser(\"player\", true);\n    const minute = interaction.options.getInteger(\"minute\");\n    const reason = interaction.options.getString(\"reason\");\n    const player = await prisma.player.findUnique({ where: { discordId: target.id } });\n    if (!player) { await interaction.editReply({ content: \"❌ Player not registered.\" }); return; }\n    await prisma.matchCard.create({ data: { matchId, playerId: player.id, type: \"Red\", minute, reason } });\n    await prisma.player.update({ where: { id: player.id }, data: { redCards: { increment: 1 } } });\n    const embed = new EmbedBuilder().setTitle(\"🟥 RED CARD!\").setColor(\"#FF0000\")\n      .setDescription(`**<@${target.id}>** has been sent off!`)\n      .addFields({ name: \"🔢 Match\", value: matchId.slice(0, 8), inline: true }, { name: \"⏱ Minute\", value: minute ? `${minute}'` : \"N/A\", inline: true }, { name: \"📝 Reason\", value: reason ?? \"Serious foul play\", inline: false })\n      .setFooter({ text: \"Legacy Football Championship • Live\" }).setTimestamp();\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\nexport default command;","src/commands/fulltime/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { matchService } from \"../../services/matchService.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { newsService } from \"../../services/newsService.js\";\nimport { predictionService } from \"../../services/predictionService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command, ExtendedClient } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"fulltime\")\n    .setDescription(\"Conclude a match — freeze log, update standings, post result\")\n    .addStringOption((o) => o.setName(\"match_id\").setDescription(\"Match ID\").setRequired(true))\n    .addIntegerOption((o) => o.setName(\"home_score\").setDescription(\"Home score\").setRequired(true).setMinValue(0))\n    .addIntegerOption((o) => o.setName(\"away_score\").setDescription(\"Away score\").setRequired(true).setMinValue(0))\n    .addUserOption((o) => o.setName(\"motm\").setDescription(\"Man of the Match\").setRequired(false)),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    if (!hasRole(interaction.member as never, RoleType.Founder) && !hasRole(interaction.member as never, RoleType.LeagueManagement) && !hasRole(interaction.member as never, RoleType.Referee)) {\n      await interaction.editReply({ embeds: [createErrorEmbed(\"❌ Permissions\", \"Staff only.\")] }); return;\n    }\n\n    const matchId = interaction.options.getString(\"match_id\", true);\n    const homeScore = interaction.options.getInteger(\"home_score\", true);\n    const awayScore = interaction.options.getInteger(\"away_score\", true);\n    const motmUser = interaction.options.getUser(\"motm\");\n\n    try {\n      const match = await matchService.finishMatch(matchId, { homeScore, awayScore });\n\n      // Record MOTM\n      if (motmUser) {\n        const motmPlayer = await prisma.player.findUnique({ where: { discordId: motmUser.id } });\n        if (motmPlayer) {\n          await prisma.matchMvp.create({ data: { matchId, playerId: motmPlayer.id, reason: \"Man of the Match\" } });\n          await prisma.player.update({ where: { id: motmPlayer.id }, data: { mvps: { increment: 1 } } });\n        }\n      }\n\n      // Resolve predictions\n      await predictionService.resolvePredictions(matchId);\n\n      // Auto-post news\n      const fullMatch = await prisma.match.findUnique({\n        where: { id: match.id },\n        include: {\n          homeTeam: true, awayTeam: true,\n          goals: { include: { player: { include: { user: true } } } },\n          mvps: { include: { player: { include: { user: true } } } },\n        },\n      });\n\n      if (fullMatch && interaction.guild) {\n        const scorers = fullMatch.goals.map((g) => `${g.player.user.username}${g.minute ? ` (${g.minute}')` : \"\"}`);\n        const mvp = fullMatch.mvps[0]?.player.user.username;\n        await newsService.announceMatchResult(interaction.client as ExtendedClient, {\n          guildId: interaction.guild.id,\n          homeTeam: fullMatch.homeTeam.name,\n          awayTeam: fullMatch.awayTeam.name,\n          homeScore: fullMatch.homeScore,\n          awayScore: fullMatch.awayScore,\n          scorers, mvp, matchId: match.id,\n        });\n        for (const g of fullMatch.goals) await newsService.checkMilestones(interaction.client as ExtendedClient, interaction.guild.id, g.playerId);\n        if (fullMatch.mvps[0]) await newsService.checkMilestones(interaction.client as ExtendedClient, interaction.guild.id, fullMatch.mvps[0].playerId);\n      }\n\n      // Archive thread\n      if (fullMatch?.threadId && interaction.channel) {\n        try {\n          const thread = await interaction.channel.client.channels.fetch(fullMatch.threadId);\n          if (thread?.isThread()) await thread.setArchived(true);\n        } catch { /* ok */ }\n      }\n\n      const result = homeScore > awayScore ? \"🏠 Home Win\" : awayScore > homeScore ? \"🚗 Away Win\" : \"🤝 Draw\";\n      const embed = new EmbedBuilder()\n        .setTitle(\"✅ Full-Time!\")\n        .setColor(\"#00AA00\")\n        .setDescription(`**${match.homeTeamId}** ${homeScore} - ${awayScore} **${match.awayTeamId}**\\n\\n📊 **${result}**`)\n        .addFields(\n          { name: \"🏆 MOTM\", value: motmUser ? `<@${motmUser.id}>` : \"Not selected\", inline: true },\n          { name: \"📊 Status\", value: \"✅ Finished\", inline: true },\n        )\n        .setFooter({ text: \"Standings & predictions updated • Legacy Football Championship\" }).setTimestamp();\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Fulltime Error]\", error);\n      await interaction.editReply({ content: \"❌ Failed to conclude match.\" });\n    }\n  },\n};\nexport default command;","src/commands/forfeit/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { matchService } from \"../../services/matchService.js\";\nimport { newsService } from \"../../services/newsService.js\";\nimport { predictionService } from \"../../services/predictionService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command, ExtendedClient } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"forfeit\")\n    .setDescription(\"Log a 3-0 default win if a team fails to show (Management only)\")\n    .addStringOption((o) => o.setName(\"match_id\").setDescription(\"Match ID\").setRequired(true))\n    .addStringOption((o) => o.setName(\"winner\").setDescription(\"Winning team name\").setRequired(true))\n    .addStringOption((o) => o.setName(\"reason\").setDescription(\"Forfeit reason\").setRequired(false)),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    if (!hasRole(interaction.member as never, RoleType.Founder) && !hasRole(interaction.member as never, RoleType.LeagueManagement)) {\n      await interaction.editReply({ embeds: [createErrorEmbed(\"❌ Permissions\", \"Management only.\")] }); return;\n    }\n\n    const matchId = interaction.options.getString(\"match_id\", true);\n    const winnerName = interaction.options.getString(\"winner\", true);\n    const reason = interaction.options.getString(\"reason\") ?? \"Team failed to show\";\n\n    try {\n      const match = await prisma.match.findUnique({\n        where: { id: matchId },\n        include: { homeTeam: true, awayTeam: true },\n      });\n      if (!match) { await interaction.editReply({ content: \"❌ Match not found.\" }); return; }\n\n      const isHomeWin = match.homeTeam.name.toLowerCase() === winnerName.toLowerCase();\n      const homeScore = isHomeWin ? 3 : 0;\n      const awayScore = isHomeWin ? 0 : 3;\n\n      await prisma.match.update({\n        where: { id: matchId },\n        data: { status: \"Forfeit\", homeScore, awayScore, forfeit: true, forfeitingTeam: isHomeWin ? \"away\" : \"home\" },\n      });\n\n      // Update standings as if finished\n      await matchService[\"updateTeamStatsAfterMatch\"]({\n        id: matchId, homeTeamId: match.homeTeamId, awayTeamId: match.awayTeamId,\n        homeScore, awayScore, seasonId: match.seasonId,\n      });\n\n      await predictionService.resolvePredictions(matchId);\n\n      if (interaction.guild) {\n        await newsService.announceMatchResult(interaction.client as ExtendedClient, {\n          guildId: interaction.guild.id,\n          homeTeam: match.homeTeam.name,\n          awayTeam: match.awayTeam.name,\n          homeScore, awayScore,\n          scorers: [\"Default win (forfeit)\"],\n          mvp: undefined,\n          matchId,\n        });\n      }\n\n      const embed = new EmbedBuilder()\n        .setTitle(\"⚖️ Forfeit — Default Win\")\n        .setColor(\"#FF0000\")\n        .setDescription(`**${match.homeTeam.name}** ${homeScore} - ${awayScore} **${match.awayTeam.name}**`)\n        .addFields(\n          { name: \"✅ Winner\", value: isHomeWin ? match.homeTeam.name : match.awayTeam.name, inline: true },\n          { name: \"📝 Reason\", value: reason, inline: false },\n          { name: \"📊 Status\", value: \"⚖️ Forfeit\", inline: true },\n        )\n        .setFooter({ text: \"Legacy Football Championship\" }).setTimestamp();\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Forfeit Error]\", error);\n      await interaction.editReply({ content: \"❌ Failed to process forfeit.\" });\n    }\n  },\n};\nexport default command;","src/commands/lineup/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { teamService } from \"../../services/teamService.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command, Formation } from \"../../types/index.js\";\n\nconst FORMATIONS: { name: string; value: string }[] = [\n  { name: \"4-4-2\", value: \"4-4-2\" },\n  { name: \"4-3-3\", value: \"4-3-3\" },\n  { name: \"3-5-2\", value: \"3-5-2\" },\n  { name: \"4-2-3-1\", value: \"4-2-3-1\" },\n  { name: \"5-3-2\", value: \"5-3-2\" },\n  { name: \"4-1-4-1\", value: \"4-1-4-1\" },\n  { name: \"3-4-3\", value: \"3-4-3\" },\n];\n\nconst POSITIONS: Record<string, string[]> = {\n  \"4-4-2\": [\"GK\", \"LB\", \"CB\", \"CB\", \"RB\", \"LM\", \"CM\", \"CM\", \"RM\", \"ST\", \"ST\"],\n  \"4-3-3\": [\"GK\", \"LB\", \"CB\", \"CB\", \"RB\", \"CM\", \"CDM\", \"CM\", \"LW\", \"ST\", \"RW\"],\n  \"3-5-2\": [\"GK\", \"CB\", \"CB\", \"CB\", \"LM\", \"CM\", \"CDM\", \"CM\", \"RM\", \"ST\", \"ST\"],\n  \"4-2-3-1\": [\"GK\", \"LB\", \"CB\", \"CB\", \"RB\", \"CDM\", \"CDM\", \"LW\", \"CAM\", \"RW\", \"ST\"],\n  \"5-3-2\": [\"GK\", \"LWB\", \"CB\", \"CB\", \"CB\", \"RWB\", \"CM\", \"CM\", \"CM\", \"ST\", \"ST\"],\n  \"4-1-4-1\": [\"GK\", \"LB\", \"CB\", \"CB\", \"RB\", \"CDM\", \"LM\", \"CM\", \"CM\", \"RM\", \"ST\"],\n  \"3-4-3\": [\"GK\", \"CB\", \"CB\", \"CB\", \"LM\", \"CM\", \"CM\", \"RM\", \"LW\", \"ST\", \"RW\"],\n};\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"lineup\")\n    .setDescription(\"Submit a starting lineup for your team (Captains)\")\n    .addStringOption((o) => o.setName(\"match_id\").setDescription(\"Match ID\").setRequired(true))\n    .addStringOption((o) => o.setName(\"formation\").setDescription(\"Formation\").setRequired(true).addChoices(...FORMATIONS))\n    .addStringOption((o) => o.setName(\"starters\").setDescription(\"11 player @mentions comma-separated\").setRequired(true))\n    .addStringOption((o) => o.setName(\"bench\").setDescription(\"Bench players @mentions comma-separated\").setRequired(false)),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const matchId = interaction.options.getString(\"match_id\", true);\n    const formation = interaction.options.getString(\"formation\", true) as Formation;\n    const startersRaw = interaction.options.getString(\"starters\", true);\n    const benchRaw = interaction.options.getString(\"bench\");\n\n    const match = await prisma.match.findUnique({ where: { id: matchId }, include: { homeTeam: true, awayTeam: true } });\n    if (!match) { await interaction.editReply({ content: \"❌ Match not found.\" }); return; }\n\n    // Check user is manager of one of the teams\n    const isHomeManager = match.homeTeam.managerId === interaction.user.id;\n    const isAwayManager = match.awayTeam.managerId === interaction.user.id;\n    if (!isHomeManager && !isAwayManager) {\n      await interaction.editReply({ embeds: [createErrorEmbed(\"❌ Not Your Team\", \"You must be the manager of a team in this match.\")] });\n      return;\n    }\n\n    const teamId = isHomeManager ? match.homeTeamId : match.awayTeamId;\n    const teamName = isHomeManager ? match.homeTeam.name : match.awayTeam.name;\n\n    // Parse starters\n    const starterIds = startersRaw.match(/<@(\\d+)>/g)?.map((m) => m.replace(/<@|>/g, \"\")) ?? [];\n    if (starterIds.length !== 11) {\n      await interaction.editReply({ content: \"❌ You must provide exactly 11 starters.\" });\n      return;\n    }\n\n    // Resolve player IDs\n    const playerMap = await prisma.player.findMany({ where: { discordId: { in: starterIds } }, include: { user: true } });\n    const benchIds = benchRaw ? benchRaw.match(/<@(\\d+)>/g)?.map((m) => m.replace(/<@|>/g, \"\")) ?? [] : [];\n    const benchPlayers = benchIds.length ? await prisma.player.findMany({ where: { discordId: { in: benchIds } } }) : [];\n\n    // Create lineup\n    const lineup = await prisma.lineup.create({\n      data: {\n        matchId, teamId, captainId: interaction.user.id, formation, isConfirmed: true,\n        players: {\n          create: [\n            ...playerMap.map((p, i) => ({\n              playerId: p.id,\n              position: POSITIONS[formation]?.[i] ?? `POS${i + 1}`,\n              isBench: false,\n              order: i,\n              matchId,\n            })),\n            ...benchPlayers.map((p, i) => ({\n              playerId: p.id,\n              position: \"SUB\",\n              isBench: true,\n              order: i + 20,\n              matchId,\n            })),\n          ],\n        },\n      },\n      include: { players: { include: { player: { include: { user: true } } } } },\n    });\n\n    const embed = new EmbedBuilder()\n      .setTitle(`📋 ${teamName} — Lineup Submitted`)\n      .setColor(\"#00AA00\")\n      .addFields(\n        { name: \"🎯 Formation\", value: formation, inline: true },\n        { name: \"👥 Starting XI\", value: lineup.players.filter((p) => !p.isBench).map((p) => `**${p.position}** — ${p.player.user.username}`).join(\"\\n\"), inline: false },\n      );\n    if (lineup.players.some((p) => p.isBench)) {\n      embed.addFields({ name: \"🔄 Bench\", value: lineup.players.filter((p) => p.isBench).map((p) => p.player.user.username).join(\", \"), inline: false });\n    }\n    embed.setFooter({ text: \"Legacy Football Championship • Lineup\" }).setTimestamp();\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\nexport default command;","src/commands/motm/index.ts":"import { SlashCommandBuilder, CommandInteraction, EmbedBuilder, ActionRowBuilder, StringSelectMenuBuilder, ComponentType } from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"motm\")\n    .setDescription(\"Start a Man of the Match poll in the match thread\")\n    .addStringOption((o) => o.setName(\"match_id\").setDescription(\"Match ID\").setRequired(true)),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    if (!hasRole(interaction.member as never, RoleType.Founder) && !hasRole(interaction.member as never, RoleType.LeagueManagement) && !hasRole(interaction.member as never, RoleType.Referee)) {\n      await interaction.editReply({ embeds: [createErrorEmbed(\"❌ Permissions\", \"Staff only.\")] }); return;\n    }\n\n    const matchId = interaction.options.getString(\"match_id\", true);\n    const match = await prisma.match.findUnique({\n      where: { id: matchId },\n      include: {\n        homeTeam: { include: { players: { include: { user: true } } } },\n        awayTeam: { include: { players: { include: { user: true } } } },\n      },\n    });\n    if (!match) { await interaction.editReply({ content: \"❌ Match not found.\" }); return; }\n\n    const allPlayers = [...match.homeTeam.players, ...match.awayTeam.players];\n    if (allPlayers.length === 0) { await interaction.editReply({ content: \"❌ No players in this match.\" }); return; }\n\n    // Create poll\n    const poll = await prisma.motmPoll.create({ data: { matchId } });\n\n    const select = new StringSelectMenuBuilder()\n      .setCustomId(\"motm_vote\").setPlaceholder(\"Vote for Man of the Match...\")\n      .addOptions(\n        allPlayers.map((p) => ({\n          label: p.user.username,\n          value: p.id,\n          description: `${p.position} — ${p.team?.name ?? \"Unknown\"}`,\n          emoji: getPosEmoji(p.position),\n        }))\n      );\n\n    const row = new ActionRowBuilder<StringSelectMenuBuilder>().addComponents(select);\n    const embed = new EmbedBuilder()\n      .setTitle(\"🏆 Man of the Match\")\n      .setColor(\"#FFD700\")\n      .setDescription(`**${match.homeTeam.name}** vs **${match.awayTeam.name}**\\n\\nVote for your MOTM below!`)\n      .setFooter({ text: \"Voting closes in 2 minutes • Legacy Football Championship\" }).setTimestamp();\n\n    const reply = await interaction.editReply({ embeds: [embed], components: [row] });\n\n    const collector = reply.createMessageComponentCollector({ componentType: ComponentType.StringSelect, time: 120_000 });\n    const votes = new Map<string, number>();\n\n    collector.on(\"collect\", async (si) => {\n      const votedPlayerId = si.values[0];\n      // Check if already voted\n      const existing = await prisma.motmVote.findUnique({\n        where: { pollId_voterId: { pollId: poll.id, voterId: si.user.id } },\n      });\n      if (existing) {\n        await si.reply({ content: \"❌ You already voted!\", ephemeral: true });\n        return;\n      }\n      await prisma.motmVote.create({ data: { pollId: poll.id, playerId: votedPlayerId, voterId: si.user.id } });\n      votes.set(votedPlayerId, (votes.get(votedPlayerId) ?? 0) + 1);\n      await si.reply({ content: `✅ Vote counted for **${allPlayers.find((p) => p.id === votedPlayerId)?.user.username}**!`, ephemeral: true });\n    });\n\n    collector.on(\"end\", async () => {\n      // Find winner\n      let winnerId = \"\";\n      let maxVotes = 0;\n      for (const [pid, count] of votes) {\n        if (count > maxVotes) { maxVotes = count; winnerId = pid; }\n      }\n\n      if (winnerId) {\n        const winner = allPlayers.find((p) => p.id === winnerId);\n        await prisma.matchMvp.upsert({\n          where: { matchId },\n          update: { playerId: winnerId, reason: \"Man of the Match (Fan Vote)\" },\n          create: { matchId, playerId: winnerId, reason: \"Man of the Match (Fan Vote)\" },\n        });\n        await prisma.player.update({ where: { id: winnerId }, data: { mvps: { increment: 1 } } });\n\n        await prisma.motmPoll.update({ where: { id: poll.id }, data: { isActive: false } });\n\n        const resultEmbed = new EmbedBuilder()\n          .setTitle(`🏆 Man of the Match: ${winner?.user.username ?? \"Unknown\"}`)\n          .setColor(\"#FFD700\")\n          .setDescription(`**${winner?.user.username}** won with **${maxVotes}** vote${maxVotes > 1 ? \"s\" : \"\"}!`)\n          .setFooter({ text: \"Legacy Football Championship\" }).setTimestamp();\n\n        const disabledRow = ActionRowBuilder.from<StringSelectMenuBuilder>(row);\n        disabledRow.components.forEach((c) => c.setDisabled(true));\n        await interaction.editReply({ embeds: [resultEmbed], components: [disabledRow] });\n      } else {\n        await interaction.editReply({ embeds: [embed.setDescription(\"No votes were cast.\")], components: [] });\n      }\n    });\n  },\n};\n\nfunction getPosEmoji(pos: string): string {\n  const map: Record<string, string> = { Goalkeeper: \"🧤\", Defender: \"🛡️\", Midfielder: \"🎯\", Forward: \"⚽\" };\n  return map[pos] ?? \"👤\";\n}\n\nexport default command;","src/commands/potw/index.ts":"import { SlashCommandBuilder, CommandInteraction, EmbedBuilder } from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { leagueService } from \"../../services/leagueService.js\";\nimport { newsService } from \"../../services/newsService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command, ExtendedClient } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"potw\")\n    .setDescription(\"Award Player of the Week (Management only)\")\n    .addUserOption((o) => o.setName(\"player\").setDescription(\"Player\").setRequired(true))\n    .addIntegerOption((o) => o.setName(\"week\").setDescription(\"Week number\").setRequired(true))\n    .addStringOption((o) => o.setName(\"reason\").setDescription(\"Reason\").setRequired(false)),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n    if (!hasRole(interaction.member as never, RoleType.Founder) && !hasRole(interaction.member as never, RoleType.LeagueManagement)) {\n      await interaction.editReply({ embeds: [createErrorEmbed(\"❌ Permissions\", \"Management only.\")] }); return;\n    }\n    const target = interaction.options.getUser(\"player\", true);\n    const week = interaction.options.getInteger(\"week\", true);\n    const reason = interaction.options.getString(\"reason\");\n    const season = await leagueService.getActiveSeason();\n    if (!season) { await interaction.editReply({ content: \"❌ No active season.\" }); return; }\n    const player = await prisma.player.findUnique({ where: { discordId: target.id }, include: { user: true, team: true } });\n    if (!player) { await interaction.editReply({ content: \"❌ Player not registered.\" }); return; }\n\n    const award = await prisma.weeklyAward.create({\n      data: { type: \"potw\", playerId: player.id, seasonId: season.id, weekNumber: week, reason },\n    });\n\n    if (interaction.guild) {\n      await newsService.announceAward(interaction.client as ExtendedClient, {\n        guildId: interaction.guild.id,\n        playerName: target.username,\n        awardType: `Player of the Week (GW${week})`,\n        season: season.name,\n        reason: reason ?? undefined,\n      });\n    }\n\n    const embed = new EmbedBuilder()\n      .setTitle(\"🌟 Player of the Week!\")\n      .setColor(\"#00AAFF\")\n      .setDescription(`**${target.username}** is the Player of the Week for **GW${week}**!`)\n      .addFields(\n        { name: \"👤 Player\", value: `<@${target.id}>`, inline: true },\n        { name: \"🏠 Club\", value: player.team?.name ?? \"Free Agent\", inline: true },\n        { name: \"⚽ Position\", value: player.position, inline: true },\n        { name: \"📝 Reason\", value: reason ?? \"Outstanding performance\", inline: false },\n      )\n      .setFooter({ text: `Week ${week} • Legacy Football Championship` }).setTimestamp();\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\nexport default command;","src/commands/totw/index.ts":"import { SlashCommandBuilder, CommandInteraction, EmbedBuilder } from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { leagueService } from \"../../services/leagueService.js\";\nimport { newsService } from \"../../services/newsService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command, ExtendedClient } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"totw\")\n    .setDescription(\"Award Team of the Week (Management only)\")\n    .addStringOption((o) => o.setName(\"team\").setDescription(\"Team name\").setRequired(true))\n    .addIntegerOption((o) => o.setName(\"week\").setDescription(\"Week number\").setRequired(true))\n    .addStringOption((o) => o.setName(\"reason\").setDescription(\"Reason\").setRequired(false)),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n    if (!hasRole(interaction.member as never, RoleType.Founder) && !hasRole(interaction.member as never, RoleType.LeagueManagement)) {\n      await interaction.editReply({ embeds: [createErrorEmbed(\"❌ Permissions\", \"Management only.\")] }); return;\n    }\n    const teamName = interaction.options.getString(\"team\", true);\n    const week = interaction.options.getInteger(\"week\", true);\n    const reason = interaction.options.getString(\"reason\");\n    const season = await leagueService.getActiveSeason();\n    if (!season) { await interaction.editReply({ content: \"❌ No active season.\" }); return; }\n    const team = await prisma.team.findUnique({ where: { name: teamName }, include: { manager: true } });\n    if (!team) { await interaction.editReply({ content: \"❌ Team not found.\" }); return; }\n\n    await prisma.weeklyAward.create({\n      data: { type: \"totw\", teamId: team.id, seasonId: season.id, weekNumber: week, reason },\n    });\n\n    if (interaction.guild) {\n      await newsService.announceBroadcast(interaction.client as ExtendedClient, {\n        guildId: interaction.guild.id,\n        title: `🏅 Team of the Week (GW${week})`,\n        message: `**${team.name}** has been awarded **Team of the Week** for GW${week}!${reason ? `\\n\\n📝 ${reason}` : \"\"}`,\n        authorName: interaction.user.username,\n        color: \"#FFD700\",\n      });\n    }\n\n    const embed = new EmbedBuilder()\n      .setTitle(\"🏅 Team of the Week!\")\n      .setColor(\"#FFD700\")\n      .setDescription(`**${team.name}** is the Team of the Week for **GW${week}**!`)\n      .addFields(\n        { name: \"🏟️ Team\", value: team.name, inline: true },\n        { name: \"👤 Manager\", value: `<@${team.manager.discordId}>`, inline: true },\n        { name: \"📝 Reason\", value: reason ?? \"Outstanding team performance\", inline: false },\n      )\n      .setFooter({ text: `Week ${week} • Legacy Football Championship` }).setTimestamp();\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\nexport default command;","src/commands/dispute/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n  ChannelType,\n} from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"dispute\")\n    .setDescription(\"Open a dispute ticket for admin review of a match incident\")\n    .addStringOption((o) => o.setName(\"match_id\").setDescription(\"Match ID\").setRequired(true))\n    .addStringOption((o) => o.setName(\"reason\").setDescription(\"What are you disputing?\").setRequired(true))\n    .addStringOption((o) => o.setName(\"evidence\").setDescription(\"Link to clip/screenshot evidence\").setRequired(false)),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply({ ephemeral: true });\n\n    const matchId = interaction.options.getString(\"match_id\", true);\n    const reason = interaction.options.getString(\"reason\", true);\n    const evidence = interaction.options.getString(\"evidence\");\n\n    const match = await prisma.match.findUnique({\n      where: { id: matchId },\n      include: { homeTeam: true, awayTeam: true },\n    });\n    if (!match) {\n      await interaction.editReply({ content: \"❌ Match not found.\" });\n      return;\n    }\n\n    // Create dispute in DB\n    const dispute = await prisma.dispute.create({\n      data: {\n        matchId,\n        reporterId: interaction.user.id,\n        reason,\n        evidenceUrl: evidence ?? null,\n        status: \"Open\",\n      },\n    });\n\n    // Try to create a private thread\n    let threadInfo = \"\";\n    if (interaction.channel && interaction.channel.type === ChannelType.GuildText) {\n      try {\n        const thread = await interaction.channel.threads.create({\n          name: `🚩 Dispute: ${match.homeTeam.name} vs ${match.awayTeam.name}`,\n          reason: `Dispute ticket #${dispute.id.slice(0, 6)}`,\n          type: ChannelType.PrivateThread,\n        });\n        await thread.send({\n          content: `🚩 **New Dispute Opened**\\n👤 **Reporter:** <@${interaction.user.id}>\\n⚽ **Match:** ${match.homeTeam.name} vs ${match.awayTeam.name}\\n📝 **Reason:** ${reason}${evidence ? `\\n🔗 **Evidence:** ${evidence}` : \"\"}\\n\\n🛠️ **Admins:** Please review and use \\`/resolve\\` when done.`,\n        });\n        await prisma.dispute.update({\n          where: { id: dispute.id },\n          data: { ticketChannelId: thread.id },\n        });\n        threadInfo = `📝 Ticket created: ${thread}`;\n      } catch {\n        threadInfo = \"⚠️ Could not create ticket thread.\";\n      }\n    }\n\n    const embed = new EmbedBuilder()\n      .setTitle(\"🚩 Dispute Filed\")\n      .setColor(\"#FF6600\")\n      .setDescription(`Your dispute for **${match.homeTeam.name} vs ${match.awayTeam.name}** has been submitted.`)\n      .addFields(\n        { name: \"📝 Reason\", value: reason, inline: false },\n        { name: \"🔢 Dispute ID\", value: dispute.id.slice(0, 8), inline: true },\n        { name: \"📋 Status\", value: \"🟡 Under Review\", inline: true },\n      );\n    if (threadInfo) embed.addFields({ name: \"📎 Thread\", value: threadInfo, inline: false });\n\n    embed.setFooter({ text: \"Legacy Football Championship • Disputes\" }).setTimestamp();\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\nexport default command;","src/commands/predict/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { predictionService } from \"../../services/predictionService.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"predict\")\n    .setDescription(\"Predict the outcome of an upcoming match\")\n    .addStringOption((o) => o.setName(\"match_id\").setDescription(\"Match ID\").setRequired(true))\n    .addStringOption((o) => o.setName(\"winner\").setDescription(\"Who wins?\").setRequired(true)\n      .addChoices(\n        { name: \"🏠 Home Team\", value: \"home\" },\n        { name: \"🚗 Away Team\", value: \"away\" },\n        { name: \"🤝 Draw\", value: \"draw\" },\n      )),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply({ ephemeral: true });\n\n    const matchId = interaction.options.getString(\"match_id\", true);\n    const winner = interaction.options.getString(\"winner\", true);\n\n    const match = await prisma.match.findUnique({\n      where: { id: matchId },\n      include: { homeTeam: true, awayTeam: true },\n    });\n    if (!match) { await interaction.editReply({ content: \"❌ Match not found.\" }); return; }\n    if (match.status !== \"Scheduled\") { await interaction.editReply({ content: \"❌ This match has already started or finished.\" }); return; }\n\n    let predictedTeamId: string | undefined;\n    let draw = false;\n\n    if (winner === \"home\") predictedTeamId = match.homeTeamId;\n    else if (winner === \"away\") predictedTeamId = match.awayTeamId;\n    else draw = true;\n\n    await predictionService.predict({\n      matchId,\n      userId: interaction.user.id,\n      teamId: predictedTeamId,\n      draw,\n    });\n\n    const prediction = draw ? \"🤝 Draw\" : `${winner === \"home\" ? match.homeTeam.name : match.awayTeam.name} wins`;\n\n    const embed = new EmbedBuilder()\n      .setTitle(\"🔮 Prediction Submitted\")\n      .setColor(\"#FF6600\")\n      .setDescription(`You predicted: **${prediction}**`)\n      .addFields(\n        { name: \"⚽ Match\", value: `${match.homeTeam.name} vs ${match.awayTeam.name}`, inline: false },\n        { name: \"🎯 Your Pick\", value: prediction, inline: true },\n        { name: \"💰 Reward\", value: \"**3 pts** for correct prediction\", inline: true },\n      )\n      .setFooter({ text: \"Legacy Football Championship • Predictions\" }).setTimestamp();\n\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\nexport default command;","src/commands/dashboard/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n  ActionRowBuilder,\n  ButtonBuilder,\n  ButtonStyle,\n  ComponentType,\n} from \"discord.js\";\nimport { playerService } from \"../../services/playerService.js\";\nimport { contractService } from \"../../services/contractService.js\";\nimport { matchService } from \"../../services/matchService.js\";\nimport { predictionService } from \"../../services/predictionService.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"dashboard\")\n    .setDescription(\"Your personal LFC control panel\"),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n    await showDashboard(interaction, \"overview\");\n  },\n};\n\nasync function showDashboard(interaction: CommandInteraction, tab: string) {\n  const userId = interaction.user.id;\n  const player = await playerService.getPlayer(userId);\n\n  if (!player) {\n    await interaction.editReply({ content: \"❌ You're not registered as an LFC player yet. Get offered a contract first!\" });\n    return;\n  }\n\n  let embed: EmbedBuilder;\n\n  switch (tab) {\n    case \"contract\": {\n      const contract = await contractService.getActiveContract(player.id);\n      embed = new EmbedBuilder()\n        .setTitle(\"📝 My Contract\")\n        .setColor(\"#00AA00\")\n        .setDescription(contract\n          ? `**Club:** ${contract.team.name}\\n**Role:** ${contract.roleInTeam ?? \"Starter\"}\\n**Signed:** <t:${Math.floor(contract.signedAt.getTime() / 1000)}:R>`\n          : \"No active contract. You're a free agent.\")\n        .setFooter({ text: \"Legacy Football Championship\" }).setTimestamp();\n      break;\n    }\n    case \"stats\": {\n      const activeStat = player.seasonStats.find((s) => s.season.isActive);\n      embed = new EmbedBuilder()\n        .setTitle(\"📊 My Stats\")\n        .setColor(\"#00AA00\")\n        .addFields(\n          { name: \"📈 This Season\", value: activeStat\n            ? `⚽ ${activeStat.goals}G | 🎯 ${activeStat.assists}A | 🧤 ${activeStat.saves}S | 🏆 ${activeStat.mvps}MVP\\n📋 ${activeStat.appearances}Apps | 🧹 ${activeStat.cleanSheets}CS`\n            : \"No active season.\", inline: false },\n          { name: \"🏆 Career\", value: `⚽ ${player.goals}G | 🎯 ${player.assists}A | 🧤 ${player.saves}S | 🏆 ${player.mvps}MVP\\n📋 ${player.appearances}Apps | 🏅 ${player.trophies}Trophies`, inline: false },\n        )\n        .setFooter({ text: \"Legacy Football Championship\" }).setTimestamp();\n      break;\n    }\n    case \"predictions\": {\n      const predStats = await predictionService.getUserStats(userId);\n      embed = new EmbedBuilder()\n        .setTitle(\"🔮 My Predictions\")\n        .setColor(\"#FF6600\")\n        .addFields(\n          { name: \"📊 Record\", value: `✅ ${predStats.correct} correct | ❌ ${predStats.total - predStats.correct} wrong | 📊 ${predStats.accuracy}% accuracy`, inline: false },\n          { name: \"📋 Recent Picks\", value: predStats.predictions.slice(0, 5).map((p) =>\n            `${p.match.homeTeam.name} vs ${p.match.awayTeam.name}: ${p.predictedDraw ? \"🤝 Draw\" : p.predictedTeamId === p.match.homeTeamId ? `🏠 ${p.match.homeTeam.name}` : `🚗 ${p.match.awayTeam.name}`}${p.resolved ? p.points > 0 ? \" ✅\" : \" ❌\" : \" ⏳\"}`\n          ).join(\"\\n\") || \"No predictions yet.\", inline: false },\n        )\n        .setFooter({ text: \"Legacy Football Championship\" }).setTimestamp();\n      break;\n    }\n    default: {\n      const contract = await contractService.getActiveContract(player.id);\n      const upcomingMatches = contract\n        ? await prisma.match.findMany({\n            where: {\n              OR: [{ homeTeamId: contract.teamId }, { awayTeamId: contract.teamId }],\n              status: \"Scheduled\",\n            },\n            include: { homeTeam: true, awayTeam: true },\n            take: 3,\n          })\n        : [];\n\n      embed = new EmbedBuilder()\n        .setTitle(`👋 Welcome, ${interaction.user.username}`)\n        .setThumbnail(interaction.user.displayAvatarURL())\n        .setColor(\"#00AA00\")\n        .setDescription(`**LFC ID:** ${player.lfcId}\\n**Club:** ${player.team?.name ?? \"🆓 Free Agent\"}\\n**Position:** ${player.position} | **Region:** ${player.region}`)\n        .addFields(\n          { name: \"⚽ Season Stats\", value: `⚽${player.goals}G 🎯${player.assists}A 🏆${player.mvps}MVP`, inline: true },\n          { name: \"🏆 Trophies\", value: `${player.trophies}`, inline: true },\n          { name: \"📋 Appearances\", value: `${player.appearances}`, inline: true },\n        );\n\n      if (upcomingMatches.length) {\n        embed.addFields({\n          name: \"📅 Upcoming Fixtures\",\n          value: upcomingMatches.map((m) => `• ${m.homeTeam.name} vs ${m.awayTeam.name}`).join(\"\\n\"),\n          inline: false,\n        });\n      }\n    }\n  }\n\n  const row = new ActionRowBuilder<ButtonBuilder>().addComponents(\n    new ButtonBuilder().setCustomId(\"dash_overview\").setLabel(\"🏠 Home\").setStyle(tab === \"overview\" ? ButtonStyle.Primary : ButtonStyle.Secondary),\n    new ButtonBuilder().setCustomId(\"dash_stats\").setLabel(\"📊 Stats\").setStyle(tab === \"stats\" ? ButtonStyle.Primary : ButtonStyle.Secondary),\n    new ButtonBuilder().setCustomId(\"dash_contract\").setLabel(\"📝 Contract\").setStyle(tab === \"contract\" ? ButtonStyle.Primary : ButtonStyle.Secondary),\n    new ButtonBuilder().setCustomId(\"dash_predictions\").setLabel(\"🔮 Predictions\").setStyle(tab === \"predictions\" ? ButtonStyle.Primary : ButtonStyle.Secondary),\n  );\n\n  const reply = await interaction.editReply({ embeds: [embed], components: [row] });\n\n  const collector = reply.createMessageComponentCollector({ componentType: ComponentType.Button, time: 120_000 });\n  collector.on(\"collect\", async (bi) => {\n    if (bi.user.id !== interaction.user.id) { await bi.reply({ content: \"❌ Not your dashboard.\", ephemeral: true }); return; }\n    await bi.deferUpdate();\n    const newTab = bi.customId.replace(\"dash_\", \"\");\n    await showDashboard(bi as unknown as CommandInteraction, newTab);\n  });\n  collector.on(\"end\", async () => {\n    const dr = ActionRowBuilder.from<ButtonBuilder>(row);\n    dr.components.forEach((c) => c.setDisabled(true));\n    await interaction.editReply({ components: [dr] }).catch(() => {});\n  });\n}\n\nexport default command;","src/commands/card/index.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  AttachmentBuilder,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\nimport { createCanvas, loadImage, registerFont } from \"canvas\";\nimport { join, dirname } from \"path\";\nimport { fileURLToPath } from \"url\";\n\nconst __filename = fileURLToPath(import.meta.url);\nconst __dirname = dirname(__filename);\n\nconst POSITION_COLORS: Record<string, string> = {\n  Goalkeeper: \"#FFD700\",\n  Defender: \"#00AAFF\",\n  Midfielder: \"#00CC66\",\n  Forward: \"#FF4444\",\n};\n\nconst RARITY_COLORS: Record<string, string> = {\n  Common: \"#888888\",\n  Rare: \"#22AAFF\",\n  \"Epic\": \"#AA44FF\",\n  Legendary: \"#FFAA00\",\n};\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"card\")\n    .setDescription(\"Generate an EA FC style player card\")\n    .addUserOption((o) => o.setName(\"player\").setDescription(\"Player\").setRequired(true)),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const target = interaction.options.getUser(\"player\", true);\n    const player = await prisma.player.findUnique({\n      where: { discordId: target.id },\n      include: { user: true, team: true },\n    });\n    if (!player) {\n      await interaction.editReply({ content: \"❌ Player not registered.\" });\n      return;\n    }\n\n    try {\n      const width = 400;\n      const height = 560;\n      const canvas = createCanvas(width, height);\n      const ctx = canvas.getContext(\"2d\");\n\n      // Background gradient\n      const bgColor = POSITION_COLORS[player.position] ?? \"#00AA00\";\n      const grad = ctx.createLinearGradient(0, 0, width, height);\n      grad.addColorStop(0, bgColor);\n      grad.addColorStop(0.4, \"#1a1a2e\");\n      grad.addColorStop(1, \"#0f0f1a\");\n      ctx.fillStyle = grad;\n      ctx.fillRect(0, 0, width, height);\n\n      // Card border\n      ctx.strokeStyle = bgColor;\n      ctx.lineWidth = 3;\n      ctx.strokeRect(5, 5, width - 10, height - 10);\n\n      // Top accent bar\n      ctx.fillStyle = bgColor;\n      ctx.fillRect(10, 10, width - 20, 4);\n\n      // Rating circle\n      const rating = Math.min(99, Math.max(60, player.goals * 3 + player.appearances + 60));\n      ctx.beginPath();\n      ctx.arc(80, 100, 40, 0, Math.PI * 2);\n      ctx.fillStyle = \"rgba(0,0,0,0.5)\";\n      ctx.fill();\n      ctx.strokeStyle = bgColor;\n      ctx.lineWidth = 3;\n      ctx.stroke();\n\n      ctx.fillStyle = \"#FFFFFF\";\n      ctx.font = \"bold 36px Arial\";\n      ctx.textAlign = \"center\";\n      ctx.fillText(`${rating}`, 80, 112);\n\n      // Position label\n      ctx.font = \"bold 18px Arial\";\n      ctx.fillStyle = bgColor;\n      ctx.textAlign = \"left\";\n      const posAbbr: Record<string, string> = {\n        Goalkeeper: \"GK\", Defender: \"DEF\", Midfielder: \"MID\", Forward: \"FWD\",\n      };\n      ctx.fillText(posAbbr[player.position] ?? \"LFC\", 140, 85);\n\n      // Player name\n      ctx.fillStyle = \"#FFFFFF\";\n      ctx.font = \"bold 24px Arial\";\n      ctx.fillText(target.username.length > 14 ? target.username.slice(0, 14) + \"...\" : target.username, 140, 115);\n\n      // Stats\n      const stats = [\n        { label: \"GOALS\", value: player.goals, max: 50 },\n        { label: \"ASSISTS\", value: player.assists, max: 50 },\n        { label: \"APPS\", value: player.appearances, max: 100 },\n        { label: \"MVP\", value: player.mvps, max: 20 },\n      ];\n\n      ctx.textAlign = \"left\";\n      stats.forEach((stat, i) => {\n        const y = 160 + i * 55;\n        ctx.fillStyle = \"#AAAAAA\";\n        ctx.font = \"12px Arial\";\n        ctx.fillText(stat.label, 30, y);\n\n        ctx.fillStyle = \"#FFFFFF\";\n        ctx.font = \"bold 28px Arial\";\n        ctx.fillText(`${stat.value}`, 30, y + 25);\n\n        // Stat bar background\n        ctx.fillStyle = \"rgba(255,255,255,0.1)\";\n        ctx.fillRect(120, y + 10, 220, 8);\n        // Stat bar fill\n        const pct = Math.min(1, stat.value / stat.max);\n        const barGrad = ctx.createLinearGradient(120, 0, 340, 0);\n        barGrad.addColorStop(0, bgColor);\n        barGrad.addColorStop(1, \"#FFFFFF\");\n        ctx.fillStyle = barGrad;\n        ctx.fillRect(120, y + 10, 220 * pct, 8);\n      });\n\n      // Club badge area\n      if (player.team) {\n        ctx.fillStyle = \"rgba(255,255,255,0.1)\";\n        ctx.fillRect(30, 400, width - 60, 50);\n        ctx.fillStyle = bgColor;\n        ctx.font = \"bold 16px Arial\";\n        ctx.textAlign = \"center\";\n        ctx.fillText(player.team.name, width / 2, 430);\n      }\n\n      // LFC ID & footer\n      ctx.fillStyle = \"rgba(255,255,255,0.4)\";\n      ctx.font = \"11px Arial\";\n      ctx.textAlign = \"center\";\n      ctx.fillText(`LFC ID: ${player.lfcId}`, width / 2, 480);\n\n      ctx.fillStyle = \"rgba(255,255,255,0.2)\";\n      ctx.font = \"10px Arial\";\n      ctx.fillText(\"LEGACY FOOTBALL CHAMPIONSHIP\", width / 2, height - 30);\n\n      // Bottom accent bar\n      ctx.fillStyle = bgColor;\n      ctx.fillRect(10, height - 14, width - 20, 4);\n\n      // Convert to buffer\n      const buffer = canvas.toBuffer(\"image/png\");\n      const attachment = new AttachmentBuilder(buffer, { name: `${target.username}-card.png` });\n\n      await interaction.editReply({\n        content: `🏆 **${target.username}** — EA FC Style Card`,\n        files: [attachment],\n      });\n    } catch (error) {\n      console.error(\"[Card Error]\", error);\n      await interaction.editReply({\n        embeds: [createErrorEmbed(\"❌ Card Generation Failed\", \"Could not generate player card.\")],\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/admin/setup.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n  PermissionFlagsBits,\n} from \"discord.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed, createSuccessEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"setup\")\n    .setDescription(\"Set up the LFC bot in this server (Founder only)\")\n    .setDefaultMemberPermissions(PermissionFlagsBits.Administrator),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    if (!hasRole(interaction.member as never, RoleType.Founder)) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"Only the **Founder** can run setup.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const guild = interaction.guild;\n    if (!guild) {\n      await interaction.editReply({\n        embeds: [createErrorEmbed(\"❌ Error\", \"This command must be used in a server.\")],\n      });\n      return;\n    }\n\n    const embed = new EmbedBuilder()\n      .setTitle(\"✅ LFC Bot Setup Complete\")\n      .setColor(\"#00AA00\")\n      .setDescription(\n        \"Legacy Football Championship bot has been configured for this server!\"\n      )\n      .addFields(\n        {\n          name: \"📋 Required Roles\",\n          value: [\n            \"Make sure these roles exist in your server:\",\n            \"• **Founder** — Top-level admin access\",\n            \"• **League Management** — League operations\",\n            \"• **Moderator** — General moderation\",\n            \"• **Referee** — Match officiating\",\n          ].join(\"\\n\"),\n          inline: false,\n        },\n        {\n          name: \"⚙️ Getting Started\",\n          value: [\n            \"1. `/season start` — Begin a new season\",\n            \"2. `/team create` — Register teams\",\n            \"3. `/match create` — Schedule matches\",\n            \"4. `/match start` — Begin a match\",\n            \"5. `/match report` — Record events\",\n            \"6. `/match finish` — End the match\",\n          ].join(\"\\n\"),\n          inline: false,\n        },\n        {\n          name: \"📖 Need Help?\",\n          value: \"Use `/` to browse all available commands.\",\n          inline: false,\n        }\n      )\n      .setFooter({ text: \"Legacy Football Championship\" })\n      .setTimestamp();\n\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\n\nexport default command;","src/commands/admin/warn.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { adminService } from \"../../services/adminService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed, formatDate } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"warn\")\n    .setDescription(\"Warn a user for misconduct (Staff only)\")\n    .addUserOption((opt) =>\n      opt\n        .setName(\"user\")\n        .setDescription(\"User to warn\")\n        .setRequired(true)\n    )\n    .addStringOption((opt) =>\n      opt\n        .setName(\"reason\")\n        .setDescription(\"Reason for the warning\")\n        .setRequired(true)\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply({ ephemeral: true });\n\n    const member = interaction.member;\n    if (\n      !hasRole(member as never, RoleType.Founder) &&\n      !hasRole(member as never, RoleType.LeagueManagement) &&\n      !hasRole(member as never, RoleType.Moderator)\n    ) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"You need **Founder**, **League Management**, or **Moderator** role.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const targetUser = interaction.options.getUser(\"user\", true);\n    const reason = interaction.options.getString(\"reason\", true);\n\n    try {\n      await adminService.warnUser(targetUser.id, reason, interaction.user.id);\n\n      const embed = new EmbedBuilder()\n        .setTitle(\"⚠️ Warning Issued\")\n        .setColor(\"#FFAA00\")\n        .addFields(\n          { name: \"👤 User\", value: `<@${targetUser.id}>`, inline: true },\n          { name: \"📝 Reason\", value: reason, inline: false },\n          { name: \"👮‍♂️ Issued By\", value: `<@${interaction.user.id}>`, inline: true }\n        )\n        .setFooter({ text: \"Legacy Football Championship\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n\n      // Try to DM the warned user\n      try {\n        const dmEmbed = new EmbedBuilder()\n          .setTitle(\"⚠️ You have received a warning\")\n          .setColor(\"#FFAA00\")\n          .addFields(\n            { name: \"Server\", value: interaction.guild?.name ?? \"LFC\", inline: true },\n            { name: \"Reason\", value: reason, inline: false }\n          )\n          .setFooter({ text: \"Legacy Football Championship\" })\n          .setTimestamp();\n\n        await targetUser.send({ embeds: [dmEmbed] });\n      } catch {\n        // User may have DMs disabled, that's fine\n      }\n    } catch (error) {\n      console.error(\"[Warn Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while issuing the warning.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/admin/suspend.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { adminService } from \"../../services/adminService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"suspend\")\n    .setDescription(\"Suspend a user from the league (Management only)\")\n    .addUserOption((opt) =>\n      opt\n        .setName(\"user\")\n        .setDescription(\"User to suspend\")\n        .setRequired(true)\n    )\n    .addStringOption((opt) =>\n      opt\n        .setName(\"reason\")\n        .setDescription(\"Reason for the suspension\")\n        .setRequired(true)\n    )\n    .addStringOption((opt) =>\n      opt\n        .setName(\"duration\")\n        .setDescription(\"Suspension duration (e.g. 7d, 30d, permanent)\")\n        .setRequired(false)\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply({ ephemeral: true });\n\n    const member = interaction.member;\n    if (\n      !hasRole(member as never, RoleType.Founder) &&\n      !hasRole(member as never, RoleType.LeagueManagement)\n    ) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"You need **Founder** or **League Management** role.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const targetUser = interaction.options.getUser(\"user\", true);\n    const reason = interaction.options.getString(\"reason\", true);\n    const duration = interaction.options.getString(\"duration\");\n\n    try {\n      // Parse duration\n      let expiresAt: Date | undefined;\n      if (duration && duration !== \"permanent\") {\n        const match = duration.match(/^(\\d+)(d|h|m)$/);\n        if (match) {\n          const amount = parseInt(match[1]);\n          const unit = match[2];\n          const now = new Date();\n          switch (unit) {\n            case \"m\":\n              expiresAt = new Date(now.getTime() + amount * 60000);\n              break;\n            case \"h\":\n              expiresAt = new Date(now.getTime() + amount * 3600000);\n              break;\n            case \"d\":\n              expiresAt = new Date(now.getTime() + amount * 86400000);\n              break;\n          }\n        }\n      }\n\n      await adminService.suspendUser(\n        targetUser.id,\n        reason,\n        interaction.user.id,\n        expiresAt\n      );\n\n      const embed = new EmbedBuilder()\n        .setTitle(\"🔒 User Suspended\")\n        .setColor(\"#FF0000\")\n        .addFields(\n          { name: \"👤 User\", value: `<@${targetUser.id}>`, inline: true },\n          { name: \"📝 Reason\", value: reason, inline: false },\n          {\n            name: \"⏱ Duration\",\n            value: expiresAt ? `Until ${expiresAt.toLocaleDateString()}` : \"Permanent\",\n            inline: true,\n          },\n          {\n            name: \"👮‍♂️ Issued By\",\n            value: `<@${interaction.user.id}>`,\n            inline: true,\n          }\n        )\n        .setFooter({ text: \"Use /suspend again to extend | Legacy Football Championship\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Suspend Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while suspending the user.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/admin/blacklist.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { adminService } from \"../../services/adminService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"blacklist\")\n    .setDescription(\"Blacklist a user from the league (Founder only)\")\n    .addUserOption((opt) =>\n      opt\n        .setName(\"user\")\n        .setDescription(\"User to blacklist\")\n        .setRequired(true)\n    )\n    .addStringOption((opt) =>\n      opt\n        .setName(\"reason\")\n        .setDescription(\"Reason for blacklisting\")\n        .setRequired(true)\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply({ ephemeral: true });\n\n    if (!hasRole(interaction.member as never, RoleType.Founder)) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"Only the **Founder** can blacklist users.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const targetUser = interaction.options.getUser(\"user\", true);\n    const reason = interaction.options.getString(\"reason\", true);\n\n    try {\n      const isBlacklisted = await adminService.isBlacklisted(targetUser.id);\n      if (isBlacklisted) {\n        await interaction.editReply({\n          embeds: [\n            createErrorEmbed(\n              \"❌ Already Blacklisted\",\n              `${targetUser.username} is already blacklisted.`\n            ),\n          ],\n        });\n        return;\n      }\n\n      await adminService.blacklistUser(targetUser.id, reason, interaction.user.id);\n\n      const embed = new EmbedBuilder()\n        .setTitle(\"🚫 User Blacklisted\")\n        .setColor(\"#000000\")\n        .addFields(\n          { name: \"👤 User\", value: `<@${targetUser.id}>`, inline: true },\n          { name: \"📝 Reason\", value: reason, inline: false },\n          { name: \"👮‍♂️ Issued By\", value: `<@${interaction.user.id}>`, inline: true }\n        )\n        .setFooter({ text: \"This action is irreversible | Legacy Football Championship\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Blacklist Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while blacklisting the user.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/admin/season.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { leagueService } from \"../../services/leagueService.js\";\nimport { newsService } from \"../../services/newsService.js\";\nimport { teamService } from \"../../services/teamService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command, ExtendedClient } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"season\")\n    .setDescription(\"Season management commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"start\")\n        .setDescription(\"Start a new season (Management only)\")\n        .addStringOption((opt) =>\n          opt\n            .setName(\"name\")\n            .setDescription(\"Season name (e.g. Season 3)\")\n            .setRequired(true)\n        )\n    )\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"end\")\n        .setDescription(\"End the current active season (Management only)\")\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const member = interaction.member;\n    if (\n      !hasRole(member as never, RoleType.Founder) &&\n      !hasRole(member as never, RoleType.LeagueManagement)\n    ) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"You need **Founder** or **League Management** role.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const subcommand = interaction.options.getSubcommand();\n    const client = interaction.client as ExtendedClient;\n\n    try {\n      if (subcommand === \"start\") {\n        await handleSeasonStart(interaction, client);\n      } else if (subcommand === \"end\") {\n        await handleSeasonEnd(interaction, client);\n      }\n    } catch (error) {\n      console.error(\"[Season Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred managing the season.\",\n      });\n    }\n  },\n};\n\nasync function handleSeasonStart(interaction: CommandInteraction, client: ExtendedClient) {\n  const name = interaction.options.getString(\"name\", true);\n\n  // Check for existing active season\n  const active = await leagueService.getActiveSeason();\n  if (active) {\n    await interaction.editReply({\n      embeds: [\n        createErrorEmbed(\n          \"❌ Season Already Active\",\n          `**${active.name}** is already active. End it first with \\`/season end\\`.`\n        ),\n      ],\n    });\n    return;\n  }\n\n  const season = await leagueService.createSeason(name);\n  await leagueService.initializeSeasonStats(season.id);\n  await leagueService.initializePlayerSeasonStats(season.id);\n\n  // ── Auto-post season start news ──\n  try {\n    if (interaction.guild) {\n      const teams = await teamService.listTeams();\n      await newsService.announceSeasonStart(client, {\n        guildId: interaction.guild.id,\n        seasonName: season.name,\n        teamCount: teams.length,\n      });\n    }\n  } catch (newsError) {\n    console.error(\"[Season News Error]\", newsError);\n  }\n\n  const embed = new EmbedBuilder()\n    .setTitle(\"📅 New Season Started!\")\n    .setColor(\"#00AA00\")\n    .setDescription(`**${season.name}** is now active!`)\n    .addFields(\n      { name: \"📋 Season\", value: season.name, inline: true },\n      { name: \"🎯 Status\", value: \"🟢 Active\", inline: true },\n      {\n        name: \"✅ What's Next?\",\n        value: [\n          \"1. Make sure all teams are registered with `/team create`\",\n          \"2. Schedule matches with `/match create`\",\n          \"3. Use `/standings` to track the league table\",\n        ].join(\"\\n\"),\n        inline: false,\n      }\n    )\n    .setFooter({ text: \"Legacy Football Championship\" })\n    .setTimestamp();\n\n  await interaction.editReply({ embeds: [embed] });\n}\n\nasync function handleSeasonEnd(interaction: CommandInteraction, client: ExtendedClient) {\n  const active = await leagueService.getActiveSeason();\n  if (!active) {\n    await interaction.editReply({\n      embeds: [createErrorEmbed(\"❌ No Active Season\", \"There is no active season to end.\")],\n    });\n    return;\n  }\n\n  // Get final standings\n  const standings = await leagueService.getStandings(active.id);\n  const champion = standings[0];\n\n  const ended = await leagueService.endActiveSeason();\n\n  // ── Auto-post season end news ──\n  try {\n    if (interaction.guild) {\n      await newsService.announceSeasonEnd(client, {\n        guildId: interaction.guild.id,\n        seasonName: active.name,\n        championName: champion?.teamName,\n        championPoints: champion?.points,\n      });\n    }\n  } catch (newsError) {\n    console.error(\"[Season News Error]\", newsError);\n  }\n\n  const embed = new EmbedBuilder()\n    .setTitle(\"🏆 Season Ended!\")\n    .setColor(\"#FFD700\")\n    .setDescription(`**${active.name}** has come to a close!`);\n\n  if (champion) {\n    embed.addFields({\n      name: \"👑 Champions\",\n      value: `**${champion.teamName}** — ${champion.points}pts (${champion.wins}W / ${champion.draws}D / ${champion.losses}L)`,\n      inline: false,\n    });\n  }\n\n  embed\n    .addFields(\n      { name: \"📋 Season\", value: active.name, inline: true },\n      { name: \"✅ Status\", value: \"🔴 Ended\", inline: true },\n      {\n        name: \"🎯 Next Steps\",\n        value: \"Use `/award give` to distribute season awards, then `/season start` to begin a new season.\",\n        inline: false,\n      }\n    )\n    .setFooter({ text: \"Legacy Football Championship\" })\n    .setTimestamp();\n\n  await interaction.editReply({ embeds: [embed] });\n}\n\nexport default command;","src/commands/award/give.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { playerService } from \"../../services/playerService.js\";\nimport { leagueService } from \"../../services/leagueService.js\";\nimport { newsService } from \"../../services/newsService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command, AwardType, ExtendedClient } from \"../../types/index.js\";\n\nconst AWARD_TYPES: AwardType[] = [\n  \"Golden Boot\",\n  \"Golden Boy\",\n  \"Best Playmaker\",\n  \"Player of the Season\",\n  \"Team of the Season\",\n  \"Manager of the Season\",\n];\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"award\")\n    .setDescription(\"Award management commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"give\")\n        .setDescription(\"Give an award to a player (Management only)\")\n        .addStringOption((opt) =>\n          opt\n            .setName(\"type\")\n            .setDescription(\"Award type\")\n            .setRequired(true)\n            .addChoices(\n              ...AWARD_TYPES.map((t) => ({ name: t, value: t }))\n            )\n        )\n        .addUserOption((opt) =>\n          opt\n            .setName(\"player\")\n            .setDescription(\"Player to award\")\n            .setRequired(true)\n        )\n        .addStringOption((opt) =>\n          opt\n            .setName(\"reason\")\n            .setDescription(\"Reason for the award\")\n            .setRequired(false)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const member = interaction.member;\n    if (\n      !hasRole(member as never, RoleType.Founder) &&\n      !hasRole(member as never, RoleType.LeagueManagement)\n    ) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"Only **Founder** or **League Management** can give awards.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const awardType = interaction.options.getString(\"type\", true) as AwardType;\n    const targetUser = interaction.options.getUser(\"player\", true);\n    const reason = interaction.options.getString(\"reason\");\n\n    try {\n      const player = await playerService.getPlayer(targetUser.id);\n\n      if (!player) {\n        await interaction.editReply({\n          embeds: [\n            createErrorEmbed(\n              \"❌ Player Not Found\",\n              `${targetUser.username} is not registered as an LFC player.`\n            ),\n          ],\n        });\n        return;\n      }\n\n      const activeSeason = await leagueService.getActiveSeason();\n\n      if (!activeSeason) {\n        await interaction.editReply({\n          embeds: [\n            createErrorEmbed(\n              \"❌ No Active Season\",\n              \"Start a season before giving awards.\"\n            ),\n          ],\n        });\n        return;\n      }\n\n      // Check if player already has this award this season\n      const existingAward = await prisma.award.findUnique({\n        where: {\n          playerId_seasonId_type: {\n            playerId: player.id,\n            seasonId: activeSeason.id,\n            type: awardType,\n          },\n        },\n      });\n\n      if (existingAward) {\n        await interaction.editReply({\n          embeds: [\n            createErrorEmbed(\n              \"❌ Award Already Given\",\n              `${targetUser.username} already received **${awardType}** in ${activeSeason.name}.`\n            ),\n          ],\n        });\n        return;\n      }\n\n      const award = await prisma.award.create({\n        data: {\n          type: awardType,\n          playerId: player.id,\n          seasonId: activeSeason.id,\n          reason,\n        },\n        include: {\n          player: { include: { user: true } },\n          season: true,\n        },\n      });\n\n      const embed = new EmbedBuilder()\n        .setTitle(`🏅 Award Given!`)\n        .setColor(\"#FFD700\")\n        .setDescription(\n          `**${award.player.user.username}** has been awarded **${award.type}**!`\n        )\n        .addFields(\n          { name: \"🏅 Award\", value: award.type, inline: true },\n          { name: \"📅 Season\", value: award.season.name, inline: true },\n          {\n            name: \"📝 Reason\",\n            value: award.reason ?? \"Outstanding performance\",\n            inline: false,\n          }\n        )\n        .setFooter({ text: \"Legacy Football Championship\" })\n        .setTimestamp();\n\n      // Increment trophies counter\n      await prisma.player.update({\n        where: { id: player.id },\n        data: { trophies: { increment: 1 } },\n      });\n\n      // ── Auto-post award news ──\n      try {\n        if (interaction.guild) {\n          await newsService.announceAward(\n            interaction.client as ExtendedClient,\n            {\n              guildId: interaction.guild.id,\n              playerName: targetUser.username,\n              awardType: award.type,\n              season: award.season.name,\n              reason: award.reason ?? undefined,\n            }\n          );\n        }\n      } catch (newsError) {\n        console.error(\"[Award News Error]\", newsError);\n        // Non-fatal\n      }\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Award Give Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while giving the award.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/league/standings.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { leagueService } from \"../../services/leagueService.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"standings\")\n    .setDescription(\"View the current league table\"),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    try {\n      const activeSeason = await leagueService.getActiveSeason();\n\n      if (!activeSeason) {\n        await interaction.editReply({\n          content: \"❌ No active season. Use `/season start` to begin a season.\",\n        });\n        return;\n      }\n\n      const standings = await leagueService.getStandings(activeSeason.id);\n\n      const embed = new EmbedBuilder()\n        .setTitle(`🏆 ${activeSeason.name} — League Standings`)\n        .setColor(\"#00AA00\")\n        .setDescription(\n          standings.length > 0\n            ? standings\n                .map(\n                  (s) =>\n                    `**${s.position}.** ${getPositionEmoji(s.position)} **${s.teamName}**` +\n                    `\\n    ${s.played}PL | ${s.wins}W | ${s.draws}D | ${s.losses}L` +\n                    ` | GF:${s.goalsFor} GA:${s.goalsAgainst} GD:${s.goalDifference >= 0 ? \"+\" : \"\"}${s.goalDifference}` +\n                    ` | **${s.points}pts**`\n                )\n                .join(\"\\n\\n\")\n            : \"No standings data yet. Start the season and play matches!\"\n        )\n        .setFooter({ text: \"Legacy Football Championship\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Standings Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while fetching standings.\",\n      });\n    }\n  },\n};\n\nfunction getPositionEmoji(pos: number): string {\n  switch (pos) {\n    case 1:\n      return \"🥇\";\n    case 2:\n      return \"🥈\";\n    case 3:\n      return \"🥉\";\n    default:\n      return \"#\";\n  }\n}\n\nexport default command;","src/commands/league/fixtures.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { matchService } from \"../../services/matchService.js\";\nimport { leagueService } from \"../../services/leagueService.js\";\nimport { formatDate } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"fixtures\")\n    .setDescription(\"View upcoming match fixtures\"),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    try {\n      const activeSeason = await leagueService.getActiveSeason();\n      const fixtures = await matchService.getUpcomingFixtures(10);\n\n      const embed = new EmbedBuilder()\n        .setTitle(\"📅 Upcoming Fixtures\")\n        .setColor(\"#00AA00\");\n\n      if (fixtures.length > 0) {\n        for (const match of fixtures) {\n          embed.addFields({\n            name: `${match.homeTeam.name} vs ${match.awayTeam.name}`,\n            value: [\n              `📅 **Date:** ${formatDate(match.matchDate)}`,\n              `📊 **Season:** ${match.season.name}`,\n              match.refereeId ? `👨‍⚖️ **Referee:** <@${match.refereeId}>` : null,\n            ]\n              .filter(Boolean)\n              .join(\"\\n\"),\n            inline: false,\n          });\n        }\n      } else {\n        embed.setDescription(\n          activeSeason\n            ? \"No upcoming fixtures scheduled.\"\n            : \"No active season. Start a season first!\"\n        );\n      }\n\n      embed\n        .setFooter({ text: \"Legacy Football Championship\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Fixtures Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while fetching fixtures.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/league/results.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { matchService } from \"../../services/matchService.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"results\")\n    .setDescription(\"View recent match results\"),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    try {\n      const results = await matchService.getRecentResults(10);\n\n      const embed = new EmbedBuilder()\n        .setTitle(\"📋 Recent Results\")\n        .setColor(\"#00AA00\");\n\n      if (results.length > 0) {\n        for (const match of results) {\n          const homeWin = match.homeScore > match.awayScore;\n          const awayWin = match.awayScore > match.homeScore;\n          const scoreEmoji = homeWin ? \"🏠\" : awayWin ? \"🚗\" : \"🤝\";\n\n          // Get scorers if available\n          const scorers = match.goals\n            .slice(0, 3)\n            .map((g) => g.player.user.username)\n            .join(\", \");\n\n          // Get MVP if available\n          const mvp = match.mvps[0];\n\n          embed.addFields({\n            name: `${scoreEmoji} ${match.homeTeam.name} ${match.homeScore} - ${match.awayScore} ${match.awayTeam.name}`,\n            value: [\n              `📅 ${match.matchDate ? new Date(match.matchDate).toLocaleDateString() : \"N/A\"}`,\n              scorers ? `⚽ **Scorers:** ${scorers}` : null,\n              mvp ? `🏆 **MVP:** ${mvp.player.user.username}` : null,\n            ]\n              .filter(Boolean)\n              .join(\"\\n\"),\n            inline: false,\n          });\n        }\n      } else {\n        embed.setDescription(\"No match results yet.\");\n      }\n\n      embed\n        .setFooter({ text: \"Legacy Football Championship\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Results Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while fetching results.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/league/history.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { matchService } from \"../../services/matchService.js\";\nimport { formatDate } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"history\")\n    .setDescription(\"View match history between two teams\")\n    .addStringOption((opt) =>\n      opt\n        .setName(\"team1\")\n        .setDescription(\"First team name\")\n        .setRequired(true)\n    )\n    .addStringOption((opt) =>\n      opt\n        .setName(\"team2\")\n        .setDescription(\"Second team name\")\n        .setRequired(true)\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const team1Name = interaction.options.getString(\"team1\", true);\n    const team2Name = interaction.options.getString(\"team2\", true);\n\n    try {\n      const teamService = await import(\"../../services/teamService.js\").then(\n        (m) => m.teamService\n      );\n\n      const team1 = await teamService.getTeamByName(team1Name);\n      const team2 = await teamService.getTeamByName(team2Name);\n\n      if (!team1 || !team2) {\n        await interaction.editReply({\n          content: \"❌ One or both teams not found.\",\n        });\n        return;\n      }\n\n      const matches = await matchService.getTeamMatches(team1.id);\n      const headToHead = matches.filter(\n        (m) =>\n          (m.homeTeamId === team1.id && m.awayTeamId === team2.id) ||\n          (m.homeTeamId === team2.id && m.awayTeamId === team1.id)\n      );\n\n      if (headToHead.length === 0) {\n        await interaction.editReply({\n          content: `📋 **${team1.name}** and **${team2.name}** have no match history.`,\n        });\n        return;\n      }\n\n      // Calculate head-to-head record\n      let team1Wins = 0;\n      let team2Wins = 0;\n      let draws = 0;\n      let team1Goals = 0;\n      let team2Goals = 0;\n\n      for (const m of headToHead) {\n        if (m.status !== \"Finished\") continue;\n        const isTeam1Home = m.homeTeamId === team1.id;\n        const t1Score = isTeam1Home ? m.homeScore : m.awayScore;\n        const t2Score = isTeam1Home ? m.awayScore : m.homeScore;\n\n        team1Goals += t1Score;\n        team2Goals += t2Score;\n\n        if (t1Score > t2Score) team1Wins++;\n        else if (t2Score > t1Score) team2Wins++;\n        else draws++;\n      }\n\n      const embed = new EmbedBuilder()\n        .setTitle(`📊 Head-to-Head: ${team1.name} vs ${team2.name}`)\n        .setColor(\"#00AA00\")\n        .addFields(\n          {\n            name: `🏠 ${team1.name}`,\n            value: `${team1Wins} wins | ${team1Goals} goals`,\n            inline: true,\n          },\n          { name: \"🤝 Draws\", value: `${draws}`, inline: true },\n          {\n            name: `🚗 ${team2.name}`,\n            value: `${team2Wins} wins | ${team2Goals} goals`,\n            inline: true,\n          },\n          {\n            name: `📋 Last ${Math.min(headToHead.length, 5)} Meetings`,\n            value: headToHead\n              .slice(0, 5)\n              .map((m) => {\n                const isTeam1Home = m.homeTeamId === team1.id;\n                const t1Score = isTeam1Home ? m.homeScore : m.awayScore;\n                const t2Score = isTeam1Home ? m.awayScore : m.homeScore;\n                return `${formatDate(m.matchDate)}: ${team1.name} ${t1Score} - ${t2Score} ${team2.name}`;\n              })\n              .join(\"\\n\"),\n            inline: false,\n          }\n        )\n        .setFooter({ text: \"Legacy Football Championship\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[History Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while fetching history.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/match/create.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { matchService } from \"../../services/matchService.js\";\nimport { leagueService } from \"../../services/leagueService.js\";\nimport { teamService } from \"../../services/teamService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed, formatDate } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"match\")\n    .setDescription(\"Match management commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"create\")\n        .setDescription(\"Schedule a new match (Management/Referee only)\")\n        .addStringOption((opt) =>\n          opt\n            .setName(\"home\")\n            .setDescription(\"Home team name\")\n            .setRequired(true)\n        )\n        .addStringOption((opt) =>\n          opt\n            .setName(\"away\")\n            .setDescription(\"Away team name\")\n            .setRequired(true)\n        )\n        .addUserOption((opt) =>\n          opt\n            .setName(\"referee\")\n            .setDescription(\"Match referee\")\n            .setRequired(false)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const member = interaction.member;\n    if (\n      !hasRole(member as never, RoleType.Founder) &&\n      !hasRole(member as never, RoleType.LeagueManagement) &&\n      !hasRole(member as never, RoleType.Referee)\n    ) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"You need **Founder**, **League Management**, or **Referee** role to create matches.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const homeName = interaction.options.getString(\"home\", true);\n    const awayName = interaction.options.getString(\"away\", true);\n    const refereeUser = interaction.options.getUser(\"referee\");\n\n    try {\n      const homeTeam = await teamService.getTeamByName(homeName);\n      const awayTeam = await teamService.getTeamByName(awayName);\n\n      if (!homeTeam) {\n        await interaction.editReply({\n          embeds: [createErrorEmbed(\"❌ Team Not Found\", `Home team **${homeName}** not found.`)],\n        });\n        return;\n      }\n\n      if (!awayTeam) {\n        await interaction.editReply({\n          embeds: [createErrorEmbed(\"❌ Team Not Found\", `Away team **${awayName}** not found.`)],\n        });\n        return;\n      }\n\n      if (homeTeam.id === awayTeam.id) {\n        await interaction.editReply({\n          embeds: [createErrorEmbed(\"❌ Invalid Match\", \"A team cannot play against itself.\")],\n        });\n        return;\n      }\n\n      const activeSeason = await leagueService.getActiveSeason();\n      if (!activeSeason) {\n        await interaction.editReply({\n          embeds: [createErrorEmbed(\"❌ No Active Season\", \"Please start a season first using `/season start`.\")],\n        });\n        return;\n      }\n\n      const match = await matchService.createMatch({\n        homeTeamId: homeTeam.id,\n        awayTeamId: awayTeam.id,\n        seasonId: activeSeason.id,\n        refereeId: refereeUser?.id,\n      });\n\n      const embed = new EmbedBuilder()\n        .setTitle(\"⚽ Match Scheduled\")\n        .setColor(\"#00AA00\")\n        .addFields(\n          { name: \"🏠 Home\", value: homeTeam.name, inline: true },\n          { name: \"🆚\", value: \"vs\", inline: true },\n          { name: \"🚗 Away\", value: awayTeam.name, inline: true },\n          { name: \"📅 Season\", value: activeSeason.name, inline: true },\n          { name: \"🔢 Match ID\", value: match.id.slice(0, 8), inline: true },\n          { name: \"👨‍⚖️ Referee\", value: refereeUser ? `<@${refereeUser.id}>` : \"TBD\", inline: true },\n          { name: \"📋 Status\", value: \"🟢 Scheduled\", inline: false }\n        )\n        .setFooter({ text: \"Use /match start to begin the match\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Match Create Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while creating the match.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/match/start.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { matchService } from \"../../services/matchService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"match\")\n    .setDescription(\"Match commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"start\")\n        .setDescription(\"Start a scheduled match\")\n        .addStringOption((opt) =>\n          opt\n            .setName(\"match_id\")\n            .setDescription(\"Match ID to start\")\n            .setRequired(true)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const member = interaction.member;\n    if (\n      !hasRole(member as never, RoleType.Founder) &&\n      !hasRole(member as never, RoleType.LeagueManagement) &&\n      !hasRole(member as never, RoleType.Referee)\n    ) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"Only staff can start matches.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const matchId = interaction.options.getString(\"match_id\", true);\n\n    try {\n      const match = await matchService.startMatch(matchId);\n\n      const embed = new EmbedBuilder()\n        .setTitle(\"⚽ Match Started!\")\n        .setColor(\"#FFAA00\")\n        .setDescription(\n          `**${match.homeTeamId}** vs **${match.awayTeamId}** is now **LIVE**!`\n        )\n        .addFields(\n          { name: \"🟢 Status\", value: \"Live\", inline: true },\n          { name: \"🔢 Match ID\", value: match.id.slice(0, 8), inline: true }\n        )\n        .setFooter({ text: \"Use /match report to record goals, assists, and cards\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Match Start Error]\", error);\n      await interaction.editReply({\n        content: \"❌ Match not found or could not be started.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/match/report.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"match\")\n    .setDescription(\"Match commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"report\")\n        .setDescription(\"Report match events (goal, assist, card, MVP)\")\n        .addStringOption((opt) =>\n          opt\n            .setName(\"match_id\")\n            .setDescription(\"Match ID\")\n            .setRequired(true)\n        )\n        .addStringOption((opt) =>\n          opt\n            .setName(\"event\")\n            .setDescription(\"Event type\")\n            .setRequired(true)\n            .addChoices(\n              { name: \"⚽ Goal\", value: \"goal\" },\n              { name: \"🎯 Assist\", value: \"assist\" },\n              { name: \"🟨 Yellow Card\", value: \"yellow\" },\n              { name: \"🟥 Red Card\", value: \"red\" },\n              { name: \"🏆 MVP\", value: \"mvp\" }\n            )\n        )\n        .addUserOption((opt) =>\n          opt\n            .setName(\"player\")\n            .setDescription(\"Player involved\")\n            .setRequired(true)\n        )\n        .addStringOption((opt) =>\n          opt\n            .setName(\"minute\")\n            .setDescription(\"Minute of the event\")\n            .setRequired(false)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const member = interaction.member;\n    if (\n      !hasRole(member as never, RoleType.Founder) &&\n      !hasRole(member as never, RoleType.LeagueManagement) &&\n      !hasRole(member as never, RoleType.Referee)\n    ) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"Only staff can report match events.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const matchId = interaction.options.getString(\"match_id\", true);\n    const eventType = interaction.options.getString(\"event\", true);\n    const targetUser = interaction.options.getUser(\"player\", true);\n    const minute = interaction.options.getString(\"minute\");\n    const minuteNum = minute ? parseInt(minute) : undefined;\n\n    // Note: In production, you'd import playerService to resolve the player ID\n    // For now we output the event as a logged message\n    const eventEmojis: Record<string, string> = {\n      goal: \"⚽\",\n      assist: \"🎯\",\n      yellow: \"🟨\",\n      red: \"🟥\",\n      mvp: \"🏆\",\n    };\n\n    const embed = new EmbedBuilder()\n      .setTitle(`${eventEmojis[eventType] ?? \"📋\"} Match Event Reported`)\n      .setColor(\"#00AA00\")\n      .addFields(\n        { name: \"🔢 Match ID\", value: matchId.slice(0, 8), inline: true },\n        { name: \"📋 Event\", value: eventType.toUpperCase(), inline: true },\n        { name: \"👤 Player\", value: `<@${targetUser.id}>`, inline: true },\n        { name: \"⏱ Minute\", value: minute ?? \"N/A\", inline: true },\n        { name: \"📝 Reported By\", value: `<@${interaction.user.id}>`, inline: true }\n      )\n      .setFooter({ text: \"Use /match finish to end the match\" })\n      .setTimestamp();\n\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\n\nexport default command;","src/commands/match/finish.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { matchService } from \"../../services/matchService.js\";\nimport { newsService } from \"../../services/newsService.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command, ExtendedClient } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"match\")\n    .setDescription(\"Match commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"finish\")\n        .setDescription(\"Finish a match with the final score\")\n        .addStringOption((opt) =>\n          opt\n            .setName(\"match_id\")\n            .setDescription(\"Match ID to finish\")\n            .setRequired(true)\n        )\n        .addIntegerOption((opt) =>\n          opt\n            .setName(\"home_score\")\n            .setDescription(\"Home team final score\")\n            .setRequired(true)\n            .setMinValue(0)\n        )\n        .addIntegerOption((opt) =>\n          opt\n            .setName(\"away_score\")\n            .setDescription(\"Away team final score\")\n            .setRequired(true)\n            .setMinValue(0)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const member = interaction.member;\n    if (\n      !hasRole(member as never, RoleType.Founder) &&\n      !hasRole(member as never, RoleType.LeagueManagement) &&\n      !hasRole(member as never, RoleType.Referee)\n    ) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"Only staff can finish matches.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const matchId = interaction.options.getString(\"match_id\", true);\n    const homeScore = interaction.options.getInteger(\"home_score\", true);\n    const awayScore = interaction.options.getInteger(\"away_score\", true);\n\n    try {\n      const match = await matchService.finishMatch(matchId, {\n        homeScore,\n        awayScore,\n      });\n\n      // ── Auto-post match result news ──\n      try {\n        const fullMatch = await prisma.match.findUnique({\n          where: { id: match.id },\n          include: {\n            homeTeam: true,\n            awayTeam: true,\n            goals: { include: { player: { include: { user: true } } } },\n            mvps: { include: { player: { include: { user: true } } } },\n          },\n        });\n\n        if (fullMatch && interaction.guild) {\n          const scorers = fullMatch.goals.map(\n            (g) => `${g.player.user.username}${g.minute ? ` (${g.minute}')` : \"\"}`\n          );\n          const mvp = fullMatch.mvps[0]?.player.user.username;\n\n          await newsService.announceMatchResult(\n            interaction.client as ExtendedClient,\n            {\n              guildId: interaction.guild.id,\n              homeTeam: fullMatch.homeTeam.name,\n              awayTeam: fullMatch.awayTeam.name,\n              homeScore: fullMatch.homeScore,\n              awayScore: fullMatch.awayScore,\n              scorers,\n              mvp,\n              matchId: match.id,\n            }\n          );\n\n          // Check milestones for all goal scorers and MVP\n          for (const g of fullMatch.goals) {\n            await newsService.checkMilestones(\n              interaction.client as ExtendedClient,\n              interaction.guild.id,\n              g.playerId\n            );\n          }\n          if (fullMatch.mvps[0]) {\n            await newsService.checkMilestones(\n              interaction.client as ExtendedClient,\n              interaction.guild.id,\n              fullMatch.mvps[0].playerId\n            );\n          }\n        }\n      } catch (newsError) {\n        console.error(\"[Match News Error]\", newsError);\n        // Non-fatal — match result is still saved\n      }\n\n      const winnerText =\n        homeScore > awayScore\n          ? \"🏠 **Home team wins!**\"\n          : awayScore > homeScore\n            ? \"🚗 **Away team wins!**\"\n            : \"🤝 **It's a draw!**\";\n\n      const embed = new EmbedBuilder()\n        .setTitle(\"✅ Match Finished!\")\n        .setColor(\"#00AA00\")\n        .setDescription(\n          `**${match.homeTeamId}** ${match.homeScore} - ${match.awayScore} **${match.awayTeamId}**`\n        )\n        .addFields(\n          { name: \"📋 Result\", value: winnerText, inline: false },\n          { name: \"🔢 Match ID\", value: match.id.slice(0, 8), inline: true },\n          { name: \"📊 Status\", value: \"✅ Finished\", inline: true }\n        )\n        .setFooter({\n          text: \"Standings have been updated | Legacy Football Championship\",\n        })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Match Finish Error]\", error);\n      await interaction.editReply({\n        content: \"❌ Failed to finish the match. Check the match ID.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/news/setchannel.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  ChannelType,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { newsService } from \"../../services/newsService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"news\")\n    .setDescription(\"News and media commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"setchannel\")\n        .setDescription(\"Set the news broadcast channel (Management only)\")\n        .addChannelOption((opt) =>\n          opt\n            .setName(\"channel\")\n            .setDescription(\"The text channel for news broadcasts\")\n            .setRequired(true)\n            .addChannelTypes(ChannelType.GuildText)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const member = interaction.member;\n    if (\n      !hasRole(member as never, RoleType.Founder) &&\n      !hasRole(member as never, RoleType.LeagueManagement)\n    ) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"You need **Founder** or **League Management** role.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const channel = interaction.options.getChannel(\"channel\", true);\n    if (!interaction.guild) return;\n\n    await newsService.setNewsChannel(interaction.guild.id, channel.id);\n\n    const embed = new EmbedBuilder()\n      .setTitle(\"📢 News Channel Configured!\")\n      .setColor(\"#00AA00\")\n      .setDescription(\n        `All auto-news will now be posted in ${channel}.`\n      )\n      .addFields(\n        { name: \"📺 Channel\", value: `${channel}`, inline: true },\n        {\n          name: \"📋 Auto-Posts Include\",\n          value: [\n            \"• ⚽ Match results & highlights\",\n            \"• 🔄 Transfer announcements\",\n            \"• 🏅 Award ceremonies\",\n            \"• 📅 Season start/end\",\n            \"• 🌟 Player milestones\",\n            \"• 📊 Weekly roundups\",\n            \"• 📢 Breaking broadcasts\",\n          ].join(\"\\n\"),\n          inline: false,\n        }\n      )\n      .setFooter({ text: \"Legacy Football Championship • News System\" })\n      .setTimestamp();\n\n    await interaction.editReply({ embeds: [embed] });\n  },\n};\n\nexport default command;","src/commands/news/latest.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { newsService } from \"../../services/newsService.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst TYPE_EMOJIS: Record<string, string> = {\n  match_result: \"⚽\",\n  transfer: \"🔄\",\n  award: \"🏅\",\n  season_start: \"📅\",\n  season_end: \"🏆\",\n  milestone: \"🌟\",\n  broadcast: \"📢\",\n  weekly_roundup: \"📊\",\n};\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"news\")\n    .setDescription(\"News commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"latest\")\n        .setDescription(\"View the latest LFC news and announcements\")\n        .addIntegerOption((opt) =>\n          opt\n            .setName(\"count\")\n            .setDescription(\"Number of articles to show (1-20)\")\n            .setRequired(false)\n            .setMinValue(1)\n            .setMaxValue(20)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const count = interaction.options.getInteger(\"count\") ?? 5;\n    const guildId = interaction.guild?.id;\n    if (!guildId) return;\n\n    try {\n      const articles = await newsService.getRecentNews(guildId, count);\n\n      const embed = new EmbedBuilder()\n        .setTitle(\"📰 Latest LFC News\")\n        .setColor(\"#00AA00\");\n\n      if (articles.length > 0) {\n        embed.setDescription(\n          articles\n            .map(\n              (a, i) =>\n                `${i + 1}. ${TYPE_EMOJIS[a.type] ?? \"📰\"} **${a.title}**\\n` +\n                `   ${a.content.slice(0, 100)}${a.content.length > 100 ? \"...\" : \"\"}\\n` +\n                `   🕐 <t:${Math.floor(a.createdAt.getTime() / 1000)}:R>`\n            )\n            .join(\"\\n\\n\")\n        );\n      } else {\n        embed.setDescription(\"No news articles yet. As matches happen, transfers complete, and awards are given, they'll appear here automatically!\");\n      }\n\n      embed\n        .setFooter({\n          text: `Showing last ${articles.length || 0} articles • Legacy Football Championship`,\n        })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[News Latest Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while fetching news.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/news/broadcast.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { newsService } from \"../../services/newsService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"news\")\n    .setDescription(\"News commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"broadcast\")\n        .setDescription(\"Send a breaking news broadcast (Management only)\")\n        .addStringOption((opt) =>\n          opt\n            .setName(\"title\")\n            .setDescription(\"Broadcast headline\")\n            .setRequired(true)\n        )\n        .addStringOption((opt) =>\n          opt\n            .setName(\"message\")\n            .setDescription(\"Broadcast message content\")\n            .setRequired(true)\n        )\n        .addStringOption((opt) =>\n          opt\n            .setName(\"color\")\n            .setDescription(\"Embed color (red, blue, green, gold)\")\n            .setRequired(false)\n            .addChoices(\n              { name: \"🔴 Red (Urgent)\", value: \"#FF0000\" },\n              { name: \"🔵 Blue (Info)\", value: \"#0066FF\" },\n              { name: \"🟢 Green (Positive)\", value: \"#00AA00\" },\n              { name: \"🟡 Gold (Important)\", value: \"#FFD700\" }\n            )\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply({ ephemeral: true });\n\n    const member = interaction.member;\n    if (\n      !hasRole(member as never, RoleType.Founder) &&\n      !hasRole(member as never, RoleType.LeagueManagement)\n    ) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"Only **Founder** or **League Management** can broadcast.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const title = interaction.options.getString(\"title\", true);\n    const message = interaction.options.getString(\"message\", true);\n    const color = interaction.options.getString(\"color\") ?? \"#FF0000\";\n\n    if (!interaction.guild?.id) return;\n\n    try {\n      const result = await newsService.announceBroadcast(\n        interaction.client as never,\n        {\n          guildId: interaction.guild.id,\n          title,\n          message,\n          authorName: interaction.user.username,\n          color,\n        }\n      );\n\n      if (result) {\n        await interaction.editReply({\n          content: `✅ Broadcast sent! [View message](${result.url})`,\n        });\n      } else {\n        await interaction.editReply({\n          content: \"⚠️ Broadcast published but no news channel is configured. Use `/news setchannel` first.\",\n        });\n      }\n    } catch (error) {\n      console.error(\"[Broadcast Error]\", error);\n      await interaction.editReply({\n        content: \"❌ Failed to send broadcast. Make sure a news channel is set via `/news setchannel`.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/news/roundup.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n} from \"discord.js\";\nimport { newsService } from \"../../services/newsService.js\";\nimport { leagueService } from \"../../services/leagueService.js\";\nimport { playerService } from \"../../services/playerService.js\";\nimport { matchService } from \"../../services/matchService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"news\")\n    .setDescription(\"News commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"roundup\")\n        .setDescription(\"Generate a weekly league roundup (Management only)\")\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply({ ephemeral: true });\n\n    const member = interaction.member;\n    if (\n      !hasRole(member as never, RoleType.Founder) &&\n      !hasRole(member as never, RoleType.LeagueManagement)\n    ) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"You need **Founder** or **League Management** role.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const guildId = interaction.guild?.id;\n    if (!guildId) return;\n\n    try {\n      const activeSeason = await leagueService.getActiveSeason();\n      if (!activeSeason) {\n        await interaction.editReply({\n          content: \"❌ No active season to generate a roundup for.\",\n        });\n        return;\n      }\n\n      const standings = await leagueService.getStandings(activeSeason.id);\n      const topScorers = await playerService.getTopGoalscorers(5);\n      const results = await matchService.getRecentResults(5);\n\n      const result = await newsService.generateWeeklyRoundup(\n        interaction.client as never,\n        guildId,\n        activeSeason.name,\n        standings.map((s) => ({\n          position: s.position,\n          teamName: s.teamName,\n          played: s.played,\n          wins: s.wins,\n          draws: s.draws,\n          losses: s.losses,\n          points: s.points,\n        })),\n        topScorers.map((p) => ({\n          name: p.user.username,\n          goals: p.goals,\n          team: p.team?.name,\n        })),\n        results.map((m) => ({\n          homeTeam: m.homeTeam.name,\n          awayTeam: m.awayTeam.name,\n          homeScore: m.homeScore,\n          awayScore: m.awayScore,\n        }))\n      );\n\n      if (result) {\n        await interaction.editReply({\n          content: `✅ Weekly roundup published! [View post](${result.url})`,\n        });\n      } else {\n        await interaction.editReply({\n          content: \"⚠️ Roundup generated but no news channel is configured. Use `/news setchannel` first.\",\n        });\n      }\n    } catch (error) {\n      console.error(\"[Roundup Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while generating the roundup.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/player/profile.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { playerService } from \"../../services/playerService.js\";\nimport { formatSeasonStats, formatDate } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"player\")\n    .setDescription(\"View a player's full profile\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"profile\")\n        .setDescription(\"View a player profile\")\n        .addUserOption((opt) =>\n          opt\n            .setName(\"player\")\n            .setDescription(\"The player to look up\")\n            .setRequired(true)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const targetUser = interaction.options.getUser(\"player\", true);\n\n    try {\n      const player = await playerService.getPlayer(targetUser.id);\n\n      if (!player) {\n        const embed = new EmbedBuilder()\n          .setTitle(\"❌ Player Not Found\")\n          .setDescription(\n            `${targetUser.username} is not registered as an LFC player yet. They need to play their first match to be registered.`\n          )\n          .setColor(\"#FF0000\")\n          .setTimestamp();\n\n        await interaction.editReply({ embeds: [embed] });\n        return;\n      }\n\n      // Season stats display\n      const seasonStatsText =\n        player.seasonStats.length > 0\n          ? player.seasonStats\n              .map(\n                (s) =>\n                  `**${s.season.name}**: ⚽ ${s.goals}G | 🎯 ${s.assists}A | 🏆 ${s.mvps} MVP | 📋 ${s.appearances} Apps`\n              )\n              .join(\"\\n\")\n          : \"No season data yet.\";\n\n      // Career stats\n      const careerStats = {\n        goals: player.goals,\n        assists: player.assists,\n        mvps: player.mvps,\n        appearances: player.appearances,\n        yellowCards: player.yellowCards,\n        redCards: player.redCards,\n      };\n\n      // Awards\n      const awardsText =\n        player.awards.length > 0\n          ? player.awards\n              .map((a) => `🏅 **${a.type}** — ${a.season.name}`)\n              .join(\"\\n\")\n          : \"No awards yet.\";\n\n      // Transfers\n      const transfers = await playerService.getTransferHistory(player.id);\n      const transfersText =\n        transfers.length > 0\n          ? transfers\n              .slice(0, 5)\n              .map(\n                (t) =>\n                  `🔄 ${t.fromTeamName ?? \"Free Agent\"} → ${t.toTeamName ?? \"Free Agent\"}${t.fee ? ` ($${t.fee}M)` : \"\"}`\n              )\n              .join(\"\\n\")\n          : \"No transfer history.\";\n\n      const embed = new EmbedBuilder()\n        .setTitle(`${targetUser.username} — LFC Profile`)\n        .setThumbnail(targetUser.displayAvatarURL())\n        .setColor(\"#00AA00\")\n        .addFields(\n          {\n            name: \"👤 General\",\n            value: [\n              `**LFC ID:** ${player.lfcId}`,\n              `**Discord ID:** ${player.discordId}`,\n              `**Joined:** ${formatDate(player.joinedAt)}`,\n            ].join(\"\\n\"),\n            inline: false,\n          },\n          {\n            name: \"⚽ Club & Position\",\n            value: [\n              `**Club:** ${player.team?.name ?? \"Free Agent\"}`,\n              `**Position:** ${player.position}`,\n              `**Region:** ${player.region}`,\n            ].join(\"\\n\"),\n            inline: true,\n          },\n          {\n            name: \"🏆 Trophies & Awards\",\n            value: `**Trophies:** ${player.trophies}\\n${awardsText}`,\n            inline: true,\n          },\n          {\n            name: \"📊 Season Stats\",\n            value: seasonStatsText,\n            inline: false,\n          },\n          {\n            name: \"📈 Career Stats\",\n            value: formatSeasonStats(careerStats),\n            inline: false,\n          },\n          {\n            name: \"🔄 Transfer History\",\n            value: transfersText,\n            inline: false,\n          }\n        )\n        .setFooter({ text: \"Legacy Football Championship\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Player Profile Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while fetching the player profile.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/player/stats.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { playerService } from \"../../services/playerService.js\";\nimport { formatSeasonStats } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"player\")\n    .setDescription(\"Player commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"stats\")\n        .setDescription(\"View a player's detailed career statistics\")\n        .addUserOption((opt) =>\n          opt\n            .setName(\"player\")\n            .setDescription(\"The player to view stats for\")\n            .setRequired(true)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const targetUser = interaction.options.getUser(\"player\", true);\n\n    try {\n      const player = await playerService.getPlayer(targetUser.id);\n\n      if (!player) {\n        await interaction.editReply({\n          content: `❌ ${targetUser.username} is not registered as an LFC player.`,\n        });\n        return;\n      }\n\n      const embed = new EmbedBuilder()\n        .setTitle(`📊 ${targetUser.username} — Career Statistics`)\n        .setThumbnail(targetUser.displayAvatarURL())\n        .setColor(\"#00AA00\");\n\n      // Per-season breakdown\n      if (player.seasonStats.length > 0) {\n        for (const stat of player.seasonStats) {\n          embed.addFields({\n            name: `📅 ${stat.season.name}`,\n            value: formatSeasonStats({\n              goals: stat.goals,\n              assists: stat.assists,\n              mvps: stat.mvps,\n              appearances: stat.appearances,\n              yellowCards: stat.yellowCards,\n              redCards: stat.redCards,\n            }),\n            inline: true,\n          });\n        }\n      } else {\n        embed.addFields({\n          name: \"No Season Data\",\n          value: \"This player hasn't recorded any stats yet.\",\n          inline: false,\n        });\n      }\n\n      // Career totals\n      embed.addFields({\n        name: \"🏆 Career Totals\",\n        value: formatSeasonStats({\n          goals: player.goals,\n          assists: player.assists,\n          mvps: player.mvps,\n          appearances: player.appearances,\n          yellowCards: player.yellowCards,\n          redCards: player.redCards,\n        }),\n        inline: false,\n      });\n\n      embed.setFooter({ text: \"Legacy Football Championship\" }).setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Player Stats Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while fetching player stats.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/player/leaderboard.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n  ActionRowBuilder,\n  StringSelectMenuBuilder,\n  ComponentType,\n} from \"discord.js\";\nimport { playerService } from \"../../services/playerService.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst LEADERBOARD_TYPES = [\n  { label: \"⚽ Top Goalscorers\", value: \"goals\", emoji: \"⚽\" },\n  { label: \"🎯 Top Assists\", value: \"assists\", emoji: \"🎯\" },\n  { label: \"🏆 Most MVPs\", value: \"mvps\", emoji: \"🏆\" },\n  { label: \"📋 Most Appearances\", value: \"appearances\", emoji: \"📋\" },\n] as const;\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"leaderboard\")\n    .setDescription(\"View league leaderboards\")\n    .addStringOption((opt) =>\n      opt\n        .setName(\"type\")\n        .setDescription(\"Leaderboard category\")\n        .setRequired(false)\n        .addChoices(\n          { name: \"⚽ Top Goalscorers\", value: \"goals\" },\n          { name: \"🎯 Top Assists\", value: \"assists\" },\n          { name: \"🏆 Most MVPs\", value: \"mvps\" },\n          { name: \"📋 Most Appearances\", value: \"appearances\" }\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const selectedType = interaction.options.getString(\"type\") ?? \"goals\";\n\n    try {\n      await showLeaderboard(interaction, selectedType);\n    } catch (error) {\n      console.error(\"[Leaderboard Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while fetching the leaderboard.\",\n      });\n    }\n  },\n};\n\nasync function showLeaderboard(\n  interaction: CommandInteraction,\n  type: string\n) {\n  let players: Array<{\n    user: { username: string; globalName: string | null };\n    team: { name: string } | null;\n    goals: number;\n    assists: number;\n    mvps: number;\n    appearances: number;\n  }>;\n  let title: string;\n  let valueKey: string;\n\n  switch (type) {\n    case \"assists\":\n      players = await playerService.getTopAssists();\n      title = \"🎯 Top Assists\";\n      valueKey = \"assists\";\n      break;\n    case \"mvps\":\n      players = await playerService.getTopMvps();\n      title = \"🏆 Most MVPs\";\n      valueKey = \"mvps\";\n      break;\n    case \"appearances\":\n      players = await playerService.getTopAppearances();\n      title = \"📋 Most Appearances\";\n      valueKey = \"appearances\";\n      break;\n    default:\n      players = await playerService.getTopGoalscorers();\n      title = \"⚽ Top Goalscorers\";\n      valueKey = \"goals\";\n  }\n\n  const embed = new EmbedBuilder()\n    .setTitle(title)\n    .setColor(\"#00AA00\")\n    .setDescription(\n      players.length > 0\n        ? players\n            .map(\n              (p, i) =>\n                `${i + 1}. **${p.user.globalName ?? p.user.username}**` +\n                `${p.team ? ` (${p.team.name})` : \"\"} — **${(p as Record<string, number>)[valueKey]}**`\n            )\n            .join(\"\\n\")\n        : \"No data available yet.\"\n    )\n    .setFooter({ text: \"Legacy Football Championship\" })\n    .setTimestamp();\n\n  // Add a select menu to switch leaderboard types\n  const select = new StringSelectMenuBuilder()\n    .setCustomId(\"leaderboard_select\")\n    .setPlaceholder(\"Switch leaderboard...\")\n    .addOptions(\n      LEADERBOARD_TYPES.map((lt) => ({\n        label: lt.label,\n        value: lt.value,\n      }))\n    );\n\n  const row = new ActionRowBuilder<StringSelectMenuBuilder>().addComponents(\n    select\n  );\n\n  const reply = await interaction.editReply({\n    embeds: [embed],\n    components: [row],\n  });\n\n  // Handle select menu interaction\n  const collector = reply.createMessageComponentCollector({\n    componentType: ComponentType.StringSelect,\n    time: 60_000,\n  });\n\n  collector.on(\"collect\", async (selectInteraction) => {\n    if (selectInteraction.user.id !== interaction.user.id) {\n      await selectInteraction.reply({\n        content: \"❌ Only the command author can use this.\",\n        ephemeral: true,\n      });\n      return;\n    }\n\n    await selectInteraction.deferUpdate();\n    await showLeaderboard(\n      selectInteraction as unknown as CommandInteraction,\n      selectInteraction.values[0]\n    );\n  });\n\n  collector.on(\"end\", async () => {\n    const disabledRow =\n      ActionRowBuilder.from<StringSelectMenuBuilder>(row);\n    disabledRow.components.forEach((c) => c.setDisabled(true));\n\n    await interaction.editReply({ components: [disabledRow] });\n  });\n}\n\nexport default command;","src/commands/team/create.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { teamService } from \"../../services/teamService.js\";\nimport { playerService } from \"../../services/playerService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"team\")\n    .setDescription(\"Team management commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"create\")\n        .setDescription(\"Create a new team (Management only)\")\n        .addStringOption((opt) =>\n          opt\n            .setName(\"name\")\n            .setDescription(\"Full team name (e.g. Legacy FC)\")\n            .setRequired(true)\n        )\n        .addStringOption((opt) =>\n          opt\n            .setName(\"short\")\n            .setDescription(\"Short name (e.g. LFC)\")\n            .setRequired(false)\n        )\n        .addStringOption((opt) =>\n          opt\n            .setName(\"description\")\n            .setDescription(\"Team description\")\n            .setRequired(false)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    // Permission check\n    const member = interaction.member;\n    if (\n      !hasRole(member as never, RoleType.Founder) &&\n      !hasRole(member as never, RoleType.LeagueManagement)\n    ) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"You need the **Founder** or **League Management** role to create teams.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const name = interaction.options.getString(\"name\", true);\n    const shortName = interaction.options.getString(\"short\");\n    const description = interaction.options.getString(\"description\");\n    const managerId = interaction.user.id;\n\n    try {\n      // Ensure user exists in DB\n      await playerService.getOrCreatePlayer(managerId, interaction.user.username);\n\n      // Check if team name is taken\n      const existing = await teamService.getTeamByName(name);\n      if (existing) {\n        await interaction.editReply({\n          embeds: [\n            createErrorEmbed(\n              \"❌ Team Already Exists\",\n              `A team named **${name}** already exists.`\n            ),\n          ],\n        });\n        return;\n      }\n\n      const team = await teamService.createTeam({\n        name,\n        shortName: shortName ?? undefined,\n        description: description ?? undefined,\n        managerId,\n      });\n\n      const embed = new EmbedBuilder()\n        .setTitle(`✅ Team Created: ${team.name}`)\n        .setColor(\"#00AA00\")\n        .addFields(\n          { name: \"📛 Name\", value: team.name, inline: true },\n          {\n            name: \"🔤 Short Name\",\n            value: team.shortName ?? \"None\",\n            inline: true,\n          },\n          {\n            name: \"👤 Manager\",\n            value: `<@${team.manager.discordId}>`,\n            inline: true,\n          },\n          {\n            name: \"📝 Description\",\n            value: team.description ?? \"No description.\",\n            inline: false,\n          }\n        )\n        .setFooter({ text: \"Legacy Football Championship\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Team Create Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while creating the team.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/team/info.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { teamService } from \"../../services/teamService.js\";\nimport { formatDate } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"team\")\n    .setDescription(\"Team commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"info\")\n        .setDescription(\"View team information\")\n        .addStringOption((opt) =>\n          opt\n            .setName(\"name\")\n            .setDescription(\"Team name\")\n            .setRequired(true)\n            .setAutocomplete(true)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const teamName = interaction.options.getString(\"name\", true);\n\n    try {\n      const team = await teamService.getTeamByName(teamName);\n\n      if (!team) {\n        await interaction.editReply({\n          content: `❌ Team **${teamName}** not found.`,\n        });\n        return;\n      }\n\n      // Get current season stats\n      const seasonStats = team.seasonTeams[team.seasonTeams.length - 1];\n\n      const embed = new EmbedBuilder()\n        .setTitle(`🏟️ ${team.name} ${team.shortName ? `(${team.shortName})` : \"\"}`)\n        .setColor(\"#00AA00\")\n        .addFields(\n          {\n            name: \"👤 Manager\",\n            value: `<@${team.manager.discordId}>`,\n            inline: true,\n          },\n          {\n            name: \"👥 Squad Size\",\n            value: `${team.players.length} players`,\n            inline: true,\n          },\n          {\n            name: \"🏆 Trophies\",\n            value: `${team.trophies}`,\n            inline: true,\n          },\n          {\n            name: \"📝 Description\",\n            value: team.description ?? \"No description set.\",\n            inline: false,\n          }\n        );\n\n      // Add season stats if available\n      if (seasonStats) {\n        embed.addFields({\n          name: `📊 Season Record (${seasonStats.season?.name ?? \"Current\"})`,\n          value: [\n            `**Played:** ${seasonStats.played}`,\n            `**Wins:** ${seasonStats.wins}`,\n            `**Draws:** ${seasonStats.draws}`,\n            `**Losses:** ${seasonStats.losses}`,\n            `**Goals For:** ${seasonStats.goalsFor}`,\n            `**Goals Against:** ${seasonStats.goalsAgainst}`,\n            `**GD:** ${seasonStats.goalsFor - seasonStats.goalsAgainst}`,\n            `**Points:** ${seasonStats.points}`,\n          ].join(\" | \"),\n          inline: false,\n        });\n      }\n\n      // Top 5 players by goals\n      const topScorers = [...team.players]\n        .sort((a, b) => b.goals - a.goals)\n        .slice(0, 5);\n\n      if (topScorers.length > 0) {\n        embed.addFields({\n          name: \"⚽ Top Scorers\",\n          value: topScorers\n            .map(\n              (p, i) =>\n                `${i + 1}. **${p.user.username}** — ${p.goals}G / ${p.assists}A`\n            )\n            .join(\"\\n\"),\n          inline: false,\n        });\n      }\n\n      embed\n        .setFooter({ text: \"Legacy Football Championship\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Team Info Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while fetching team info.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/team/roster.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { teamService } from \"../../services/teamService.js\";\nimport type { Command } from \"../../types/index.js\";\nimport type { Position } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"team\")\n    .setDescription(\"Team commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"roster\")\n        .setDescription(\"View a team's full roster\")\n        .addStringOption((opt) =>\n          opt\n            .setName(\"name\")\n            .setDescription(\"Team name\")\n            .setRequired(true)\n            .setAutocomplete(true)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const teamName = interaction.options.getString(\"name\", true);\n\n    try {\n      const team = await teamService.getTeamByName(teamName);\n\n      if (!team) {\n        await interaction.editReply({\n          content: `❌ Team **${teamName}** not found.`,\n        });\n        return;\n      }\n\n      const positions: Position[] = [\n        \"Goalkeeper\",\n        \"Defender\",\n        \"Midfielder\",\n        \"Forward\",\n      ];\n\n      const embed = new EmbedBuilder()\n        .setTitle(`👥 ${team.name} — Squad Roster`)\n        .setColor(\"#00AA00\");\n\n      let totalPlayers = 0;\n\n      for (const pos of positions) {\n        const positionPlayers = team.players.filter(\n          (p) => p.position === pos\n        );\n\n        if (positionPlayers.length > 0) {\n          totalPlayers += positionPlayers.length;\n          embed.addFields({\n            name: `${getPositionEmoji(pos)} ${pos}s (${positionPlayers.length})`,\n            value: positionPlayers\n              .map(\n                (p) =>\n                  `**${p.user.username}** — ⚽ ${p.goals}G / 🎯 ${p.assists}A / 🏆 ${p.mvps} MVP`\n              )\n              .join(\"\\n\"),\n            inline: false,\n          });\n        } else {\n          embed.addFields({\n            name: `${getPositionEmoji(pos)} ${pos}s`,\n            value: \"No players\",\n            inline: true,\n          });\n        }\n      }\n\n      embed.setFooter({\n        text: `Total: ${totalPlayers} players | Legacy Football Championship`,\n      });\n      embed.setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Team Roster Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while fetching the roster.\",\n      });\n    }\n  },\n};\n\nfunction getPositionEmoji(position: Position): string {\n  switch (position) {\n    case \"Goalkeeper\":\n      return \"🧤\";\n    case \"Defender\":\n      return \"🛡️\";\n    case \"Midfielder\":\n      return \"🎯\";\n    case \"Forward\":\n      return \"⚽\";\n    default:\n      return \"👤\";\n  }\n}\n\nexport default command;","src/commands/team/stats.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { teamService } from \"../../services/teamService.js\";\nimport { leagueService } from \"../../services/leagueService.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"team\")\n    .setDescription(\"Team commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"stats\")\n        .setDescription(\"View detailed team statistics\")\n        .addStringOption((opt) =>\n          opt\n            .setName(\"name\")\n            .setDescription(\"Team name\")\n            .setRequired(true)\n            .setAutocomplete(true)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const teamName = interaction.options.getString(\"name\", true);\n\n    try {\n      const team = await teamService.getTeamByName(teamName);\n\n      if (!team) {\n        await interaction.editReply({\n          content: `❌ Team **${teamName}** not found.`,\n        });\n        return;\n      }\n\n      const activeSeason = await leagueService.getActiveSeason();\n\n      const embed = new EmbedBuilder()\n        .setTitle(`📊 ${team.name} — Statistics`)\n        .setColor(\"#00AA00\");\n\n      // Season-by-season breakdown\n      if (team.seasonTeams.length > 0) {\n        for (const stat of team.seasonTeams) {\n          const gd = stat.goalsFor - stat.goalsAgainst;\n          const gdText = gd >= 0 ? `+${gd}` : `${gd}`;\n          embed.addFields({\n            name: `📅 ${stat.season?.name ?? \"Unknown Season\"}`,\n            value: [\n              `**Played:** ${stat.played}`,\n              `**Wins:** ${stat.wins}`,\n              `**Draws:** ${stat.draws}`,\n              `**Losses:** ${stat.losses}`,\n              `**GF:** ${stat.goalsFor} | **GA:** ${stat.goalsAgainst} | **GD:** ${gdText}`,\n              `**Points:** ${stat.points} (${((stat.points / (stat.played * 3)) * 100).toFixed(1)}% win rate)`,\n            ].join(\"\\n\"),\n            inline: true,\n          });\n        }\n      } else {\n        embed.addFields({\n          name: \"No Season Data\",\n          value: \"This team hasn't played any matches yet.\",\n          inline: false,\n        });\n      }\n\n      // Player contributions\n      const topScorer = [...team.players].sort((a, b) => b.goals - a.goals)[0];\n      const topAssist = [...team.players].sort(\n        (a, b) => b.assists - a.assists\n      )[0];\n      const topMvp = [...team.players].sort((a, b) => b.mvps - a.mvps)[0];\n\n      embed.addFields({\n        name: \"🌟 Key Players\",\n        value: [\n          `⚽ **Top Scorer:** ${topScorer ? `${topScorer.user.username} (${topScorer.goals}G)` : \"N/A\"}`,\n          `🎯 **Top Assists:** ${topAssist ? `${topAssist.user.username} (${topAssist.assists}A)` : \"N/A\"}`,\n          `🏆 **Most MVPs:** ${topMvp ? `${topMvp.user.username} (${topMvp.mvps})` : \"N/A\"}`,\n        ].join(\"\\n\"),\n        inline: false,\n      });\n\n      embed\n        .setFooter({ text: \"Legacy Football Championship\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Team Stats Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while fetching team stats.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/transfer/create.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { playerService } from \"../../services/playerService.js\";\nimport { teamService } from \"../../services/teamService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"transfer\")\n    .setDescription(\"Transfer management commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"create\")\n        .setDescription(\"Create a transfer request (Management only)\")\n        .addUserOption((opt) =>\n          opt\n            .setName(\"player\")\n            .setDescription(\"Player to transfer\")\n            .setRequired(true)\n        )\n        .addStringOption((opt) =>\n          opt\n            .setName(\"to_team\")\n            .setDescription(\"Destination team\")\n            .setRequired(true)\n        )\n        .addIntegerOption((opt) =>\n          opt\n            .setName(\"fee\")\n            .setDescription(\"Transfer fee (in millions)\")\n            .setRequired(false)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const member = interaction.member;\n    if (\n      !hasRole(member as never, RoleType.Founder) &&\n      !hasRole(member as never, RoleType.LeagueManagement)\n    ) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"Only **Founder** or **League Management** can create transfers.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const targetUser = interaction.options.getUser(\"player\", true);\n    const toTeamName = interaction.options.getString(\"to_team\", true);\n    const fee = interaction.options.getInteger(\"fee\");\n\n    try {\n      const player = await playerService.getPlayer(targetUser.id);\n      if (!player) {\n        await interaction.editReply({\n          embeds: [createErrorEmbed(\"❌ Player Not Found\", `${targetUser.username} is not registered.`)],\n        });\n        return;\n      }\n\n      const toTeam = await teamService.getTeamByName(toTeamName);\n      if (!toTeam) {\n        await interaction.editReply({\n          embeds: [createErrorEmbed(\"❌ Team Not Found\", `Team **${toTeamName}** not found.`)],\n        });\n        return;\n      }\n\n      const transfer = await prisma.transfer.create({\n        data: {\n          playerId: player.id,\n          fromTeamId: player.teamId,\n          fromTeamName: player.team?.name ?? \"Free Agent\",\n          toTeamId: toTeam.id,\n          toTeamName: toTeam.name,\n          fee,\n          status: \"Pending\",\n        },\n      });\n\n      const embed = new EmbedBuilder()\n        .setTitle(\"🔄 Transfer Request Created\")\n        .setColor(\"#FFAA00\")\n        .addFields(\n          { name: \"👤 Player\", value: `<@${targetUser.id}>`, inline: true },\n          { name: \"➡️ Destination\", value: toTeam.name, inline: true },\n          { name: \"💰 Fee\", value: fee ? `$${fee}M` : \"Free Transfer\", inline: true },\n          { name: \"📋 Status\", value: \"⏳ Pending\", inline: true },\n          { name: \"🔢 Transfer ID\", value: transfer.id.slice(0, 8), inline: true }\n        )\n        .setFooter({ text: \"Use /transfer complete to finalize\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Transfer Create Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while creating the transfer.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/transfer/complete.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport { teamService } from \"../../services/teamService.js\";\nimport { newsService } from \"../../services/newsService.js\";\nimport { hasRole, RoleType } from \"../../utils/permissions.js\";\nimport { createErrorEmbed } from \"../../utils/helpers.js\";\nimport type { Command, ExtendedClient } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"transfer\")\n    .setDescription(\"Transfer commands\")\n    .addSubcommand((sub) =>\n      sub\n        .setName(\"complete\")\n        .setDescription(\"Complete a pending transfer\")\n        .addStringOption((opt) =>\n          opt\n            .setName(\"transfer_id\")\n            .setDescription(\"Transfer ID to complete\")\n            .setRequired(true)\n        )\n    ),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    const member = interaction.member;\n    if (\n      !hasRole(member as never, RoleType.Founder) &&\n      !hasRole(member as never, RoleType.LeagueManagement)\n    ) {\n      await interaction.editReply({\n        embeds: [\n          createErrorEmbed(\n            \"❌ Insufficient Permissions\",\n            \"Only **Founder** or **League Management** can complete transfers.\"\n          ),\n        ],\n      });\n      return;\n    }\n\n    const transferId = interaction.options.getString(\"transfer_id\", true);\n\n    try {\n      const transfer = await prisma.transfer.findUnique({\n        where: { id: transferId },\n        include: { player: { include: { user: true } } },\n      });\n\n      if (!transfer) {\n        await interaction.editReply({\n          embeds: [createErrorEmbed(\"❌ Transfer Not Found\", `Transfer ID **${transferId}** not found.`)],\n        });\n        return;\n      }\n\n      if (transfer.status !== \"Pending\") {\n        await interaction.editReply({\n          embeds: [createErrorEmbed(\"❌ Invalid Status\", `This transfer is already **${transfer.status}**.`)],\n        });\n        return;\n      }\n\n      // Update the player's team\n      if (transfer.toTeamId) {\n        await teamService.addPlayerToTeam(transfer.playerId, transfer.toTeamId);\n      } else {\n        await teamService.removePlayerFromTeam(transfer.playerId);\n      }\n\n      // Mark transfer as completed\n      await prisma.transfer.update({\n        where: { id: transferId },\n        data: {\n          status: \"Completed\",\n          completedAt: new Date(),\n        },\n      });\n\n      // ── Auto-post transfer news ──\n      try {\n        if (interaction.guild) {\n          await newsService.announceTransfer(\n            interaction.client as ExtendedClient,\n            {\n              guildId: interaction.guild.id,\n              playerName: transfer.player.user.username,\n              fromTeam: transfer.fromTeamName ?? \"Free Agent\",\n              toTeam: transfer.toTeamName ?? \"Free Agent\",\n              fee: transfer.fee ? `$${transfer.fee}M` : undefined,\n            }\n          );\n        }\n      } catch (newsError) {\n        console.error(\"[Transfer News Error]\", newsError);\n        // Non-fatal\n      }\n\n      const embed = new EmbedBuilder()\n        .setTitle(\"✅ Transfer Completed!\")\n        .setColor(\"#00AA00\")\n        .addFields(\n          { name: \"👤 Player\", value: transfer.player.user.username, inline: true },\n          { name: \"➡️ From\", value: transfer.fromTeamName ?? \"Free Agent\", inline: true },\n          { name: \"🏠 To\", value: transfer.toTeamName ?? \"Free Agent\", inline: true },\n          { name: \"💰 Fee\", value: transfer.fee ? `$${transfer.fee}M` : \"Free Transfer\", inline: true }\n        )\n        .setFooter({ text: \"Legacy Football Championship\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Transfer Complete Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while completing the transfer.\",\n      });\n    }\n  },\n};\n\nexport default command;","src/commands/transfer/list.ts":"import {\n  SlashCommandBuilder,\n  CommandInteraction,\n  EmbedBuilder,\n} from \"discord.js\";\nimport { prisma } from \"../../database/prisma.js\";\nimport type { Command } from \"../../types/index.js\";\n\nconst command: Command = {\n  data: new SlashCommandBuilder()\n    .setName(\"transfers\")\n    .setDescription(\"View recent completed transfers\"),\n\n  async execute(interaction: CommandInteraction) {\n    if (!interaction.isChatInputCommand()) return;\n    await interaction.deferReply();\n\n    try {\n      const transfers = await prisma.transfer.findMany({\n        where: { status: \"Completed\" },\n        include: {\n          player: { include: { user: true } },\n        },\n        orderBy: { completedAt: \"desc\" },\n        take: 10,\n      });\n\n      if (transfers.length === 0) {\n        await interaction.editReply({\n          content: \"📋 No completed transfers yet.\",\n        });\n        return;\n      }\n\n      const embed = new EmbedBuilder()\n        .setTitle(\"🔄 Recent Transfers\")\n        .setColor(\"#00AA00\")\n        .setDescription(\n          transfers\n            .map(\n              (t, i) =>\n                `${i + 1}. **${t.player.user.username}**` +\n                `: ${t.fromTeamName ?? \"Free Agent\"} → ${t.toTeamName ?? \"Free Agent\"}` +\n                (t.fee ? ` ($${t.fee}M)` : \" (Free)\")\n            )\n            .join(\"\\n\")\n        )\n        .setFooter({ text: \"Legacy Football Championship\" })\n        .setTimestamp();\n\n      await interaction.editReply({ embeds: [embed] });\n    } catch (error) {\n      console.error(\"[Transfers List Error]\", error);\n      await interaction.editReply({\n        content: \"❌ An error occurred while fetching transfers.\",\n      });\n    }\n  },\n};\n\nexport default command;"};

